import type { CultureArticle } from "../types";

const items: CultureArticle[] = [{"id":"asa-059","version":2,"slug":"pchum-ben-feeding-the-ancestors-for-fifteen-days","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"بشوم بن: إطعام الأسلاف خمسة عشر يوماً","de":"Pchum Ben: fünfzehn Tage für die Ahnen","en":"Pchum Ben: feeding the ancestors for fifteen days"},"deck":{"ar":"في كمبوديا تفتح أبواب العالم السفلي، فتخرج العائلات قبل الفجر بالطعام إلى المعابد لتصل إلى أقاربها الراحلين.","de":"In Kambodscha öffnen sich die Tore der Unterwelt, und Familien bringen vor Sonnenaufgang Speisen in die Pagoden, um ihre Verstorbenen zu erreichen.","en":"In Cambodia the gates of the underworld open, and families carry food to pagodas before dawn to reach relatives who have died."},"teaser":{"ar":"مهرجان بوذي يجمع الإيمان بالأسلاف والرحلة إلى الأقاليم؛ خمسة عشر يوماً يمتلئ فيها الناس بالطعام والقراءة واللقاء.","de":"Ein buddhistisches Fest verbindet Ahnenverehrung mit Reisen in die Heimatprovinzen; fünfzehn Tage voller Speisen, Gesänge und Begegnungen.","en":"A Buddhist festival ties ancestor belief to journeys home; for fifteen days, food, chanting and rare family reunions fill the temples."},"readingMinutes":1,"sections":{"ar":[{"heading":"طعام قبل الفجر","paragraphs":["بشوم بن مهرجان بوذي كمبودي يقام في الشهر القمري العاشر، وتقدّم فيه العائلات قرابين لأقاربها الراحلين على مدى نحو خمسة عشر يوماً.","يحمل الناس الأرز والحلويات والفواكه إلى المعابد، ويرتل الرهبان؛ وبعض العائلات تزور عدة معابد لتصل إلى أسلاف ربما انتقلوا إلى مكان آخر.","ويعتقد أن أبواب العالم السفلي تُفتح فت search الأرواح الجائعة عن القرابين، وأن التقصير في فعل الخير قد يترك الأقارب يتعذبون."]},{"heading":"طريق العودة إلى البيت","paragraphs":["هذا المهرجان من أكبر مواسم السفر في السنة، إذ يعود الناس إلى أقاليمهم وقبور عائلاتهم، وتمتلئ المعابد قبل الفجر.","وهو يمزج الممارسة البوذية التيرافادية بمعتقدات الأسلاف السابقة للبوذية، كما أنه مناسبة اجتماعية يلتقي فيها الأقارب البعيدون.","تختلف التوقيتات والعادات المحلية بين بلدية ومعبد وآخر، ولا يلتزم الجميع به، وكثيراً ما تكتفي العائلات المدنية بالمال أو الطعام بدل حضور الأسبوعين كاملين، مع اختلاف واضح بين الأجيال في ذلك."]}],"de":[{"heading":"Essen vor dem Morgengrauen","paragraphs":["Pchum Ben ist ein kambodschanisches buddhistisches Fest im zehnten Mondmonat, bei dem Familien ihren verstorbenen Angehörigen etwa fünfzehn Tage lang Opfer darbringen.","Die Menschen bringen Reis, Süßspeisen und Obst in die Pagoden, Mönche rezitieren; manche Familien besuchen mehrere Tempel, um Ahnen zu erreichen, die vielleicht weitergezogen sind.","Der Glaube besagt, dass sich die Tore der Unterwelt öffnen und hungrige Geister nach Gaben suchen, sodass versäumte Verdienste die Verstorbenen leiden lassen könnten."]},{"heading":"Der Weg zurück nach Hause","paragraphs":["Das Fest ist eine der größten Reisezeiten des Jahres: Menschen kehren in ihre Heimatprovinzen und zu den Familiengräbern zurück, und die Pagoden füllen sich vor der Dämmerung.","Es verbindet theravada-buddhistische Praxis mit vor-buddhistischem Ahnen glauben und ist zugleich ein gesellschaftlicher Anlass, bei dem sich entfernte Verwandte treffen.","Zeitpunkt und lokale Bräuche unterscheiden sich je nach Gemeinde und Tempel, und nicht alle Kambodschaner begehen das Fest; städtische Familien geben oft Geld oder Essen statt der vollen zwei Wochen, wobei die Unterschiede zwischen den Generationen deutlich sind."]}],"en":[{"heading":"Food before sunrise","paragraphs":["Pchum Ben is a Cambodian Buddhist festival in the tenth lunar month, when families make offerings to deceased relatives over about fifteen days.","People bring rice, sweet cakes and fruit to pagodas, and monks chant; some families visit several temples to reach ancestors who may have moved on.","The belief is that the gates of the underworld open and hungry spirits search for offerings, so failing to make merit could leave relatives suffering."]},{"heading":"The road back home","paragraphs":["The festival is one of the year's biggest travel periods, as people return to home provinces and family graves, and pagodas fill before dawn.","It combines Theravada Buddhist practice with pre-Buddhist ancestor beliefs, and it is also a social occasion for distant relatives to meet.","Timing and local customs vary by commune and temple, and observance is not universal among Cambodians; urban families often give money or food rather than attend a full fortnight, and younger relatives sometimes join for only a day or two."]}]},"context":{"countries":["KH"],"region":"Cambodia","continent":"asia","languages":["km"],"period":"contemporary"},"tags":["beliefs-and-folklore","Cambodia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pchum Ben","de":"Pchum Ben","en":"Pchum Ben"},"url":"https://en.wikipedia.org/wiki/Pchum_Ben","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Buddhism in Cambodia","de":"Buddhism in Cambodia","en":"Buddhism in Cambodia"},"url":"https://en.wikipedia.org/wiki/Buddhism_in_Cambodia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"قبل شروق الشمس تحمل عائلة سلال كرات الأرز إلى معبد، وتقدمها للرهبان وتسكب الماء على الأرض للأسلاف، ثم تتشارك وجبة مع أقارب لا تراهم إلا مرة في السنة.","de":"Vor Sonnenaufgang trägt eine Familie Körbe mit Reiskugeln zu einer Pagode, opfert sie den Mönchen und gießt Wasser auf die Erde für die Ahnen, dann teilt sie eine Mahlzeit mit Verwandten, die sie nur einmal im Jahr sieht.","en":"Before sunrise a family carries baskets of rice balls to a pagoda, offers them to monks and pours water on the ground for ancestors, then shares a meal with relatives they see once a year."},"misunderstanding":{"ar":"ليس بشوم بن احتفالاً واحداً في يوم واحد، ولا هو مجرد طقس ديني؛ إنه فترة طويلة من الزيارات والتنقل والعناية بالأقارب الأحياء والأموات معاً.","de":"Pchum Ben ist kein einzelner Feiertag und nicht nur ein religiöses Ritual; es ist eine lange Zeit der Besuche, des Reisens und der Fürsorge für lebende und verstorbene Verwandte zugleich.","en":"Pchum Ben is not a single day or purely a religious ritual; it is a long stretch of visiting, travelling and caring for living and dead relatives at once."},"comparison":{"ar":"يشبه في روحه زيارات المقابر التي تعرفها مجتمعات أخرى، لكنه يمتد أياماً ويقوم على الذهاب إلى المعبد وفعل الخير لا على زيارة القبر وحده.","de":"Im Geist ähnelt es Grabvisiten anderer Gesellschaften, doch es dauert viele Tage und beruht auf dem Gang zur Pagode und guten Taten, nicht nur auf dem Besuch am Grab.","en":"In spirit it resembles grave-visiting customs elsewhere, but it lasts many days and rests on going to the pagoda and making merit, not only on tending a grave."}},{"id":"asa-060","version":2,"slug":"the-krama-one-scarf-a-hundred-uses","contentType":"note","category":"clothing-and-design","title":{"ar":"الكرامة: وشاح واحد بمئة استعمال","de":"Die Krama: ein Schal, hundert Aufgaben","en":"The Krama: One Scarf, a Hundred Uses"},"deck":{"ar":"في كمبوديا، الوشاح القطني المخطط أداة يومية أكثر منه زينة، يرافق الفلاح وسائق التوك توك والموظف على حد سواء.","de":"In Kambodscha ist der karierte Baumwollschal kein Schmuckstück, sondern ein Werkzeug, das Bauern, Tuk-Tuk-Fahrer und Beamte täglich begleitet.","en":"In Cambodia the checked cotton scarf is less an accessory than a tool, carried daily by farmers, tuk-tuk drivers and officials alike."},"teaser":{"ar":"الكرامة قطعة قماش قطنية مربعة الشكل ترافق الكمبوديين في العمل والراحة، وتحمل في طيّاتها ذكريات معقدة ورمزية وطنية.","de":"Die Krama begleitet Khmer beim Arbeiten und Ausruhen, trägt nationale Symbolik und birgt zugleich schwierige Erinnerungen an die Zeit der Roten Khmer.","en":"The krama travels through Khmer daily life as head cover, towel and baby hammock, carrying both national pride and difficult memories."},"readingMinutes":1,"sections":{"ar":[{"heading":"قطعة قماش تؤدي كل المهام","paragraphs":["الكرامة وشاح قطني منسوج، غالباً بمربعات حمراء وبيضاء أو زرقاء وبيضاء، يرتديه الخمير في كمبوديا. يُستخدم غطاءً للرأس ووشاحاً للكتف ومنشفة وسلة ومهداً معلقاً للأطفال وحشوة للأحمال، ما يجعله أقرب إلى أداة منه إلى إكسسوار.","تختلف الأنماط والألوان بحسب المنطقة والجنس والمناسبة، وقد صار الكرامة رمزاً للهوية الكمبودية. وتتفاوت طريقة استعماله بين الأجيال والمناطق، إذ يبقى في القرى أساسياً بينما يقتصر في المدن أحياناً على المناسبات."]},{"heading":"ذاكرة معقدة وحاضر متغيّر","paragraphs":["خلال سنوات الخمير الحمر ارتداه الكوادر، واستُخدم أيضاً لحمل المتعلقات في عمليات التهجير القسري، فاكتسب ذكريات مركّبة لا تُقرأ بالطريقة نفسها عند الجميع.","اليوم يُباع للسياح ويرتديه الفلاحون وسائقو التوك توك والمسؤولون، مع منافسة من أوشحة مستوردة أرخص، كثير منها مصنوع في المصانع لا منسوج يدوياً."]}],"de":[{"heading":"Ein Tuch, das fast alles kann","paragraphs":["Die Krama ist ein gewebter Baumwollschal, meist rot-weiß oder blau-weiß kariert, den Khmer in Kambodscha tragen. Sie dient als Kopfbedeckung, Schultertuch, Handtuch, Korb, Babyhängematte und Polster für Lasten – eher ein Werkzeug als ein Accessoire.","Muster und Farben können Region, Geschlecht und Anlass anzeigen; die Krama gilt als Symbol kambodschanischer Identität. Wie sie genutzt wird, unterscheidet sich je nach Region und Generation: Auf dem Land bleibt sie alltäglich, in Städten oft auf bestimmte Anlässe beschränkt."]},{"heading":"Schwierige Erinnerung und Wandel","paragraphs":["In den Jahren der Roten Khmer trugen Kadermitglieder die Krama; bei Zwangsumsiedlungen diente sie auch zum Tragen von Habseligkeiten. So bekam sie vielschichtige Erinnerungen, die nicht alle gleich deuten.","Heute wird sie an Touristen verkauft und von Bauern, Tuk-Tuk-Fahrern und Beamten getragen, während billigere importierte Schals mit handgewebten konkurrieren – viele davon fabrikmäßig hergestellt."]}],"en":[{"heading":"A cloth that does nearly everything","paragraphs":["The krama is a woven cotton scarf, usually red-and-white or blue-and-white checked, worn by Khmer in Cambodia. It serves as head covering, shoulder cloth, towel, basket, hammock for babies and padding for loads, which makes it more a tool than an accessory.","Patterns and colours can indicate region, gender and occasion, and the krama has become a symbol of Cambodian identity. How it is used varies by region and generation: in villages it stays everyday, while in cities it is sometimes reserved for certain occasions."]},{"heading":"Complex memory and a changing present","paragraphs":["During the Khmer Rouge years the krama was worn by cadre and also used to carry belongings during forced evacuations, giving it complex memories that not everyone reads the same way.","Today it is sold to tourists and worn by farmers, tuk-tuk drivers and officials, though cheaper imported scarves compete with hand-woven versions, and the tourist kind is often factory-made."]}]},"context":{"countries":["KH"],"region":"Cambodia","continent":"asia","languages":["km"],"period":"contemporary"},"tags":["clothing-and-design","Cambodia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Krama","de":"Krama","en":"Krama"},"url":"https://en.wikipedia.org/wiki/Krama","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Cambodia","de":"Cambodia","en":"Cambodia"},"url":"https://en.wikipedia.org/wiki/Cambodia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يلفّ سائق توك توك كرامة حول عنقه عند الفجر، ويستخدم ثانية لتظليل راكب، ويربط ثالثة بالإطار لحمل إطار احتياطي.","de":"Ein Tuk-Tuk-Fahrer wickelt sich im Morgengrauen eine Krama um den Hals, nutzt eine zweite als Sonnenschutz für den Fahrgast und bindet eine dritte an den Rahmen, um den Ersatzreifen zu halten.","en":"A tuk-tuk driver wraps a krama around his neck at dawn, uses a second one to shade a passenger, and ties a third to the frame to hold a spare tyre."},"misunderstanding":{"ar":"يُظن أحياناً أن الكرامة مجرد تذكار سياحي، مع أن وظيفتها العملية اليومية هي جوهرها.","de":"Manchmal gilt die Krama nur als Touristensouvenir, obwohl ihr praktischer Alltagsnutzen ihr Kern ist.","en":"It is sometimes assumed the krama is merely a tourist souvenir, although its practical everyday function is the heart of it."},"comparison":{"ar":"مثل المنديل الكبير أو الشال العملي في مجتمعات أخرى، تؤدي الكرامة أدواراً متعددة في آن واحد.","de":"Ähnlich wie ein großes Tuch oder ein praktischer Schal anderswo erfüllt die Krama mehrere Aufgaben zugleich.","en":"Like a large cloth or practical shawl elsewhere, the krama performs several jobs at once."}},{"id":"asa-061","version":2,"slug":"utang-na-loob-the-debt-that-cannot-be-paid-with-money","contentType":"note","category":"family-and-friendship","title":{"ar":"دين الامتنان الذي لا يُسدَّد بالمال","de":"Die Dankesschuld, die man nicht mit Geld begleicht","en":"The debt that money cannot repay"},"deck":{"ar":"في الفلبين، يعني 'أوتانغ نا لوب' دينًا من الداخل، يُرد بالوفاء والخدمة، ويشكّل شبكة دعم تُثقل كاهل البعض.","de":"Utang na loob auf den Philippinen ist eine Schuld der inneren Person, die durch Loyalität und Dienst getilgt wird und familiäre Netze prägt.","en":"Utang na loob in the Philippines is a debt of one's inner self, repaid through loyalty and service, shaping family and friendship bonds."},"teaser":{"ar":"دين لا يُقاس بالمال، بل بالولاء والخدمة. كيف يعيش الفلبينيون هذا الالتزام في العائلة والصداقة؟","de":"Eine Schuld, die nicht in Geld gemessen wird, sondern in Loyalität und Dienst. Wie prägt sie das Leben philippinischer Familien?","en":"A debt measured not in money but in loyalty and service. How does this Filipino value shape family life and social ties?"},"readingMinutes":1,"sections":{"ar":[{"heading":"دين من الداخل","paragraphs":["في الفلبين، 'أوتانغ نا لوب' هو دين امتنان تجاه من ساعد في وقت الحاجة؛ العبارة تعني دين النفس الداخلية. ليس التزامًا ماليًا ولا يُسدَّد بردّ المال، بل يُحمل كرابطة دائمة.","يُرد هذا الدين بالولاء والخدمة والمساعدة المستقبلية. يختلف تفسيره بين الأجيال وفي المدن والأرياف، حيث يتفاوض الشباب الحضريون عليه بشكل مختلف."]},{"heading":"امتداد العائلة","paragraphs":["المفهوم محوري في حياة الأسرة: يُنظر إلى الأبناء كمدينين لوالديهم مدى الحياة، ويرتبط الأشقاء والعرّابون بشبكات من الالتزام. هو مصدر دعم متبادل، لكنه قد يصبح عبئًا، إذ إن رفض طلب من محسنٍ مكلف اجتماعيًا. يعتبره علم النفس الفلبيني قيمة أساسية إلى جانب 'باكيكيساما' (الانسجام) و'هيا' (الحياء)."]}],"de":[{"heading":"Eine Schuld des Inneren","paragraphs":["Utang na loob ist eine philippinische Vorstellung von Dankesschuld gegenüber jemandem, der in einer Notlage geholfen hat; der Ausdruck bedeutet Schuld des inneren Selbst. Sie ist keine finanzielle Verpflichtung und wird nicht durch Rückzahlung beglichen, sondern als dauerhafte Bindung getragen.","Zurückgezahlt wird sie durch Loyalität, Dienst und künftige Hilfe. Regional und generationell wird sie unterschiedlich ausgehandelt: Jüngere Stadtbewohner interpretieren sie anders als Menschen auf dem Land."]},{"heading":"Ein familiäres Netz","paragraphs":["Das Konzept ist zentral für das Familienleben: Kinder gelten als lebenslang ihren Eltern verpflichtet, Geschwister und Paten sind in Netze von Verpflichtungen eingebunden. Es kann gegenseitige Unterstützung sein und auch Last, denn die Ablehnung einer Bitte eines Wohltäters ist sozial kostspielig. Die philippinische Psychologie zählt utang na loob neben pakikisama (Harmonie) und hiya (Scham) zu den Kernwerten."]}],"en":[{"heading":"A debt of the inner self","paragraphs":["Utang na loob is a Filipino idea of a debt of gratitude owed to someone who helped in a time of need; the phrase means a debt of one's inner self. It is not a financial obligation and is not settled by repayment; it is carried as a lasting bond.","It is repaid through loyalty, service and future help. The concept varies by region and generation: younger urban Filipinos negotiate it differently from those in rural areas."]},{"heading":"A family web of obligation","paragraphs":["The concept is central to family life: children are seen as owing their parents for life, and siblings and godparents are tied into webs of obligation. It can be a source of mutual support and also a burden, as refusing a request from a benefactor is socially costly. Filipino psychology treats utang na loob as one of several core values alongside pakikisama (getting along) and hiya (shame)."]}]},"context":{"countries":["PH"],"region":"Philippines","continent":"asia","languages":["tl"],"period":"contemporary"},"tags":["family-and-friendship","Philippines"],"sources":[{"organization":"Wikipedia","title":{"ar":"Utang na loob","de":"Utang na loob","en":"Utang na loob"},"url":"https://en.wikipedia.org/wiki/Utang_na_loob","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Filipino values","de":"Filipino values","en":"Filipino values"},"url":"https://en.wikipedia.org/wiki/Filipino_values","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"امرأة ساعدتها عمتها في الجامعة، فقدمت لاحقًا لابن عمتها وظيفة، وتعتبر العائلة ذلك سدادًا لدين لم يكن ماليًا قط.","de":"Eine Frau, der eine Tante das Studium ermöglichte, gibt später deren Sohn eine Stelle – die Familie sieht darin die Tilgung einer nie finanziellen Schuld.","en":"A woman who was helped through university by an aunt later gives that aunt's son a job, and the family treats this as repayment of a debt that was never financial."},"misunderstanding":{"ar":"يُفهم أحيانًا خطأً كدين مالي يمكن إسقاطه بالمال، لكنه في جوهره رابطة أخلاقية مستمرة.","de":"Manchmal wird es fälschlich als finanzielle Schuld verstanden, die man mit Geld abtragen kann, doch es ist eine fortbestehende moralische Bindung.","en":"It is sometimes mistaken for a financial debt that can be cleared with money, but it is a continuing moral bond."},"comparison":{"ar":"يشبه الامتنان في ثقافات أخرى، لكنه هنا يتحول إلى التزام اجتماعي ممتد عبر الأجيال.","de":"Ähnlich wie Dankbarkeit in anderen Kulturen, wird hier jedoch zu einer generationenübergreifenden sozialen Verpflichtung.","en":"Similar to gratitude in other cultures, but here it becomes a lasting social obligation across generations."}},{"id":"asa-062","version":2,"slug":"balikbayan-boxes-migration-packed-into-a-cardboard-box","contentType":"note","category":"migration-and-identity","title":{"ar":"صناديق باليكبايان: الهجرة في كرتونة","de":"Balikbayan-Boxen: Migration im Karton","en":"Balikbayan boxes: migration packed in cardboard"},"deck":{"ar":"صناديق كرتونية ترسلها العائلات من الخارج إلى الفلبين، تحمل ملابس وطعامًا وألعابًا، وتحمل معها حضورًا لا تستطيع التذاكر أن تشتريه.","de":"Kartons, die philippinische Familien aus dem Ausland nach Hause schicken, gefüllt mit Kleidung, Essen und Spielzeug – und mit einer Anwesenheit, die kein Flugticket kauft.","en":"Cardboard cargo boxes sent home by overseas Filipinos carry clothes, food and toys, and with them a kind of presence that no plane ticket can buy."},"teaser":{"ar":"للمهاجرين الفلبينيين طريقة خاصة ليكونوا في البيت رغم الغياب: صندوق كرتوني يسافر بدلًا منهم.","de":"Wer weit weg arbeitet, schickt einen Karton nach Hause. So sind philippinische Migranten präsent, auch wenn sie nicht reisen können.","en":"For Filipino migrant workers, a cardboard box can stand in for a homecoming, carrying what a family needs and what absence takes away."},"readingMinutes":1,"sections":{"ar":[{"heading":"صندوق يسافر بدل الإنسان","paragraphs":["صندوق باليكبايان صندوق شحن كرتوني يرسله الفلبينيون العاملون في الخارج إلى ذويهم، مملوءًا بالملابس والطعام والألعاب والأدوات المنزلية. وكلمة باليكبايان تعني العودة إلى الوطن، فالصندوق وسيلة ليحضر العامل المهاجر في بيته حين تعجز عنه الرحلة.","تجمع شركات الشحن الصناديق وتنقلها في حاويات إلى عناوين المحافظات، وللأغراض الشخصية المرسلة بهذه الطريقة امتياز معفي من الضرائب. وتختلف الإجراءات الجمركية وشركات الشحن بحسب المكان والزمن، كما تتباين العادة بين جيل وآخر وبين منطقة وأخرى."]},{"heading":"طقس عائلي واقتصاد بلد","paragraphs":["إرسال الصندوق طقس عائلي: يكتب الأقارب قائمة بما يحتاجون، ويسدّ المرسل الثغرات، ويُصوَّر وصول الصندوق ويُشارَك مع الأهل والأصدقاء.","تعكس هذه العادة حجم هجرة العمل الفلبينية واقتصاد التحويلات المالية الذي يشكل نصيبًا كبيرًا من الدخل الوطني.","لكن ليس كل مهاجر يرسل صناديق؛ فالعادة تتركز بين من يستطيعون تحمل كلفة الشحن، وهي جزئيًا طقس عائلي من الطبقة الوسطى."]}],"de":[{"heading":"Ein Karton reist statt eines Menschen","paragraphs":["Eine Balikbayan-Box ist ein Karton, den im Ausland arbeitende Filipinos an Verwandte schicken, gefüllt mit Kleidung, Lebensmitteln, Spielzeug und Haushaltswaren. Das Wort balikbayan bedeutet Rückkehr ins Land; die Box lässt den Migranten zu Hause anwesend sein, wenn die Reise nicht möglich ist.","Frachtfirmen sammeln die Kartons, verschiffen sie in Containern und liefern sie an Provinzadressen; für so versandte persönliche Sachen gilt ein Steuerprivileg. Zollregeln und Frachtfirmen unterscheiden sich je nach Ort und Zeit, und die Praxis variiert zwischen Generationen und Regionen."]},{"heading":"Familienritual und Volkswirtschaft","paragraphs":["Das Senden ist ein Familienritual: Verwandte notieren, was sie brauchen, der Absender füllt Lücken, und die Ankunft wird fotografiert und geteilt.","Die Praxis spiegelt das Ausmaß der philippinischen Arbeitsmigration und die Rücküberweisungswirtschaft, die einen großen Teil des Nationaleinkommens ausmacht.","Doch nicht jeder Migrant schickt Boxen; die Praxis konzentriert sich auf jene, die sich den Versand leisten können, und ist teils ein Ritual der Mittelschicht."]}],"en":[{"heading":"A box travels instead of a person","paragraphs":["A balikbayan box is a cardboard cargo box sent home by overseas Filipinos, filled with clothes, food, toys and household goods for relatives. The word balikbayan means returning to the country, and the box is a way for migrant workers to be present at home even when they cannot travel.","Cargo companies collect the boxes, ship them in containers and deliver them to provincial addresses; personal effects sent this way carry a tax-free privilege. Customs rules and cargo firms vary by place and period, and the practice shifts between generations and regions."]},{"heading":"A family ritual and a national economy","paragraphs":["Sending a box is a family ritual: relatives list what they need, the sender fills the gaps, and the arrival is photographed and shared.","The practice reflects the scale of Filipino labour migration and the economy of remittances, which accounts for a large share of national income.","Not every migrant sends boxes; the practice is concentrated among workers who can afford shipping, and it is partly a middle-class family ritual."]}]},"context":{"countries":["PH"],"region":"Philippines","community":"Overseas Filipino workers","continent":"asia","languages":["tl","en"],"period":"contemporary"},"tags":["migration-and-identity","Philippines"],"sources":[{"organization":"Wikipedia","title":{"ar":"Balikbayan box","de":"Balikbayan box","en":"Balikbayan box"},"url":"https://en.wikipedia.org/wiki/Balikbayan_box","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Overseas Filipino Worker","de":"Overseas Filipino Worker","en":"Overseas Filipino Worker"},"url":"https://en.wikipedia.org/wiki/Overseas_Filipino_Worker","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"ممرضة فلبينية في دبي تحزم صندوقًا فيه شوكولاتة وأحذية وشامبو وجهاز لوحي لابن أختها، تسلمه لمكتب شحن قبل عيد الميلاد بثمانية أسابيع، وتتابع رحلته حتى يصل إلى كاغايان دي أورو.","de":"Eine philippinische Krankenschwester in Dubai packt Schokolade, Schuhe, Shampoo und ein Tablet für ihren Neffen in einen Karton, gibt ihn acht Wochen vor Weihnachten bei einer Frachtfirma ab und verfolgt die Sendung bis Cagayan de Oro.","en":"A Filipino nurse in Dubai packs a box with chocolate, shoes, shampoo and a tablet for her nephew, drops it at a cargo office eight weeks before Christmas, and tracks it as it lands in Cagayan de Oro."},"misunderstanding":{"ar":"يُظن أن الصندوق مجرد هدية، لكنه في العمق تعبير عن الحضور والانتماء حين يغيب الجسد.","de":"Man hält die Box für ein bloßes Geschenk, doch sie ist vor allem ein Ausdruck von Anwesenheit und Zugehörigkeit, wenn der Körper fehlt.","en":"The box is often read as a simple gift, but it is really a claim of presence and belonging when the body cannot make the trip."},"comparison":{"ar":"يشبه الصندوق رسالة طويلة ترسلها العائلة إلى نفسها، لكنه أثقل وزنًا وأكثر تفصيلًا في احتياجات البيت اليومية.","de":"Die Box gleicht einem langen Brief der Familie an sich selbst, nur schwerer und genauer an den täglichen Bedürfnissen des Hauses.","en":"It works like a long letter a family writes to itself, only heavier and far more precise about the everyday needs of a household."}},{"id":"asa-063","version":2,"slug":"mano-po-asking-an-elder-s-hand-for-a-blessing","contentType":"note","category":"communication","title":{"ar":"مانو بو: طلب البركة من يد الكبير","de":"Mano po: den Segen der Älteren erbitten","en":"Mano po: asking an elder's hand for a blessing"},"deck":{"ar":"إيماءة فلبينية بسيطة تجمع بين الاحترام الديني والدفء العائلي، حيث يضع الأصغر جبهته على يد الجد أو الجدة.","de":"Eine schlichte philippinische Geste, die Respekt und familiäre Wärme verbindet – die Hand eines Älteren wird an die eigene Stirn geführt.","en":"A simple Filipino gesture that joins religious respect with family warmth, as a younger person presses an elder's hand to their forehead."},"teaser":{"ar":"في الفلبين، يأخذ الصغير يد الكبير ويضعها على جبهته قائلاً «مانو بو»، طالباً البركة ومظهراً الاحترام.","de":"Auf den Philippinen nimmt ein Jüngerer die rechte Hand eines Älteren, führt sie zur Stirn und sagt „mano po“ – eine Bitte um Segen.","en":"In the Philippines a younger person takes an elder's right hand, touches it to the forehead and says mano po, asking for a blessing."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف تُؤدَّى الإيماءة","paragraphs":["يأخذ الشخص الأصغر يد الكبير اليمنى ويرفعها بلطف حتى تلامس جبهته، قائلاً «مانو بو». الكلمة تجمع بين «مانو» أي اليد، و«بو» أداة التأدب في التاغالوغ التي تظهر في الكلام اليومي أيضاً.","تتصل الإيماءة بالممارسة الكاثوليكية، إذ تُقبَّل اليد أو تُلمس، وتكثر في الأعياد ولمّات العائلة، خاصة عند لقاء الأجداد والعرابين والأقارب.","في صباح عيد الميلاد يصطف الأطفال ليأخذوا يد الجد، يلمسونها بجباههم ويقولون «مانو بو»، فينالون هدية وبركة. وتختلف الممارسة بحسب المنطقة والعائلة والجيل؛ فبعض العائلات تقتصر عليها مع الأقارب الكبار المقربين جداً."]},{"heading":"تراجع في المدن وبقاء في العائلة","paragraphs":["يتراجع استخدام الإيماءة في بعض العائلات المدنية، حيث يُفضَّل العناق أو التحية الكلامية، لكنها تصمد في سياقات العائلة الوثيقة.","نادراً ما يُتوقع من غير الفلبينيين أداؤها، ويبقى فهمها كافياً لإظهار التقدير.","بهذا تبقى «مانو بو» لغة جسد تحمل معنى الاحترام والانتماء أكثر مما تحمل مجرد تحية عابرة."]}],"de":[{"heading":"Wie die Geste ausgeführt wird","paragraphs":["Der Jüngere nimmt die rechte Hand des Älteren und führt sie sanft an die eigene Stirn, während er „mano po“ sagt. Das Wort verbindet „mano“ (Hand) mit „po“, dem Höflichkeitspartikel des Tagalog, das auch sonst Respekt im Sprechen markiert.","Die Geste ist mit katholischer Praxis verbunden, bei der die Hand geküsst oder berührt wird, und wird besonders an Feiertagen und Familienfesten ausgeführt, etwa bei Begegnungen mit Großeltern, Paten und Verwandten.","Am Weihnachtsmorgen stehen Kinder Schlange, um die Hand des Großvaters zu nehmen, sie an die Stirn zu führen und „mano po“ zu sagen; dafür erhalten sie ein Geschenk und einen Segen. Die Praxis variiert je nach Region, Familie und Generation; manche Familien nutzen sie nur bei sehr engen älteren Verwandten."]},{"heading":"Rückgang in der Stadt, Bestand in der Familie","paragraphs":["In manchen städtischen Familien geht die Nutzung zurück, wo eine Umarmung oder ein verbales Grußwort bevorzugt wird, doch in engen Familienkontexten bleibt sie bestehen.","Von Nicht-Filipinos wird sie selten erwartet; sie zu verstehen genügt, um Wertschätzung zu zeigen.","So bleibt „mano po“ eine Körpersprache, die Respekt und Zugehörigkeit trägt – mehr als ein flüchtiger Gruß."]}],"en":[{"heading":"How the gesture is performed","paragraphs":["The younger person takes the elder's right hand and gently brings it to their own forehead, saying mano po. The phrase combines mano (hand) with po, the Tagalog politeness particle that also marks respect in speech generally.","The gesture is related to Catholic practice, where the hand may be kissed or touched, and it is performed especially at holidays and family reunions, when meeting grandparents, godparents and relatives.","On Christmas morning children queue to take their grandfather's hand, touch it to their foreheads and say mano po, and in return they receive a gift and a blessing. Practice varies by region, family and religion; some families use it only with very close elder relatives."]},{"heading":"Fading in cities, lasting in the family","paragraphs":["The use is declining in some urban families, where a hug or a verbal greeting is preferred, but it persists in close family contexts.","Non-Filipinos are rarely expected to attempt it, and understanding it is enough to show appreciation.","So mano po remains a body language that carries respect and belonging, more than a passing greeting."]}]},"context":{"countries":["PH"],"region":"Philippines","continent":"asia","languages":["tl"],"period":"contemporary"},"tags":["communication","Philippines"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mano (gesture)","de":"Mano (gesture)","en":"Mano (gesture)"},"url":"https://en.wikipedia.org/wiki/Mano_(gesture)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Filipino language","de":"Filipino language","en":"Filipino language"},"url":"https://en.wikipedia.org/wiki/Filipino_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في صباح عيد الميلاد يصطف الأطفال ليأخذوا يد الجد، يلمسونها بجباههم ويقولون «مانو بو»، فينالون هدية وبركة.","de":"Am Weihnachtsmorgen stehen Kinder Schlange, um die Hand des Großvaters zu nehmen, sie an die Stirn zu führen und „mano po“ zu sagen; dafür erhalten sie ein Geschenk und einen Segen.","en":"On Christmas morning children queue to take their grandfather's hand, touch it to their foreheads and say mano po, and in return they receive a gift and a blessing."},"misunderstanding":{"ar":"قد يظن الغريب أنها مجرد مصافحة غريبة، لكنها في جوهرها طلب بركة وتأكيد لصلة القرابة والاحترام.","de":"Außenstehende halten sie oft für einen seltsamen Händedruck, doch im Kern ist sie eine Bitte um Segen und eine Bestätigung von Verwandtschaft und Respekt.","en":"Outsiders may read it as an odd handshake, but at its core it is a request for a blessing and a confirmation of kinship and respect."},"comparison":{"ar":"تشبه في وظيفتها تقبيل يد الكبير في بعض الثقافات العربية، حيث يُعبَّر عن الاحترام والطلب غير المباشر للبركة.","de":"Ihre Funktion ähnelt dem Küssen der Hand Älterer in manchen Kulturen, wo Respekt und indirekt um Segen gebeten wird.","en":"It functions like kissing an elder's hand in some cultures, where respect and an indirect request for blessing are expressed."},"expression":{"original":"Mano pô","language":"Tagalog","gloss":{"ar":"يدك، من فضلك — تحية تطلب البركة من الكبير","de":"Ihre Hand, bitte – ein Gruß, der einen Älteren um Segen bittet","en":"your hand, please - a greeting that asks an elder for a blessing"},"usage":{"ar":"تُقال أثناء وضع يد الكبير على الجبهة، خاصة عند لقاء الأجداد والعرابين في الأعياد.","de":"Wird gesagt, während die Hand des Älteren an die Stirn geführt wird, besonders bei Begegnungen mit Großeltern und Paten an Feiertagen.","en":"Said while bringing an elder's hand to the forehead, especially when meeting grandparents and godparents at holidays."},"transliteration":"mano pô"}},{"id":"asa-065","version":2,"slug":"mamak-stalls-malaysia-s-twenty-four-hour-social-kitchens","contentType":"scene","category":"food-and-hospitality","title":{"ar":"مطاعم ماماك: مطابخ ماليزيا الاجتماعية على مدار الساعة","de":"Mamak-Stände: Malaysias soziale Küchen rund um die Uhr","en":"Mamak stalls: Malaysia's twenty-four-hour social kitchens"},"deck":{"ar":"أكشاك ماماك على قارعة الطريق، يديرها مسلمون تاميل، تقدم الطعام والشراب على مدار الساعة وتعمل كمساحات اجتماعية مفتوحة للجميع.","de":"Mamak-Stände am Straßenrand, meist von tamilischen Muslimen betrieben, servieren rund um die Uhr Speisen und Getränke und dienen als offene soziale Räume.","en":"Roadside mamak stalls, run mostly by Tamil Muslims, serve food and drink around the clock and function as open social spaces for everyone."},"teaser":{"ar":"في ماليزيا وسنغافورة، تتحول أكشاك ماماك إلى غرف معيشة مفتوحة حيث يجتمع الناس على الشاي والروتي في أي ساعة.","de":"In Malaysia und Singapur werden Mamak-Stände zu offenen Wohnzimmern, wo Menschen zu jeder Stunde bei Tee und Roti zusammenkommen.","en":"In Malaysia and Singapore, mamak stalls become open living rooms where people gather over tea and roti at any hour."},"readingMinutes":1,"sections":{"ar":[{"heading":"أكثر من مجرد طعام","paragraphs":["تنتشر أكشاك ماماك على جوانب الطرق في شبه جزيرة ماليزيا وسنغافورة، ويديرها في الغالب مسلمون تاميل. تقدم روتي تشاناي وتيه تاريك ومي جورينج وناسي كاندار على مدار الساعة، وتفتح طاولاتها المكشوفة للرجال والنساء والعائلات على حد سواء.","تعمل هذه الأكشاك كمساحات اجتماعية: يتلكأ الناس على كوب شاي، يشاهدون كرة القدم، يناقشون السياسة ويأكلون في أي وقت. الطعام نفسه مزيج من الطبخ الهندي المسلم المكيف مع الأذواق المحلية، ومفرداته تمزج التاميلية والماليزية والإنجليزية وهوكين."]},{"heading":"حياة المدينة في طبق","paragraphs":["غالبًا ما تنحاز الأحياء إلى جانب أكشاك ماماك في نزاعات الترخيص، مما يظهر مدى انغماس هذا الشكل في الحياة الحضرية. يختلف الإقبال والطقوس حسب المنطقة والجيل، فالشباب قد يفضلون السهر حتى الفجر بينما تفضل العائلات ساعات المساء."]}],"de":[{"heading":"Mehr als nur Essen","paragraphs":["Mamak-Stände sind Straßenimbisse, die überwiegend von tamilischen Muslimen betrieben werden und auf der malaiischen Halbinsel sowie in Singapur verbreitet sind. Sie servieren Roti Canai, Teh Tarik, Mee Goreng und Nasi Kandar rund um die Uhr, und ihre Tische im Freien stehen Männern, Frauen und Familien gleichermaßen offen.","Der Stand fungiert als sozialer Raum: Menschen verweilen bei Tee, schauen Fußball, diskutieren Politik und essen zu jeder Stunde. Das Essen ist indisch-muslimische Küche, angepasst an lokale Geschmäcker, und sein Vokabular mischt Tamil, Malaiisch, Englisch und Hokkien."]},{"heading":"Stadtleben auf einem Teller","paragraphs":["Nachbarschaften ergreifen in Lizenzstreitigkeiten oft Partei für ihre Mamak-Stände, was zeigt, wie tief das Format im urbanen Leben verankert ist. Die Gewohnheiten variieren je nach Region und Generation – Jugendliche bleiben oft bis zum Morgengrauen, während Familien die Abendstunden bevorzugen."]}],"en":[{"heading":"More than just food","paragraphs":["Mamak stalls are roadside food stalls run mostly by Tamil Muslims, found across Peninsular Malaysia and Singapore. They serve roti canai, teh tarik, mee goreng and nasi kandar around the clock, and their open-air tables are open to men, women and families alike.","The stall works as a social space: people linger over tea, watch football, discuss politics and eat at any hour. The food is Indian-Muslim cooking adapted to local tastes, and its vocabulary mixes Tamil, Malay, English and Hokkien terms."]},{"heading":"City life on a plate","paragraphs":["Neighbourhoods often take their mamak stalls' side in licensing disputes, which shows how deeply the format is embedded in urban life. Habits vary by region and generation—young people may stay until dawn, while families prefer the evening hours."]}]},"context":{"countries":["MY","SG"],"region":"Peninsular Malaysia and Singapore","continent":"asia","languages":["ms","ta","en"],"period":"contemporary"},"tags":["food-and-hospitality","Peninsular Malaysia and Singapore"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mamak stall","de":"Mamak stall","en":"Mamak stall"},"url":"https://en.wikipedia.org/wiki/Mamak_stall","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Malaysian cuisine","de":"Malaysian cuisine","en":"Malaysian cuisine"},"url":"https://en.wikipedia.org/wiki/Malaysian_cuisine","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الواحدة صباحًا بعد وردية ليلية، يجلس سائق على طاولة بلاستيكية، يطلب روتي تشاناي وتيه تاريك، ويراقب حشدًا من الطلاب وسائقي سيارات الأجرة يفعلون الشيء نفسه.","de":"Um 1 Uhr nachts nach einer Nachtschicht sitzt ein Fahrer an einem Plastiktisch, bestellt Roti Canai und Teh Tarik und beobachtet eine Menge von Studenten und Taxifahrern, die dasselbe tun.","en":"At 1 a.m. after a night shift a driver sits at a plastic table, orders roti canai and teh tarik, and watches a crowd of students and taxi drivers do the same."},"misunderstanding":{"ar":"يظن البعض أن هذه الأكشاك مجرد أماكن للأكل السريع، لكنها في الواقع مساحات للبقاء والتواصل، وقد لا ترحب بعض الأحياء بها بسبب الترخيص.","de":"Manche halten diese Stände für reine Schnellimbisse, doch tatsächlich sind sie Orte des Verweilens und der Kommunikation; nicht jede Nachbarschaft heißt sie wegen unklarer Lizenzierung willkommen.","en":"Some assume these stalls are just quick eateries, but they are actually places for lingering and socializing; not every neighbourhood welcomes them due to uncertain licensing."},"comparison":{"ar":"بينما تقدم المطاعم الأخرى وجبات محددة بمواعيد، تظل أكشاك ماماك مفتوحة على مدار الساعة وتجمع بين وظيفة الطعام والاستراحة الاجتماعية.","de":"Während andere Restaurants feste Öffnungszeiten haben, bleiben Mamak-Stände durchgehend geöffnet und verbinden Essensfunktion mit sozialer Pause.","en":"While other restaurants keep fixed hours, mamak stalls stay open continuously and combine eating with a social pause."}},{"id":"asa-066","version":2,"slug":"singlish-the-creole-that-singapore-officially-discourages","contentType":"language","category":"languages","title":{"ar":"سنغليش: كريول سنغافورة غير الرسمي","de":"Singlish: Singapurs informeller Kreol","en":"Singlish: Singapore's unofficial creole"},"deck":{"ar":"لغة يومية تجمع بين الإنجليزية وهوكيين والماليزية والتاميلية، تستخدمها المجتمعات المحلية رغم الحملات الرسمية ضدها.","de":"Eine Alltagssprache aus Englisch, Hokkien, Malaiisch und Tamil, die trotz offizieller Kampagnen den Ton angibt.","en":"A everyday language blending English with Hokkien, Malay and Tamil, spoken widely despite official campaigns against it."},"teaser":{"ar":"في سنغافورة، يتحدث الناس سنغليش في الحياة اليومية، لكنهم يعودون إلى الإنجليزية الفصحى في العمل. كيف يعيش هذا التنوع اللغوي؟","de":"In Singapur sprechen viele im Alltag Singlish, im Büro wechseln sie zu Standardenglisch. Wie lebt diese Sprachvielfalt?","en":"In Singapore, many speak Singlish daily but switch to standard English at work. How does this linguistic diversity shape everyday life?"},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة الشارع والهوية","paragraphs":["السنغليش هو الإنجليزية العامية في سنغافورة، تشكلت بفعل تأثيرات هوكيين والماليزية والتاميلية ولغات أخرى. يستخدمه السنغافوريون في الأحاديث غير الرسمية، مع أدوات مثل lah وleh وmah وsia، وترتيب جمل مختلف مثل You eat already? وكلمات مختصرة.","رغم أن الحكومة أطلقت حركة Speak Good English Movement لتثبيط استخدامه في المدارس والمكاتب، يعتبر السنغليش علامة على الهوية الوطنية، ويظهر في الكوميديا والأفلام والمسلسلات المحلية."]},{"heading":"أدوات صغيرة بمعانٍ كبيرة","paragraphs":["هذه الأدوات تقوم بعمل نحوي حقيقي: Can lah تعني تقريبًا نعم، بالطبع، بينما Can or not? تسأل عما إذا كان شيء ممكنًا. وهكذا يحمل السنغليش وظائف لغوية دقيقة رغم بساطته الظاهرة."]}],"de":[{"heading":"Sprache der Straße und Identität","paragraphs":["Singlish ist das umgangssprachliche Englisch Singapurs, geprägt von Hokkien, Malaiisch, Tamil und anderen Sprachen. Es wird informell verwendet und ist durch Partikeln wie lah, leh, mah und sia sowie eine andere Satzstellung (z. B. You eat already?) und Abkürzungen gekennzeichnet.","Obwohl die Regierung mit der Speak Good English Movement Singlish in Schulen und Büros zurückdrängt, gilt es als Marker nationaler Identität und erscheint in Komödien sowie lokalen Filmen und Fernsehsendungen."]},{"heading":"Kleine Partikeln, große Wirkung","paragraphs":["Die Partikeln leisten echte grammatische Arbeit: Can lah bedeutet ungefähr ja, natürlich, während Can or not? fragt, ob etwas möglich ist. So erfüllt Singlish trotz seiner scheinbaren Einfachheit präzise sprachliche Funktionen."]}],"en":[{"heading":"Street language and identity","paragraphs":["Singlish is Singapore's colloquial English, shaped by Hokkien, Malay, Tamil and other languages. It is used informally between Singaporeans and marked by particles such as lah, leh, mah and sia, different sentence order (e.g., You eat already?) and abbreviated words.","Although the government's Speak Good English Movement discourages Singlish in schools and offices, it remains a marker of national identity, appearing in comedies and local films and television."]},{"heading":"Small particles, big meaning","paragraphs":["The particles do real grammatical work: Can lah means roughly yes, of course, while Can or not? asks whether something is possible. Thus Singlish carries precise linguistic functions despite its apparent simplicity."]}]},"context":{"countries":["SG"],"region":"Singapore","continent":"asia","languages":["en","zh","ms","ta"],"period":"contemporary"},"tags":["languages","Singapore"],"sources":[{"organization":"Wikipedia","title":{"ar":"Singlish","de":"Singlish","en":"Singlish"},"url":"https://en.wikipedia.org/wiki/Singlish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Singapore","de":"Languages of Singapore","en":"Languages of Singapore"},"url":"https://en.wikipedia.org/wiki/Languages_of_Singapore","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"نادل يسأل طاولة: You all want same order? فيرد صديق: Can lah, sama sama، ثم يعود الجميع إلى الإنجليزية الفصحى في المكتب لاحقًا.","de":"Ein Kellner fragt einen Tisch: You all want same order? Ein Freund antwortet: Can lah, sama sama, und später im Büro wechseln alle zurück zu Standardenglisch.","en":"A waiter asks a table You all want same order?; a friend replies Can lah, sama sama, and everyone switches back to standard English in the office later."},"misunderstanding":{"ar":"يُفهم أحيانًا أن السنغليش إنجليزية سيئة، لكنه في الواقع كريول له قواعده الخاصة وأدواته النحوية.","de":"Singlish wird oft für schlechtes Englisch gehalten, ist aber ein Kreol mit eigenen Regeln und grammatischen Partikeln.","en":"Singlish is sometimes mistaken for bad English, but it is a creole with its own rules and grammatical particles."},"comparison":{"ar":"مثل اللهجات العامية في مدن أخرى، يختلف السنغليش حسب العرق والعمر والطبقة، ومعظم السنغافوريين يبدلون بينه وبين الإنجليزية الفصحى حسب الموقف.","de":"Wie andere urbane Dialekte variiert Singlish nach Ethnie, Alter und Klasse; die meisten Singapurer wechseln je nach Situation zwischen ihm und Standardenglisch.","en":"Like other urban dialects, Singlish varies by ethnicity, age and class; most Singaporeans code-switch between it and standard English depending on context."},"expression":{"original":"Can lah!","language":"Singapore English","gloss":{"ar":"نعم، بالطبع - lah تؤكد وتضفي روح الزمالة","de":"ja, natürlich – lah betont und schafft Nähe","en":"yes, of course – lah marks emphasis and camaraderie"},"usage":{"ar":"تستخدم للموافقة بحماس أو تأكيد شيء ما في حديث غير رسمي.","de":"Wird verwendet, um zuzustimmen oder etwas in informellem Ton zu bekräftigen.","en":"Used to agree enthusiastically or affirm something in an informal tone."},"transliteration":"can lah"}},{"id":"asa-067","version":2,"slug":"kiasu-the-fear-of-losing-out-that-singapore-jokes-about","contentType":"note","category":"regional-humour","title":{"ar":"كياشو: الخوف من فوات الفرصة في سنغافورة","de":"Kiasu: Die Angst, etwas zu verpassen","en":"Kiasu: Singapore's Fear of Missing Out"},"deck":{"ar":"مصطلح هوكيين يعبر عن سباق يومي على كل شيء، من البوفيه إلى مواقف السيارات، مع نكات ذاتية.","de":"Ein hokkienischer Begriff für den täglichen Wettlauf um alles – vom Buffet bis zum Parkplatz –, oft mit Selbstironie.","en":"A Hokkien term for the daily scramble over everything from buffets to parking spots, often met with self-mockery."},"teaser":{"ar":"في سنغافورة، كلمة واحدة تصف الاندفاع لالتقاط الفرص قبل الآخرين، وتثير ضحكاً ونقاشاً.","de":"In Singapur beschreibt ein einziges Wort den Drang, Chancen vor anderen zu ergreifen, und sorgt für Lachen und Debatten.","en":"In Singapore, one word captures the urge to grab opportunities before others do, sparking both laughter and debate."},"readingMinutes":1,"sections":{"ar":[{"heading":"من أين جاءت الكلمة؟","paragraphs":["تأتي كلمة «كياشو» من لغة هوكيين وتعني الخوف من الخسارة، أي الرغبة في اقتناص السلع النادرة أو الميزة قبل أن يسبقك أحد.","تظهر في الطوابير والبوفيهات والتخفيضات والتسجيل المدرسي ومواقف السيارات، وغالباً ما تُستخدم بسخرية ذاتية.","يشير مصطلح «كياشو-إزم» في التعليقات الاجتماعية إلى العادات التنافسية للطبقة الوسطى في سنغافورة."]},{"heading":"بين النكتة والواقع","paragraphs":["حولت الحملات الوطنية والسلع والافلام والمشاهد الكوميدية كياشو إلى علامة تجارية للفكاهة المحلية.","لكن النقاد يرون أن اللقب قد يطمس قلقاً حقيقياً في مدينة غير متكافئة، ويرفض بعض السنغافوريين رؤية أنفسهم فيه.","يختلف استخدام المصطلح بين الأجيال والمناطق: فالشباب قد يرددونه ساخرين، بينما يراه كبار السن وصفاً لواقعهم اليومي."]}],"de":[{"heading":"Woher der Begriff kommt","paragraphs":["Kiasu stammt aus dem Hokkien und bedeutet Angst zu verlieren – der Drang, knappe Güter oder Vorteile zu ergreifen, bevor es jemand anderes tut.","Es taucht beim Anstehen, an Buffets, bei Sales, Schuleinschreibungen und Parkplätzen auf und wird oft selbstironisch verwendet.","Der verwandte Begriff Kiasu-ism beschreibt in der Sozialkritik die Wettbewerbsgewohnheiten der singapurischen Mittelschicht."]},{"heading":"Zwischen Witz und Wirklichkeit","paragraphs":["Nationale Kampagnen, Merchandise, Filme und Comedyskizzen haben Kiasu zu einer erkennbaren Marke lokalen Humors gemacht.","Kritiker merken an, dass das Etikett echte Ängste einer ungleichen Stadt verflachen kann, und manche Singapurer wollen sich darin nicht wiedererkennen.","Die Verwendung variiert regional und generationell: Jüngere sagen es spöttisch, Ältere sehen darin ihren Alltag beschrieben."]}],"en":[{"heading":"Where the word comes from","paragraphs":["Kiasu comes from Hokkien and means afraid to lose, describing the urge to grab scarce goods or advantage before someone else does.","It appears in queueing, buffets, sales, school enrolment and parking spots, and is often invoked with self-mockery.","A closely related term, kiasu-ism, is used in social commentary to describe the competitive habits of Singapore's middle class."]},{"heading":"Between joke and reality","paragraphs":["National campaigns, merchandise, films and comedy sketches have turned kiasu into a recognisable brand of local humour.","Critics note that the label can flatten real anxieties of an unequal city, and some Singaporeans refuse to see themselves in it.","Usage varies by region and generation: younger people say it wryly, while older residents see it as a description of their daily reality."]}]},"context":{"countries":["SG"],"region":"Singapore","continent":"asia","languages":["en","zh"],"period":"contemporary"},"tags":["regional-humour","Singapore"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kiasu","de":"Kiasu","en":"Kiasu"},"url":"https://en.wikipedia.org/wiki/Kiasu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Singapore","de":"Culture of Singapore","en":"Culture of Singapore"},"url":"https://en.wikipedia.org/wiki/Culture_of_Singapore","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عندما يفتح بوفيه فندق، يحمل الضيوف أطباقهم إلى المنضدة قبل الإعلان؛ تمزح عائلة بأنها «كياشو» جداً لكنها تنضم إلى الطابور.","de":"Wenn ein Hotelbuffet öffnet, tragen Gäste ihre Teller zur Theke, bevor es angekündigt wird; eine Familie scherzt, sehr kiasu zu sein, stellt sich aber trotzdem an.","en":"When a hotel buffet opens, guests carry plates to the counter before the announcement; a family jokes about being very kiasu but still joins the queue."},"misunderstanding":{"ar":"كياشو صورة نمطية لكلمة هوكيين من أصل مهاجر وليس سمة شخصية ثابتة؛ لا يتصرف الجميع بهذه الطريقة، والتنافسية تتشكل أيضاً بضغط تكاليف المعيشة والتعليم.","de":"Kiasu ist ein Stereotyp eines Hokkien-Begriffs mit Migrationsgeschichte, kein festes Persönlichkeitsmerkmal; nicht alle verhalten sich so, und Wettbewerb wird auch von Lebenshaltungskosten und Bildungsdruck geprägt.","en":"Kiasu is a stereotype of a diaspora-origin Hokkien term rather than a fixed personality trait; not everyone behaves this way, and competitiveness is also shaped by cost of living and education pressure."},"comparison":{"ar":"يشبه المصطلح تعبيرات محلية أخرى عن الاندفاع مثل «كياشو» في ماليزيا، لكنه في سنغافورة ارتبط أكثر بخطاب الطبقة الوسطى.","de":"Der Begriff ähnelt anderen lokalen Ausdrücken für Vordrängeln, doch in Singapur ist er stärker mit dem Mittelschichtdiskurs verbunden.","en":"The term resembles other local expressions for pushing ahead, but in Singapore it is more closely tied to middle-class commentary."}},{"id":"asa-068","version":2,"slug":"javanese-speech-levels-the-same-sentence-in-three-registers","contentType":"language","category":"languages","title":{"ar":"مستويات الكلام في الجاوية","de":"Javanische Sprachebenen im Alltag","en":"Javanese speech levels in daily life"},"deck":{"ar":"في جزيرة جاوة، تتغيّر الكلمات نفسها حسب من تخاطبه: نظام لغوي يحمل في طيّاته احترامًا يوميًا.","de":"Auf Java ändern sich dieselben Wörter je nach Gesprächspartner: ein Sprachsystem, das Respekt täglich trägt.","en":"On Java, the same words shift with the person you address: a language system that carries respect every day."},"teaser":{"ar":"لغة الجاوية تعرف ثلاث طبقات للكلام، ويختار المتحدثون مستواها بحسب الشخص المقابل، وقد يبدّلونها داخل الحوار الواحد.","de":"Javanisch kennt drei Sprachebenen, und Sprecher wählen sie nach Gegenüber – oft wechseln sie mitten im Gespräch die Ebene.","en":"Javanese has three speech levels, and speakers choose them by listener, often switching mid-conversation."},"readingMinutes":1,"sections":{"ar":[{"heading":"ثلاث طبقات في جملة واحدة","paragraphs":["تعرف لغة الجاوية نظامًا من مستويات الكلام: ngoko غير الرسمي مع الأقران والأصغر، وmadya الأوسط، وkrama المهذّب مع الكبار والغرباء. تتغيّر المفردات وتركيب الجملة بحسب المستوى، ففعل الأكل mangan في ngoko وdhahar في krama، ويمكن أن تنتقل المحادثة الواحدة بين المستويات.","يرتبط krama بآداب السلوك والرقيّ، ويُستعمل في الرسائل الرسمية والاحتفالات وعروض Wayang. ويختلف الأمر بحسب المنطقة والجيل، فليس كل متحدث يتحكم في النظام كاملًا."]},{"heading":"التعلّم بالتصحيح","paragraphs":["قد يكون اختيار المستوى الخاطئ إهانة، لذلك يتعلّم الأطفال النظام عبر تصحيح الكبار لهم وفي الصف المدرسي.","في المدن، يخلط متحدثو الجاوية المستويات باللغة الإندونيسية، ويستعمل كثير من الشباب ngoko في معظم حياتهم اليومية."]}],"de":[{"heading":"Drei Register in einem Satz","paragraphs":["Javanisch hat ein System von Sprachebenen: ngoko (informell, unter Gleichaltrigen und Jüngeren), madya (Mitte) und krama (verfeinert, gegenüber Älteren und Fremden). Wortschatz und Satzbau ändern sich mit dem Register: essen heißt mangan in ngoko und dhahar in krama, und ein Gespräch kann die Ebenen wechseln.","Krama gilt als höflich und fein und wird in formellen Briefen, Zeremonien und Wayang-Aufführungen verwendet. Je nach Region und Generation unterscheidet sich das jedoch, denn nicht alle beherrschen das ganze System."]},{"heading":"Lernen durch Korrektur","paragraphs":["Die falsche Ebene kann beleidigen, deshalb lernen Kinder das System durch Korrektur von Erwachsenen und im Unterricht.","In Städten mischen javanische Sprecher die Ebenen mit Indonesisch, und viele junge Menschen nutzen ngoko im Alltag überwiegend."]}],"en":[{"heading":"Three registers in one sentence","paragraphs":["Javanese has a system of speech levels: ngoko (informal, used with peers and inferiors), madya (middle) and krama (refined, used with elders and strangers). Vocabulary and syntax change with the register: to eat is mangan in ngoko and dhahar in krama, and a single conversation can switch levels.","Krama is associated with etiquette and refinement, and it is used in formal letters, ceremonies and wayang performance. Yet this varies by region and generation, and many speakers control only part of the system."]},{"heading":"Learning through correction","paragraphs":["Choosing the wrong level can be insulting, so children learn the system through correction by adults and in the classroom.","In cities, Javanese speakers increasingly mix levels with Indonesian, and many young people use ngoko in most of daily life."]}]},"context":{"countries":["ID"],"region":"Java","continent":"asia","languages":["id","jv"],"period":"contemporary"},"tags":["languages","Java"],"sources":[{"organization":"Wikipedia","title":{"ar":"Javanese language","de":"Javanese language","en":"Javanese language"},"url":"https://en.wikipedia.org/wiki/Javanese_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Javanese script","de":"Javanese script","en":"Javanese script"},"url":"https://en.wikipedia.org/wiki/Javanese_script","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب جاويّ يتحدث ngoko مع أصدقائه، ثم ينتقل إلى krama لتحية معلّمه، وبعدها إلى krama المهذّب مع الجدّ المحترم في البيت.","de":"Ein javanischer Student spricht ngoko mit Freunden, wechselt zu krama für die Begrüßung der Lehrerin und später zu verfeinertem krama gegenüber dem verehrten Großvater zu Hause.","en":"A Javanese student speaks ngoko with friends, then shifts to krama for a teacher's greeting, and later to refined krama for the respected grandfather at home."},"misunderstanding":{"ar":"يظن بعض الغرباء أن المستويات مجرد مرادفات فخمة، لكنها في الحقيقة اختيار اجتماعي دقيق يعبّر عن العلاقة والاحترام.","de":"Manche halten die Ebenen für bloß vornehme Synonyme, doch sie sind eine soziale Wahl, die Beziehung und Respekt ausdrückt.","en":"Outsiders sometimes think the levels are just fancy synonyms, but they are a precise social choice expressing relationship and respect."},"comparison":{"ar":"يشبه الأمر اختيار صيغة المخاطبة في لغات أخرى، لكنه في الجاوية يمتد إلى المفردات كلها لا إلى الضمائر وحدها.","de":"Ähnlich wie die Anrede in anderen Sprachen, doch im Javanischen betrifft es den ganzen Wortschatz, nicht nur Pronomen.","en":"It resembles address forms in other languages, but in Javanese it runs through the whole vocabulary, not only pronouns."},"expression":{"original":"ꦩꦠꦸꦂꦤꦸꦮꦸꦤ꧀","language":"basa Jawa","gloss":{"ar":"شكرًا - في مستوى krama المهذّب","de":"danke – im höflichen krama-Register","en":"thank you – in the polite krama register"},"usage":{"ar":"تُقال عند الشكر في موقف رسمي أو مع شخص أكبر سنًّا.","de":"Wird beim Danken in formellen oder respektvollen Situationen gesagt.","en":"Said when thanking someone in formal or respectful situations."},"transliteration":"matur nuwun"}},{"id":"asa-069","version":2,"slug":"mudik-the-homecoming-that-empties-the-cities","contentType":"note","category":"migration-and-identity","title":{"ar":"العودة إلى البيت في العيد","de":"Mudik: die Heimkehr, die Städte leert","en":"Mudik: the homecoming that empties cities"},"deck":{"ar":"في نهاية رمضان تعود ملايين الأسر الإندونيسية إلى قراها، فتُفرغ المدن الكبرى وتزدحم الطرق بالدراجات والحافلات والعبارات.","de":"Zum Ende des Ramadan fahren Millionen Indonesier in ihre Heimatdörfer zurück; die Großstädte leeren sich, Straßen füllen sich mit Motorrädern, Bussen und Fähren.","en":"At the end of Ramadan millions of Indonesians travel back to their home villages; the big cities thin out while roads fill with motorbikes, buses and ferries."},"teaser":{"ar":"رحلة قد تستغرق ساعات أو أيامًا، لكنها واجب اجتماعي: لقاء الأهل وطلب المغفرة في القرية.","de":"Eine Reise, die Stunden oder Tage dauern kann – aber eine soziale Pflicht: Familienfeiern, neue Kleidung und Vergebung im Heimatdorf.","en":"A trip that can take hours or days, but it is a social obligation: family celebrations, new clothes and asking forgiveness in the home village."},"readingMinutes":1,"sections":{"ar":[{"heading":"لماذا يعود الناس إلى القرية؟","paragraphs":["تُعرف هذه العادة في إندونيسيا باسم «موديك»، وهي العودة إلى البلدة أو القرية الأصلية عند العيد في نهاية صيام رمضان. الرحلة قد تكون قصيرة أو طويلة جدًا، ويسافر الملايين بالدراجة النارية والحافلة والقطار والعبارة والسيارة، فتضيف شركات النقل خدمات إضافية.","العودة واجب اجتماعي: احتفالات عائلية وملابس جديدة وطلب الصفح من الوالدين والجيران، كل ذلك يجري في قرية الأصل. وتختلف تفاصيل هذا الواجب من أسرة إلى أخرى، كما تتباين العادة بين الأجيال والمناطق."]},{"heading":"طريق مزدحم واقتصاد يعود مع الناس","paragraphs":["تنسّق الحكومة السفر مع حراسات الشرطة وضبط الأسعار، وتظل حوادث الطرق — خصوصًا لقوافل الدراجات النارية — مصدر قلق متكرر.","«موديك» اقتصاد عودة أيضًا: أموال تُرسل إلى البيت وتُنفق في القرى، ولقاء مؤقت بين أطفال وأجداد يعيشون بعيدًا بعضهم عن بعض."]}],"de":[{"heading":"Warum Menschen in ihr Dorf zurückkehren","paragraphs":["In Indonesien heißt diese Praxis „Mudik“: die Rückkehr in die Heimatstadt oder das Heimatdorf zu Lebaran, dem Ende des Fastenmonats Ramadan. Die Reise kann kurz oder enorm lang sein; Millionen fahren mit Motorrad, Bus, Zug, Fähre und Auto, und Betreiber setzen zusätzliche Verbindungen ein.","Die Rückkehr ist eine soziale Verpflichtung: Familienfeiern, neue Kleidung und das Bitten um Vergebung bei Eltern und Nachbarn finden im Heimatdorf statt. Wie verbindlich das ist, unterscheidet sich je nach Familie, Region und Generation."]},{"heading":"Voller Weg, heimkehrende Wirtschaft","paragraphs":["Die Regierung koordiniert die Reisen mit Polizeibegleitung und Preiskontrollen; Verkehrsunfälle – besonders bei Motorradkonvois – bleiben ein wiederkehrendes Problem.","Mudik ist auch eine Heimkehr-Ökonomie: Geld wird nach Hause geschickt und in den Dörfern ausgegeben, Kinder und Großeltern, die getrennt leben, sehen sich vorübergehend wieder."]}],"en":[{"heading":"Why people return to the village","paragraphs":["In Indonesia this practice is called mudik: returning to one's home town or village at Lebaran, the end of the Ramadan fast. The trip can be short or enormously long; millions travel by motorbike, bus, train, ferry and car, and operators add extra services.","Returning is a social obligation: family celebrations, new clothes and asking forgiveness from parents and neighbours all happen in the home village. How binding this feels varies by family, region and generation."]},{"heading":"A crowded road and a homecoming economy","paragraphs":["The government coordinates travel with police escorts and fare controls, and traffic accidents — especially for motorbike convoys — are a recurring concern.","Mudik is also a homecoming economy: money sent home and spent in villages, and a temporary reunion of children and grandparents who live apart."]}]},"context":{"countries":["ID"],"region":"Indonesia","continent":"asia","languages":["id"],"period":"contemporary"},"tags":["migration-and-identity","Indonesia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mudik","de":"Mudik","en":"Mudik"},"url":"https://en.wikipedia.org/wiki/Mudik","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Lebaran","de":"Lebaran","en":"Lebaran"},"url":"https://en.wikipedia.org/wiki/Lebaran","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عامل في مصنع بجاكرتا يقطع أربع عشرة ساعة على دراجة نارية مع زوجته وطفله ضمن قافلة ترافقها الشرطة، حاملًا كيس هدايا إلى بيت والديه.","de":"Ein Fabrikarbeiter in Jakarta fährt mit Frau und Kind 14 Stunden auf dem Motorrad in einem polizeibegleiteten Konvoi, eine Tasche mit Geschenken für das Haus seiner Eltern dabei.","en":"A factory worker in Jakarta rides a motorbike with his wife and child for 14 hours through a police-escorted convoy, carrying a bag of gifts to his parents' house."},"misunderstanding":{"ar":"ليس الجميع قادرًا على تحمّل تكاليف الرحلة، وقد اهتزّ هذا النمط في سنوات الجائحة؛ فالحجم والاهتمام الإعلامي يتغيران من عام إلى آخر.","de":"Nicht alle können sich die Heimreise leisten, und die Pandemiejahre unterbrachen das Muster; Umfang und Medienaufmerksamkeit schwanken von Jahr zu Jahr.","en":"Not everyone can afford to travel home, and the pandemic years disrupted the pattern; the scale and media attention vary by year."},"comparison":{"ar":"يشبه هذا التقليد عادات العودة إلى مسقط الرأس في أعياد أخرى حول العالم، لكنه يتميّز بحجمه الضخم وارتباطه الوثيق بنهاية رمضان.","de":"Ähnliche Heimkehrrituale gibt es zu anderen Festen weltweit, doch Mudik besticht durch seine schiere Größe und die enge Bindung an das Ramadanende.","en":"Other festivals around the world also send people back to their roots, but mudik stands out for its sheer scale and its tight link to the end of Ramadan."}},{"id":"asa-070","version":2,"slug":"kampong-ayer-a-water-village-in-the-middle-of-brunei-s-capital","contentType":"note","category":"cities-and-community","title":{"ar":"كامبونغ آير: قرية على الماء في قلب العاصمة","de":"Kampong Ayer: ein Wasserdorf im Herzen der Hauptstadt","en":"Kampong Ayer: a water village in the capital"},"deck":{"ar":"حياة يومية على أعمدة خشبية فوق نهر بروناي، حيث تصل الممرات الخشبية بين البيوت وتعمل القوارب كسيارات أجرة.","de":"Alltag auf Holzpfählen über dem Brunei-Fluss, wo Stege die Häuser verbinden und Boote als Taxis dienen.","en":"Daily life on wooden stilts over the Brunei River, where plank walkways link homes and boats serve as taxis."},"teaser":{"ar":"في قلب بروناي، تقف قرية كامبونغ آير شاهدة على حياة مائية عمرها قرون، حيث لا تزال العائلات تعيش وتعمل وتتعلم فوق النهر.","de":"Mitten in Brunei liegt Kampong Ayer, ein jahrhundertealtes Wasserdorf, in dem Familien noch heute über dem Fluss leben, arbeiten und zur Schule gehen.","en":"In the heart of Brunei, Kampong Ayer is a centuries-old water village where families still live, work and learn above the river."},"readingMinutes":1,"sections":{"ar":[{"heading":"حياة على الأعمدة","paragraphs":["تقع كامبونغ آير على نهر بروناي، مقابل العاصمة بندر سري بكاوان. في ذروتها، سكنها عشرات الآلاف. تربطها ممرات خشبية، ويتنقل السكان بالقوارب أو سيارات الأجرة المائية. بُنيت المدارس والعيادات والمساجد على الماء.","كانت القرية مركزًا تجاريًا قديمًا، ومنها جاء لقب «بندقية الشرق» الذي استخدمه الرحالة الأوائل. بعد الحرب العالمية الثانية، انتقل كثيرون إلى الأرض، لكن القرية ما زالت مأهولة وتُروَّج كموقع تراثي."]},{"heading":"صيانة وسلامة","paragraphs":["الحياة على الماء ليست حنينًا فقط: صيانة البيوت الخشبية والسلامة من الحرائق هما شاغلان يوميان. يختلف الوضع حسب المنطقة والأجيال؛ فبعض العائلات تبقى لتراثها، وأخرى تنتقل لأسباب عملية."]}],"de":[{"heading":"Leben auf Pfählen","paragraphs":["Kampong Ayer liegt am Brunei-Fluss, direkt gegenüber der Hauptstadt Bandar Seri Begawan. Zu Spitzenzeiten wohnten hier Zehntausende. Holzstege verbinden die Häuser, die Menschen fahren mit Booten oder Wassertaxis. Schulen, Kliniken und Moscheen wurden auf dem Wasser gebaut.","Die Siedlung war ein jahrhundertealter Handelsort und gab dem Beinamen „Venedig des Ostens“ seinen Namen, den frühe Reisende verwendeten. Nach dem Zweiten Weltkrieg zogen viele an Land, doch das Wasserdorf bleibt bewohnt und wird als Kulturerbestätte gefördert."]},{"heading":"Wartung und Feuerschutz","paragraphs":["Das Leben auf dem Wasser ist nicht nur Nostalgie: Die Instandhaltung der Pfahlhäuser und der Brandschutz sind ständige praktische Sorgen. Je nach Region und Generation unterscheidet sich die Lage; manche Familien bleiben wegen des Erbes, andere ziehen aus praktischen Gründen fort."]}],"en":[{"heading":"Life on stilts","paragraphs":["Kampong Ayer sits on the Brunei River, directly opposite the capital Bandar Seri Begawan. At its peak it was home to tens of thousands of people. Plank walkways connect the houses, and residents travel by boat or water taxi. Schools, clinics and mosques have been built on the water.","The settlement is a centuries-old trading village and gave its name to the “Venice of the East” nickname used by early travellers. After the Second World War many residents moved to land, but the water village remains populated and is promoted as a heritage site."]},{"heading":"Maintenance and fire safety","paragraphs":["Life on the water is not nostalgia only: maintenance of stilt houses and fire safety are constant practical concerns. Conditions vary by area and generation; some families stay for heritage, while others move for practical reasons."]}]},"context":{"countries":["BN"],"region":"Bandar Seri Begawan","continent":"asia","languages":["ms"],"period":"contemporary"},"tags":["cities-and-community","Bandar Seri Begawan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kampong Ayer","de":"Kampong Ayer","en":"Kampong Ayer"},"url":"https://en.wikipedia.org/wiki/Kampong_Ayer","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Brunei","de":"Brunei","en":"Brunei"},"url":"https://en.wikipedia.org/wiki/Brunei","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طفل يسير إلى المدرسة على ممر خشبي من بيت على الماء، يعبر جسرًا للمشاة، ثم يأخذ سيارة أجرة مائية إلى درس بعد المدرسة على ضفة النهر.","de":"Ein Kind geht von einem Pfahlhaus über einen Steg zur Schule, überquert eine Fußgängerbrücke und nimmt ein Wassertaxi zu einem Nachmittagskurs am Flussufer.","en":"A child walks to school along a plankway from a stilt house, crosses a footbridge, and takes a water taxi to an after-school class on the riverbank."},"misunderstanding":{"ar":"يظن البعض أن القرية مجرد صورة تاريخية، لكنها أصغر وأكثر حداثة اليوم، مع مياه أنابيب وكهرباء، وليست كل العائلات تعيش هناك باختيارها.","de":"Viele halten das Dorf für ein reines Historienbild, doch es ist heute kleiner und moderner, mit fließendem Wasser und Strom; nicht alle Bewohner leben freiwillig dort.","en":"Many assume the village is purely historic, but it is smaller and more modern today, with piped water and electricity; not all residents live there by choice."},"comparison":{"ar":"مثل أحياء عائمة أخرى في آسيا، تجمع كامبونغ آير بين حياة يومية عملية ورمزية تراثية، لكن قربها من العاصمة يجعل خدماتها أكثر انتظامًا.","de":"Wie andere schwimmende Viertel in Asien verbindet Kampong Ayer praktischen Alltag mit kultureller Symbolkraft, doch die Nähe zur Hauptstadt sorgt für geregeltere Versorgung.","en":"Like other floating neighbourhoods in Asia, Kampong Ayer blends practical daily life with heritage symbolism, but its proximity to the capital means more regular services."}},{"id":"asa-071","version":2,"slug":"tetun-timor-leste-s-everyday-language-between-portuguese-and-malay","contentType":"language","category":"languages","title":{"ar":"التيتوم: لغة الحياة اليومية في تيمور الشرقية","de":"Tetun: Alltagssprache zwischen Portugiesisch und Malaiisch","en":"Tetun: Timor-Leste's language between Portuguese and Malay"},"deck":{"ar":"بين البرتغالية والماليزية، وجد التيتوم طريقه ليصبح لسان الناس في السوق والمدرسة والبيت.","de":"In Timor-Leste trägt Tetun den Alltag – auf dem Markt, in der Schule und zu Hause, zwischen zwei Amtssprachen und vielen Einflüssen.","en":"In Timor-Leste, Tetun carries everyday life through markets, classrooms and homes, layered with Portuguese and Indonesian history."},"teaser":{"ar":"لغة يتحدثها معظم سكان تيمور الشرقية، تحمل طبقات من التاريخ البرتغالي والإندونيسي، وتتبدل نبرتها بين المدينة والريف.","de":"Die meistgesprochene Sprache Timor-Lestes trägt Spuren portugiesischer und indonesischer Geschichte und klingt in Stadt und Land unterschiedlich.","en":"The most widely spoken language of Timor-Leste bears traces of Portuguese and Indonesian rule and sounds different in town and countryside."},"readingMinutes":1,"sections":{"ar":[{"heading":"لسانٌ يجمع طبقات التاريخ","paragraphs":["التيتوم هو أكثر اللغات انتشارًا في تيمور الشرقية وإحدى لغتيها الرسميتين إلى جانب البرتغالية. يعيش في سجلّين: تيتوم ديلي، الخليط الحضري من التيتوم والبرتغالية والماليزية في الحياة اليومية، وتيتوم تيريك، الصيغة الريفية الأكثر محافظة.","خلال الحكم الإندونيسي كُبِحت اللغة في المدارس، وبعد الاستقلال عام 2002 صارت رمزًا للهوية الوطنية.","توفّر البرتغالية مفردات الإدارة والتعليم، بينما تهيمن الإندونيسية والإنجليزية على مصطلحات الأعمال والتقنية. ويختلف إتقان اللغة واستخدامها اختلافًا حادًّا بين المدينة والريف وبين الأجيال."]},{"heading":"عدة ألسنة في يوم واحد","paragraphs":["يعترف الدستور أيضًا بمجموعة من لغات العمل، ومعظم التيموريين يتحدثون عدة لغات بين البيت والمدرسة والحكومة.","في مدرسة في ديلي يبدأ اليوم بتحية بالتيتوم، ويستخدم الدرس كتبًا برتغالية، ويمزح الأطفال بخليط التيتوم والماليزية في الساحة.","تبقى البرتغالية عقبة أمام كثيرين، وقرارات اللغة في التعليم موضع جدل مستمر."]}],"de":[{"heading":"Eine Sprache mit vielen Schichten","paragraphs":["Tetun ist die am weitesten verbreitete Sprache Timor-Lestes und neben Portugiesisch eine der beiden Amtssprachen. Es gibt zwei Register: Tetun Dili, die städtische Mischung aus Tetun, Portugiesisch und Malaiisch im Alltag, und Tetun Terik, eine konservativere ländliche Variante.","Unter indonesischer Herrschaft wurde die Sprache in den Schulen unterdrückt; nach der Unabhängigkeit 2002 wurde sie zum Symbol nationaler Identität.","Portugiesisch liefert Verwaltungs- und Bildungswortschatz, Indonesisch und Englisch prägen Wirtschaft und Technik. Sprachkompetenz und Gebrauch unterscheiden sich stark zwischen Stadt und Land und je nach Generation."]},{"heading":"Mehrere Sprachen an einem Tag","paragraphs":["Die Verfassung erkennt zudem mehrere Arbeitssprachen an, und die meisten Timoresen sprechen mehrere Sprachen zwischen Haus, Schule und Regierung.","In einer Schule in Dili beginnt der Tag mit einem Gruß auf Tetun, der Unterricht nutzt portugiesische Lehrbücher, und die Kinder scherzen im Tetun-Malaiisch-Mix des Pausenhofs.","Portugiesisch bleibt für viele eine Hürde, und Sprachentscheidungen in der Bildung sind umstritten."]}],"en":[{"heading":"A language built in layers","paragraphs":["Tetun is the most widely spoken language of Timor-Leste and one of its two official languages, alongside Portuguese. It exists in two main registers: Tetun Dili, the urban mix of Tetun, Portuguese and Malay used in daily life, and Tetun Terik, a more conservative rural variety.","Under Indonesian rule the language was suppressed in schools, and after independence in 2002 it became a symbol of national identity.","Portuguese supplies administration and education vocabulary, while Indonesian and English dominate business and technology terms. Language competence and use differ sharply between town and country and by generation."]},{"heading":"Several languages in one day","paragraphs":["The constitution also recognises a set of working languages, and most Timorese speak several languages across home, school and government.","A school in Dili begins with a greeting in Tetun, the lesson uses Portuguese textbooks, and the children joke in the Tetun-Malay mix of the playground.","Portuguese remains a barrier for many, and decisions about language in education are contested."]}]},"context":{"countries":["TL"],"region":"Timor-Leste","continent":"asia","languages":["pt"],"period":"contemporary"},"tags":["languages","Timor-Leste"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tetun language","de":"Tetun language","en":"Tetun language"},"url":"https://en.wikipedia.org/wiki/Tetun_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Timor-Leste","de":"Languages of Timor-Leste","en":"Languages of Timor-Leste"},"url":"https://en.wikipedia.org/wiki/Languages_of_Timor-Leste","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مدرسة في ديلي تبدأ بتحية بالتيتوم، والدرس يستخدم كتبًا برتغالية، والأطفال يمزحون بخليط التيتوم والماليزية في الساحة.","de":"Eine Schule in Dili beginnt mit einem Gruß auf Tetun, der Unterricht nutzt portugiesische Lehrbücher, und die Kinder scherzen im Tetun-Malaiisch-Mix des Pausenhofs.","en":"A school in Dili begins with a greeting in Tetun, the lesson uses Portuguese textbooks, and the children joke in the Tetun-Malay mix of the playground."},"misunderstanding":{"ar":"يُظنّ أن التيتوم لغة واحدة موحّدة، لكنه في الواقع سجلّان يتباينان بين المدينة والريف.","de":"Man hält Tetun oft für eine einheitliche Sprache, doch es sind zwei Register, die sich zwischen Stadt und Land unterscheiden.","en":"People often assume Tetun is one uniform language, but it is two registers that differ between city and countryside."},"comparison":{"ar":"كما تتعايش اللغات في تيمور الشرقية، تتعايش العربية الفصحى واللهجات المحلية في كثير من المجتمعات.","de":"Wie Tetun und Portugiesisch in Timor-Leste nebeneinander bestehen, leben auch Hochdeutsch und Dialekte in vielen Regionen zusammen.","en":"Just as Tetun and Portuguese coexist in Timor-Leste, standard and dialect forms coexist in many speech communities."},"expression":{"original":"Bondia","language":"Tetun","gloss":{"ar":"صباح الخير - من البرتغالية bom dia","de":"guten Morgen – von portugiesisch bom dia","en":"good morning – from Portuguese bom dia"},"usage":{"ar":"تحية صباحية شائعة في ديلي، تُظهر أثر البرتغالية في الكلام اليومي.","de":"Ein häufiger Morgengruß in Dili, der den portugiesischen Einfluss im Alltag zeigt.","en":"A common morning greeting in Dili, showing Portuguese influence in everyday speech."},"transliteration":"bondia"}},{"id":"asa-072","version":2,"slug":"nowruz-the-spring-new-year-that-crosses-borders","contentType":"note","category":"traditions","title":{"ar":"نوروز: ربيع يعبر الحدود","de":"Nowruz: Frühling über Grenzen hinweg","en":"Nowruz: spring crossing borders"},"deck":{"ar":"عيد رأس السنة الفارسية والآسيوية الوسطى يجمع الأسر حول مائدة واحدة ويجدد صلة الجيران والأقارب.","de":"Das Neujahrsfest persischer und zentralasiatischer Tradition bringt Familien an einen Tisch und erneuert die Bindung zwischen Nachbarn und Verwandten.","en":"The Persian and Central Asian new year brings families to one table and renews ties between neighbours and relatives."},"teaser":{"ar":"من تنظيف البيوت إلى طبخ الحبوب سبع ليال، يحتفل الناس في آسيا الوسطى بالاعتدال الربيعي بطرق مختلفة لكن بروح واحدة.","de":"Vom Putzen der Häuser bis zum nächtelangen Kochen von Weizenkeimen: In Zentralasien feiern Menschen die Frühlings-Tagundnachtgleiche auf unterschiedliche Weise, aber mit ähnlichem Geist.","en":"From cleaning houses to cooking wheat sprouts overnight, people across Central Asia mark the spring equinox in different ways but with a shared spirit."},"readingMinutes":1,"sections":{"ar":[{"heading":"استعدادات تبدأ قبل الأسابيع","paragraphs":["يبدأ التحضير لنوروز قبل أسابيع من موعده في العشرين أو الحادي والعشرين من مارس: تنظيف البيوت، شراء ملابس جديدة، وإنبات حبوب القمح في أطباق صغيرة.","تجتمع الأسر حول مائدة احتفالية بأطعمة رمزية، وتختلف الأطباق من بلد إلى آخر بحسب اللغة والعادات المحلية.","يختلف حجم الاحتفال وأسلوبه بين الأجيال والمناطق، فبعض العائلات تحيي التفاصيل كلها وأخرى تكتفي بالزيارة والمائدة."]},{"heading":"مائدة تجمع الجيران","paragraphs":["في كازاخستان وقيرغيزستان تُطبخ أطباق خاصة، وفي أوزبكستان يتبادل الجيران الزيارات بالدور، بينما تحتفظ البيوت الأفغانية بمائدة «هفت‌ميوه».","أضافت اليونسكو نوروز إلى قائمة التراث غير المادي عام 2009، لما له من دور في تقوية الروابط المجتمعية واستمرار الثقافة.","عُورض العيد في آسيا الوسطى إبان الحكم السوفيتي، ثم عاد بعد 1991 عيداً رسمياً ورمزاً وطنياً."]}],"de":[{"heading":"Vorbereitungen Wochen im Voraus","paragraphs":["Wochen vor dem 20. oder 21. März beginnt die Vorbereitung: Häuser werden geputzt, neue Kleidung gekauft und Weizenkörner in kleinen Schalen zum Keimen gebracht.","Familien decken einen festlichen Tisch mit symbolischen Speisen; die Gerichte unterscheiden sich je nach Land, Sprache und lokaler Gewohnheit.","Umfang und Stil der Feier variieren nach Region und Generation: Manche Familien begehen alle Einzelheiten, andere beschränken sich auf Besuch und Tafel."]},{"heading":"Eine Tafel, die Nachbarn verbindet","paragraphs":["In Kasachstan und Kirgisistan kocht man besondere Gerichte, in Usbekistan besuchen sich Nachbarn der Reihe nach, während afghanische Haushalte den Haft-Mewa-Tisch pflegen.","2009 nahm die UNESCO Nowruz in die Liste des immateriellen Erbes auf, wegen seiner Rolle für Gemeinschaftsbindung und kulturelle Kontinuität.","Unter sowjetischer Herrschaft wurde das Fest in Zentralasien zurückgedrängt; nach 1991 kehrte es als Feiertag und nationales Symbol zurück."]}],"en":[{"heading":"Preparations weeks in advance","paragraphs":["Preparation begins weeks before 20 or 21 March: homes are cleaned, new clothes bought, and wheat grains are grown in small dishes.","Families set a festive table with symbolic foods, and the dishes differ from country to country according to language and local custom.","The scale and style of celebration vary by region and generation: some families keep every detail, others simply visit and share the table."]},{"heading":"A table that gathers neighbours","paragraphs":["In Kazakhstan and Kyrgyzstan families cook special dishes, in Uzbekistan neighbours visit in turn, while Afghan households keep the haft-mewa table.","UNESCO added Nowruz to its intangible heritage list in 2009, citing its role in strengthening community ties and cultural continuity.","Under Soviet rule the holiday was discouraged in Central Asia, and it revived after 1991 as a public holiday and national symbol."]}]},"context":{"countries":["KZ","KG","UZ","TJ","TM","AF"],"region":"Central Asia","continent":"asia","languages":["fa","tg","uz","kk","ky","tk"],"period":"contemporary"},"tags":["traditions","Central Asia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Nowruz","de":"Nowruz","en":"Nowruz"},"url":"https://en.wikipedia.org/wiki/Nowruz","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Central Asia","de":"Central Asia","en":"Central Asia"},"url":"https://en.wikipedia.org/wiki/Central_Asia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في ألماتي تنظف أسرة بيتها وتطبخ «نوروز كوجه» بسبعة مكونات وتزور الكبار؛ وفي دوشنبه يتبادل الجيران أطباق السمالك المطبوخ طوال الليل.","de":"In Almaty putzt eine Familie das Haus, kocht Nauryz Koshe mit sieben Zutaten und besucht die Älteren; in Duschanbe tauschen Nachbarn Teller mit über Nacht gekochtem Sumalak.","en":"In Almaty a family cleans the house, cooks nauryz kozhe with seven ingredients and visits elders; in Dushanbe neighbours exchange plates of sumalak cooked overnight."},"misunderstanding":{"ar":"كثيرون يظنون أن نوروز عيد ديني واحد أو تقليد موحّد، والحقيقة أنه تراث متنوع تختلف أسماؤه وأطعمته وطقوسه بحسب البلد واللغة والدين.","de":"Viele halten Nowruz für ein einziges religiöses Fest oder eine einheitliche Tradition; tatsächlich sind Namen, Speisen und Rituale je nach Land, Sprache und Religion verschieden.","en":"Many assume Nowruz is one religious feast or a single uniform tradition; in fact names, foods and rituals vary by country, language and religion."},"comparison":{"ar":"يشترك الجميع في فكرة التجديد والاعتدال الربيعي، لكن المائدة والزيارات والأطباق تتباين بين كازاخستان وأفغانستان وأوزبكستان.","de":"Alle teilen die Idee von Erneuerung und Frühlings-Tagundnachtgleiche, doch Tafel, Besuche und Gerichte unterscheiden sich zwischen Kasachstan, Afghanistan und Usbekistan.","en":"Everyone shares the idea of renewal and the spring equinox, yet the table, visits and dishes differ between Kazakhstan, Afghanistan and Uzbekistan."}},{"id":"asa-073","version":2,"slug":"buzkashi-the-mounted-game-played-at-a-full-gallop","contentType":"note","category":"games-and-leisure","title":{"ar":"بزكشي: لعبة الفرسان في العراء","de":"Buzkashi: Reiterspiel im Galopp","en":"Buzkashi: The Mounted Game at a Full Gallop"},"deck":{"ar":"لعبة تقليدية على ظهر الخيل تجمع بين الشجاعة والتنافس، يمارسها الرجال في آسيا الوسطى وأفغانستان.","de":"Ein traditionelles Spiel zu Pferd, das Mut und Wettkampfgeist vereint und in Zentralasien und Afghanistan von Männern gespielt wird.","en":"A traditional horseback game of courage and competition, played by men in Central Asia and Afghanistan."},"teaser":{"ar":"في بزكشي، يتسابق الفرسان لنقل جيفة ماعز إلى دائرة هدف، في لعبة شعبية تمثل جزءاً من الهوية الثقافية.","de":"Beim Buzkashi jagen Reiter um einen Kadaver und bringen ihn in einen Zielkreis – ein Volkssport, der tief in der Kultur verwurzelt ist.","en":"In buzkashi, riders race to carry a goat carcass to a target circle—a popular sport that is part of cultural identity."},"readingMinutes":1,"sections":{"ar":[{"heading":"لعبة الفرسان والجمهور","paragraphs":["بزكشي هي لعبة على ظهر الخيل يتنافس فيها فريقان من الفرسان لنقل جيفة ماعز أو عجل مقطوعة الرأس إلى دائرة هدف. تُلعب بشكل رئيسي في أفغانستان حيث الرياضة الوطنية، وفي أجزاء من آسيا الوسطى تحت أسماء مثل كوكبار.","يتدرب الفرسان لسنوات ويستخدمون سروجاً خاصة؛ الميدان واسع وقليل القواعد الرسمية، مع حكام يطبقون العرف. يمكن أن تستمر المباريات ساعات وتؤدي أحياناً إلى إصابات للفرسان والخيول، والنزاعات على الجيفة شائعة."]},{"heading":"اللباس والتقاليد المحلية","paragraphs":["ظهرت خوذات وأحذية واقية في البطولات الرسمية، بينما تحتفظ الألعاب القروية بمعدات أقدم ولعب خشن. تختلف القواعد والأسماء ومعايير رعاية الحيوان بشكل كبير بين بزكشي الأفغانية وكوكبار الكازاخية أو القيرغيزية، والب طولات الرسمية تختلف عن الألعاب المحلية."]}],"de":[{"heading":"Das Spiel der Reiter und Zuschauer","paragraphs":["Buzkashi ist ein Reiterspiel, bei dem zwei Teams versuchen, einen kopflosen Ziegen- oder Kalbskadaver in einen Zielkreis zu bringen. Es wird vor allem in Afghanistan gespielt, wo es Nationalsport ist, und in Teilen Zentralasiens unter Namen wie Kokpar.","Reiter trainieren jahrelang und nutzen spezielle Sättel; das Feld ist groß und es gibt wenige formelle Regeln, Schiedsrichter achten auf Bräuche. Spiele können Stunden dauern und manchmal Reiter und Pferde verletzen; Streit um den Kadaver ist häufig."]},{"heading":"Ausrüstung und lokale Traditionen","paragraphs":["Bei offiziellen Turnieren sind Schutzhelme und Stiefel aufgekommen, während Dorfspiele ältere Ausrüstung und raues Spiel bewahren. Regeln, Namen und Tierschutzstandards unterscheiden sich deutlich zwischen afghanischem Buzkashi und kasachischem oder kirgisischem Kokpar, und offizielle Turniere sind anders als lokale Spiele."]}],"en":[{"heading":"The Riders and the Crowd","paragraphs":["Buzkashi is a horse-mounted game in which two teams of riders compete to carry a headless goat or calf carcass to a target circle. It is played mainly in Afghanistan, where it is the national sport, and in parts of Central Asia under names such as kokpar.","Riders train for years and use special saddles; the field is large and there are few formal rules, with referees enforcing custom. Matches can last hours and sometimes injure riders and horses, and disputes over the carcass are common."]},{"heading":"Gear and Local Traditions","paragraphs":["Protective helmets and boots have appeared in official tournaments, while village games keep older equipment and rough play. Rules, names and animal-welfare standards differ significantly between Afghan buzkashi and Kazakh or Kyrgyz kokpar, and official tournaments are unlike local games."]}]},"context":{"countries":["AF","KZ","KG","UZ","TJ","TM"],"region":"Central Asia and Afghanistan","continent":"asia","languages":["fa","ps","kk","ky","uz","tk"],"period":"contemporary"},"tags":["games-and-leisure","Central Asia and Afghanistan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Buzkashi","de":"Buzkashi","en":"Buzkashi"},"url":"https://en.wikipedia.org/wiki/Buzkashi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Afghanistan","de":"Afghanistan","en":"Afghanistan"},"url":"https://en.wikipedia.org/wiki/Afghanistan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في احتفال زفاف على السهوب، يدور الفرسان حول الجيفة، ينفصل أحدهم، ويهرع الجمهور خلفه نحو الدائرة البيضاء على الأرض.","de":"Bei einer Hochzeitsfeier in der Steppe kreisen Reiter um den Kadaver, ein Reiter bricht aus, und die Menge galoppiert hinter ihm zum weißen Kreis auf dem Boden.","en":"At a wedding celebration on the steppe riders circle the carcass, a rider breaks away, and the crowd gallops after him toward the white circle on the ground."},"misunderstanding":{"ar":"يعتقد البعض أن بزكشي مجرد لعبة عنيفة بلا قواعد، لكنها في الواقع تخضع لعرف صارم ويحكمها حكام محليون.","de":"Manche halten Buzkashi für ein regeloses, brutales Spiel, doch es folgt strengen Bräuchen und wird von Schiedsrichtern überwacht.","en":"Some think buzkashi is just a violent game without rules, but it actually follows strict customs and is overseen by referees."},"comparison":{"ar":"بينما تشتهر بزكشي في أفغانستان كلعبة وطنية، تُعرف في كازاخستان وقيرغيزستان باسم كوكبار مع اختلافات في القواعد والتقاليد.","de":"Während Buzkashi in Afghanistan Nationalsport ist, heißt es in Kasachstan und Kirgisistan Kokpar, mit Unterschieden in Regeln und Traditionen.","en":"While buzkashi is Afghanistan's national sport, it is known as kokpar in Kazakhstan and Kyrgyzstan, with differences in rules and traditions."}},{"id":"asa-074","version":2,"slug":"kazakhstan-s-alphabet-three-scripts-in-a-century","contentType":"language","category":"languages","title":{"ar":"كازاخستان: ثلاثة أبجديات في قرن","de":"Kasachstans Alphabet: drei Schriften in einem Jahrhundert","en":"Kazakhstan's alphabet: three scripts in a century"},"deck":{"ar":"تحولات الكتابة الكازاخية بين السياسة والهوية","de":"Schriftwechsel als Spiegel von Politik und Identität","en":"Script changes as a mirror of politics and identity"},"teaser":{"ar":"من العربية إلى اللاتينية فالسيريلية ثم عودة إلى اللاتينية: رحلة أبجدية تعكس صراعات الهوية والسلطة في كازاخستان.","de":"Arabisch, Latein, Kyrillisch und zurück: Wie Kasachstan seine Schrift dreimal wechselte und was das für den Alltag bedeutet.","en":"Arabic, Latin, Cyrillic and back again: how Kazakhstan changed its alphabet three times and what it means for daily life."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحولات الأبجدية: مشروع دولة","paragraphs":["لم تكن كتابة الكازاخية بالعربية ثم اللاتينية فالسيريلية تطوراً تدريجياً، بل كانت كل خطوة مشروعاً دولة. اعتمدت السيريلية عام 1940 في ظل الحكم السوفيتي، ولا تزال الروسية لغة رسمية للتواصل بين القوميات ولغة العديد من المدارس الحضرية.","في عام 2017 صدر مرسوم يحدد أبجدية لاتينية جديدة ويستهدف استخدامها الرسمي بحلول 2025، لكن التنفيذ تأجل مراراً وتم تعديل مجموعة الحروف. يتحدث معظم الكازاخستانيين الكازاخية والروسية، وتثير سياسة اللغة حساسية لدى المجتمعات الناطقة بالروسية."]},{"heading":"الحياة اليومية بين الحروف","paragraphs":["يؤثر التغيير على التعليم والنشر والخرائط وقواعد البيانات، وتعلم الأجيال الأكبر تهجئة مختلفة لكل كلمة. يظهر كتاب مدرسي الجملة الكازاخية نفسها بالسيريلية واللاتينية، بينما تطلب جدة تعلمت العربية في طفولتها من حفيدتها قراءة اللافتات الجديدة في المطار.","يتباين الإيقاع بين شمال البلاد وجنوبها، إذ تظل الروسية مهيمنة في مدن كثيرة، ولا يؤيد جميع الكازاخ التحول إلى اللاتينية. يختلف الموقف حسب الجيل والمنطقة، مما يجعل الأبجدية قضية يومية وليست نظرية."]}],"de":[{"heading":"Schriftreformen als Staatsprojekt","paragraphs":["Die kasachische Schrift wurde erst arabisch, dann lateinisch, dann kyrillisch geschrieben – und bewegt sich nun zurück zum Lateinischen. Jeder Wechsel war ein staatliches Projekt, keine allmähliche Entwicklung. 1940 wurde unter sowjetischer Herrschaft das Kyrillische eingeführt; Russisch bleibt offizielle Sprache der interethnischen Kommunikation und Sprache vieler städtischer Schulen.","Ein Dekret von 2017 legte ein lateinisches Alphabet und das Ziel der offiziellen Nutzung bis 2025 fest. Die Umsetzung wurde wiederholt verzögert und der Buchstabensatz überarbeitet. Die meisten Kasachen sind zweisprachig in Kasachisch und Russisch, und die Sprachpolitik ist für russischsprachige Gemeinschaften ein sensibles Thema."]},{"heading":"Alltag zwischen den Buchstaben","paragraphs":["Die Umstellung betrifft Bildung, Verlagswesen, Karten und Datenbanken. Ältere Generationen lernten eine andere Schreibweise jedes Wortes. Ein Schulbuch zeigt denselben kasachischen Satz in Kyrillisch und Latein, und eine Großmutter, die als Kind Arabisch lernte, bittet ihre Enkelin, die neuen Schilder am Flughafen vorzulesen.","Das Tempo variiert zwischen dem Norden und dem Süden Kasachstans; in vielen Städten dominiert Russisch, und nicht alle Kasachen unterstützen den Wechsel zum Lateinischen. Die Haltung unterscheidet sich je nach Generation und Region – die Schrift ist ein alltägliches, kein abstraktes Thema."]}],"en":[{"heading":"Script reforms as state projects","paragraphs":["Kazakh has been written in Arabic script, then Latin, then Cyrillic, and now moves back to Latin. Each change was a state project rather than a gradual evolution. Cyrillic was adopted in 1940 under Soviet rule, and Russian remains an official language of interethnic communication and the language of many urban schools.","A 2017 decree set a Latin alphabet and a target of 2025 for official use, but implementation has been repeatedly delayed and the letter set revised. Most Kazakhstanis are bilingual in Kazakh and Russian, and language policy is a sensitive issue for Russian-speaking communities."]},{"heading":"Daily life between the letters","paragraphs":["The change affects education, publishing, maps and databases, and older generations learned a different spelling of every word. A school textbook shows the same Kazakh sentence in Cyrillic and Latin, and a grandmother who learned Arabic script as a child asks her granddaughter to read the new signs at the airport.","The reform's timetable has slipped, and daily practice varies between north and south Kazakhstan; Russian remains dominant in many cities, and not all Kazakhs support the Latin shift. Attitudes differ by generation and region, making the alphabet an everyday, not abstract, matter."]}]},"context":{"countries":["KZ"],"region":"Kazakhstan","continent":"asia","languages":["kk","ru"],"period":"contemporary"},"tags":["languages","Kazakhstan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kazakh alphabets","de":"Kazakh alphabets","en":"Kazakh alphabets"},"url":"https://en.wikipedia.org/wiki/Kazakh_alphabets","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kazakh language","de":"Kazakh language","en":"Kazakh language"},"url":"https://en.wikipedia.org/wiki/Kazakh_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"كتاب مدرسي يعرض الجملة الكازاخية نفسها بالسيريلية واللاتينية، وجدة تعلمت العربية في طفولتها تطلب من حفيدتها قراءة اللافتات الجديدة في المطار.","de":"Ein Schulbuch zeigt denselben kasachischen Satz in Kyrillisch und Latein, und eine Großmutter, die als Kind Arabisch lernte, bittet ihre Enkelin, die neuen Schilder am Flughafen vorzulesen.","en":"A school textbook shows the same Kazakh sentence in Cyrillic and Latin, and a grandmother who learned Arabic script as a child asks her granddaughter to read the new signs at the airport."},"misunderstanding":{"ar":"يُفترض أحياناً أن تغيير الأبجدية مسألة تقنية بحتة، لكنه يمس الذاكرة الجماعية والهوية والعلاقة بين المجموعات اللغوية.","de":"Oft wird angenommen, ein Schriftwechsel sei eine rein technische Angelegenheit. Tatsächlich berührt er kollektives Gedächtnis, Identität und das Verhältnis zwischen Sprachgruppen.","en":"It is sometimes assumed that changing a script is a purely technical matter, but it touches collective memory, identity and relations between language groups."},"comparison":{"ar":"يشبه هذا التحول ما حدث في تركيا عام 1928 عندما استبدلت العربية باللاتينية، لكن الحالة الكازاخية أكثر تعقيداً بسبب ثنائية اللغة الروسية.","de":"Ähnlich wie in der Türkei 1928, als das arabische durch das lateinische Alphabet ersetzt wurde, ist der kasachische Fall wegen der russischen Zweisprachigkeit komplexer.","en":"Similar to Turkey's 1928 switch from Arabic to Latin letters, the Kazakh case is more complex because of Russian bilingualism."},"expression":{"original":"Сәлеметсіз бе?","language":"қазақ тілі","gloss":{"ar":"مرحباً - الصيغة المهذبة المستخدمة مع كبار السن والغرباء","de":"Guten Tag – die höfliche Form gegenüber Älteren und Fremden","en":"hello – the polite form used with elders and strangers"},"usage":{"ar":"تحية رسمية تُقال عند لقاء شخص أكبر سناً أو غير معروف، وتُرد عليها بعبارة مماثلة.","de":"Förmliche Begrüßung beim Treffen älterer oder unbekannter Personen; die Antwort erfolgt mit derselben Wendung.","en":"A formal greeting when meeting someone older or unknown; the reply uses the same phrase."},"transliteration":"sälemetsiz be?"}},{"id":"asa-075","version":2,"slug":"aitys-the-song-duel-where-poets-improvise-insults-and-praise","contentType":"note","category":"storytelling","title":{"ar":"آيتيس: مبارزة الشعراء بالارتجال","de":"Aitys: Das Liedduell der improvisierenden Dichter","en":"Aitys: The Song Duel of Improvising Poets"},"deck":{"ar":"في كازاخستان وقيرغيزستان، يتنافس الشاعران المرتجلان في مبارزة غنائية تمزج الفكاهة والحكمة.","de":"In Kasachstan und Kirgisistan treten zwei Akyns in einem Gesangswettstreit an, der Humor und Weisheit vereint.","en":"In Kazakhstan and Kyrgyzstan, two akyns face off in a sung contest that blends humour, wisdom and quick wit."},"teaser":{"ar":"آيتيس هو فن الارتجال الشعري والغنائي بين شاعرين، حيث يتناوبان على نظم الأبيات في موضوع محدد، ويحكم الجمهور على الفائز.","de":"Aitys ist ein Wettbewerb der improvisierten Dichtung und des Gesangs zwischen zwei Akyns, bei dem das Publikum den Sieger durch seine Reaktion bestimmt.","en":"Aitys is a contest of improvised poetry and song between two akyns, where the audience judges the winner by its reaction."},"readingMinutes":1,"sections":{"ar":[{"heading":"طبيعة المبارزة","paragraphs":["آيتيس هو مسابقة شعرية غنائية مرتجلة بين شاعرين (آكين)، يرافقهما آلة الدومبرا، في التقاليد الكازاخية والقيرغيزية.","يتبادل المتنافسان نظم الأبيات حول موضوع مختار: مدح شخص، أو السخرية من منافس، أو الجدال حول الحب أو التغيير الاجتماعي.","تختلط العروض بالفكاهة والحكمة والرد السريع، ويحكم الجمهور على الفائز من خلال رد فعله."]},{"heading":"استمرارية الفن وتنوعه","paragraphs":["أدرجت اليونسكو آيتيس في قائمة التراث الثقافي غير المادي عام 2015، واصفة إياه بأنه تعبير حي عن المهارة الارتجالية وقيم المجتمع.","تحافظ المسابقات الحكومية والبرامج التلفزيونية على ظهور هذا الفن، ويؤدي الشعراء الشباب الآن بالكازاخية والروسية ومزيج من اللغتين.","يختلف محتوى هذا الفن وجمهوره بين التقاليد الكازاخية والقيرغيزية وبين المهرجانات الريفية والمسابقات التلفزيونية، ونادراً ما تُحفظ النصوص المرتجلة كتابياً."]}],"de":[{"heading":"Das Wesen des Duells","paragraphs":["Aitys ist ein Wettstreit der improvisierten Dichtung und des Gesangs zwischen zwei Akyns (Barden), begleitet von der Dombra, in der kasachischen und kirgisischen Tradition.","Die Duellanten wechseln sich ab und dichten Verse zu einem gewählten Thema – sie loben eine Person, verspotten einen Rivalen oder streiten über Liebe oder sozialen Wandel.","Die Darbietungen mischen Humor, Weisheit und schnelle Schlagfertigkeit; das Publikum kürt den Sieger durch seine Reaktion."]},{"heading":"Fortbestand und Vielfalt","paragraphs":["Die UNESCO nahm Aitys 2015 in die Liste des immateriellen Kulturerbes auf und beschrieb es als lebendigen Ausdruck von Improvisationskunst und Gemeinschaftswerten.","Staatliche Wettbewerbe und Fernsehshows halten das Genre sichtbar, und junge Akyns treten heute auf Kasachisch, Russisch und in gemischten Registern auf.","Inhalt und Publikum variieren zwischen kasachischer und kirgisischer Tradition sowie zwischen ländlichen Festen und Fernsehwettbewerben, und die improvisierten Texte bleiben selten schriftlich erhalten."]}],"en":[{"heading":"The Nature of the Duel","paragraphs":["Aitys is a contest of improvised poetry and song between two akyns (bards), accompanied by the dombra, in Kazakh and Kyrgyz tradition.","The duellists take turns composing verses on a chosen theme – praising a person, mocking a rival, arguing about love or social change.","Performances mix humour, wisdom and quick repartee; the audience judges the winner by its reaction."]},{"heading":"Continuity and Variation","paragraphs":["UNESCO listed Aitys as intangible cultural heritage in 2015, describing it as a living expression of improvisational skill and community values.","State competitions and television contests keep the genre visible, and young akyns now perform in Kazakh, Russian and mixed registers.","The genre's content and audience vary between Kazakh and Kyrgyz traditions and between rural festivals and televised contests, and the improvised texts rarely survive in written form."]}]},"context":{"countries":["KZ","KG"],"region":"Kazakhstan and Kyrgyzstan","continent":"asia","languages":["kk","ky"],"period":"contemporary"},"tags":["storytelling","Kazakhstan and Kyrgyzstan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Aytysh","de":"Aytysh","en":"Aytysh"},"url":"https://en.wikipedia.org/wiki/Aytysh","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kazakhstan","de":"Kazakhstan","en":"Kazakhstan"},"url":"https://en.wikipedia.org/wiki/Kazakhstan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"شاعران يقفان وجهاً لوجه في خيمة مهرجان، يعزفان الدومبرا ويتبادلان الأبيات عن مضيف بخيل؛ يضحك الجمهور ويصرخ، والفائز يمزح بشأن الجائزة.","de":"Zwei Akyns stehen sich in einer Festjurte gegenüber, zupfen die Dombra und tauschen Verse über einen geizigen Gastgeber aus; das Publikum lacht und ruft, und der Verlierer scherzt über den Preis.","en":"Two akyns face each other at a festival yurt, pluck the dombra and trade verses about a stingy host; the audience laughs and shouts, and the loser jokes about the prize."},"misunderstanding":{"ar":"يعتقد البعض أن آيتيس مجرد إهانات فظة، لكنه في الواقع فن منظم يجمع بين المدح والنقد الاجتماعي والفكاهة الراقية.","de":"Manche halten Aitys für bloße derbe Beschimpfungen, doch es ist eine geordnete Kunst, die Lob, Gesellschaftskritik und feinen Humor verbindet.","en":"Some think aitys is just rude insults, but it is a structured art that combines praise, social critique and refined humour."},"comparison":{"ar":"يشبه آيتيس مسابقات الارتجال الشعري في ثقافات أخرى، لكنه يتميز بمرافقة الدومبرا وتفاعل الجمهور المباشر في الحكم.","de":"Aitys ähnelt improvisierten Dichtwettbewerben anderer Kulturen, zeichnet sich aber durch die Dombra-Begleitung und die direkte Publikumsjury aus.","en":"Aitys resembles improvised poetry contests in other cultures, but stands out for its dombra accompaniment and direct audience judging."}},{"id":"asa-076","version":2,"slug":"manas-an-epic-recited-across-a-thousand-years","contentType":"note","category":"storytelling","title":{"ar":"ملحمة ماناس: حكاية شعب يتوارثها الرواة","de":"Manas: Ein Epos, das Generationen verbindet","en":"Manas: An Epic Recited Across Generations"},"deck":{"ar":"من جيل إلى جيل، يحفظ المناشي ملحمة ماناس ويؤدونها لساعات، حاملين تاريخًا وميثولوجيا وهوية.","de":"Manaschi bewahren das Epos mündlich und tragen Geschichte, Mythos und Identität Kirgisistans weiter.","en":"Manaschi keep the epic alive orally, carrying history, myth and Kyrgyz identity from one generation to the next."},"teaser":{"ar":"في قيرغيزستان، يتعلم المناشي ملحمة ماناس شفاهة ويؤدونها لساعات، مما يجعلها ذاكرة حية للشعب.","de":"In Kirgisistan lernen Manaschi das Epos Manas mündlich und tragen es über Stunden vor – als lebendiges Gedächtnis.","en":"In Kyrgyzstan, manaschi learn the Epic of Manas by heart and perform it for hours, keeping a centuries-old tradition alive."},"readingMinutes":1,"sections":{"ar":[{"heading":"الرواة: حراس الذاكرة","paragraphs":["ملحمة ماناس تحكي قصة محارب قيرغيزي وذريته، وهي من أطول الملاحم في العالم، إذ تبلغ نسخها مئات الآلاف من الأبيات. يؤديها المناشي تقليديًا، وهم رواة يتعلمون النص شفاهة وقد يؤدون لساعات بأسلوب إنشادي مرتفع.","يجمع العمل بين التاريخ والأسطورة والنسب، وقد استُخدم في القرن العشرين لتشكيل الهوية الوطنية القيرغيزية. أدرجت اليونسكو ثلاثية الملحمة القيرغيزية - ماناس وسيميتي وسيتيك - كتراث غير مادي في عام 2013."]},{"heading":"الملحمة بين الماضي والحاضر","paragraphs":["يستمر تدريب المناشي في المدارس والمهرجانات، وقد تم تكييف الملحمة في الأوبرا والسينما وعروض السياحة. يختلف الأداء حسب المنطقة والجيل، إذ يميل الرواة الأكبر سنًا إلى الالتزام بالنسخ المحفوظة بينما يجرب الشباب أساليب أكثر حرية."]}],"de":[{"heading":"Die Hüter der Erzählung","paragraphs":["Das Epos von Manas erzählt die Geschichte eines kirgisischen Kriegers und seiner Nachkommen; es ist eines der längsten Epen der Welt, mit Versionen von Hunderttausenden Versen. Traditionell wird es von Manaschi vorgetragen, Rezitatoren, die den Text mündlich lernen und stundenlang in einem erhöhten, gesangsähnlichen Vortrag performen.","Das Epos verbindet Geschichte, Mythos und Genealogie und wurde im 20. Jahrhundert zur Formung der kirgisischen nationalen Identität genutzt. 2013 listete die UNESCO die kirgisische Epen-Trilogie – Manas, Semetey und Seitek – als immaterielles Kulturerbe."]},{"heading":"Zwischen Tradition und Moderne","paragraphs":["Die Ausbildung von Manaschi wird in Schulen und Festivals fortgeführt, und das Epos wurde für Oper, Film und Tourismusaufführungen adaptiert. Je nach Region und Generation variiert die Aufführungspraxis: Ältere Rezitatoren bleiben oft näher an überlieferten Versionen, während Jüngere freiere Formen erproben."]}],"en":[{"heading":"The Reciters Who Hold the Memory","paragraphs":["The Epic of Manas tells the story of a Kyrgyz warrior and his descendants; it is one of the world's longest epics, with versions running to hundreds of thousands of lines. It is traditionally performed by manaschi, reciters who learn the text orally and may perform for hours in a heightened, chant-like delivery.","The epic combines history, myth and genealogy, and it was used in the twentieth century to shape Kyrgyz national identity. UNESCO listed the Kyrgyz epic trilogy—Manas, Semetey and Seitek—as intangible heritage in 2013."]},{"heading":"Living Tradition, Changing Voices","paragraphs":["Manaschi training continues in schools and festivals, and the epic has been adapted into opera, film and tourism performances. Performance styles vary by region and generation: older reciters often stay close to memorized versions, while younger ones experiment with freer delivery."]}]},"context":{"countries":["KG"],"region":"Kyrgyzstan","continent":"asia","languages":["ky"],"period":"contemporary"},"tags":["storytelling","Kyrgyzstan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Epic of Manas","de":"Epic of Manas","en":"Epic of Manas"},"url":"https://en.wikipedia.org/wiki/Epic_of_Manas","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kyrgyzstan","de":"Kyrgyzstan","en":"Kyrgyzstan"},"url":"https://en.wikipedia.org/wiki/Kyrgyzstan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مهرجان صيفي في الجبال، يجلس مناشي أمام حشد، يغمض عينيه ويرتل مقطعًا من معركة لمدة ساعة، بينما يومئ المستمعون عند الأبيات المألوفة.","de":"Bei einem Sommerfestival in den Bergen sitzt ein Manaschi vor einer Menge, schließt die Augen und rezitiert eine Stunde lang eine Schlachtpassage, während die Zuhörer bei vertrauten Versen nicken.","en":"At a summer festival in the mountains a manaschi sits before a crowd, closes his eyes and recites a battle passage for an hour, while listeners nod at familiar lines."},"misunderstanding":{"ar":"لا يوجد نص واحد معتمد: تختلف النسخ حسب الراوي والمنطقة، وقد شكل التحرير في العهد السوفيتي أجزاء من التقليد المطبوع.","de":"Es gibt keinen einzigen autorisierten Text: Versionen unterscheiden sich je nach Rezitator und Region, und sowjetische Bearbeitungen prägten Teile der gedruckten Tradition.","en":"There is no single authorised text: versions differ by reciter and region, and Soviet-era editing shaped parts of the printed tradition."},"comparison":{"ar":"مثل الحكواتي في الثقافات العربية، المناشي ليس مجرد راوٍ بل مؤدٍّ يحمل ذاكرة جماعية ويجددها في كل جلسة.","de":"Ähnlich dem arabischen Hakawati ist der Manaschi nicht nur Erzähler, sondern Träger eines kollektiven Gedächtnisses, das er in jeder Aufführung erneuert.","en":"Like the hakawati in Arabic cultures, the manaschi is not just a storyteller but a keeper of collective memory who renews it with each performance."}},{"id":"asa-077","version":2,"slug":"jailoo-the-summer-migration-to-the-high-pasture","contentType":"note","category":"nature-and-seasons","title":{"ar":"الجيلو: الهجرة الصيفية إلى المراعي العليا","de":"Jailoo: der Sommerzug auf die Hochweide","en":"Jailoo: the summer migration to high pasture"},"deck":{"ar":"عائلات الرعاة تنتقل مع قطعانها إلى مراعي الجبال العالية في قيرغيزستان وكازاخستان، حيث تعيش في الخيام ويحلبون ويحتفلون.","de":"Hirtenfamilien ziehen mit ihren Tieren auf die Hochweiden Kirgisistans und Kasachstans, leben in Jurten und verbinden Melken mit Festen.","en":"Herder families move with their animals to the high pastures of Kyrgyzstan and Kazakhstan, living in yurts and combining milking with celebrations."},"teaser":{"ar":"في الصيف، تصعد عائلات الرعاة إلى مراعي الجيلو العالية، حيث الحياة اليومية تدور حول الحلب والاحتفالات، لكن التغير المناخي وانتقال الشباب يهددان هذا التقليد.","de":"Im Sommer ziehen Hirtenfamilien auf die Jailoo-Weiden, wo Alltag zwischen Melken und Feiern pendelt – doch Klimawandel und Abwanderung der Jugend setzen der Tradition zu.","en":"In summer, herder families ascend to jailoo pastures, where daily life revolves around milking and festivities—but climate change and youth migration threaten the tradition."},"readingMinutes":1,"sections":{"ar":[{"heading":"حياة الجيلو: بين الرعي والاحتفال","paragraphs":["الجيلو هي المراعي الصيفية في قيرغيزستان وكازاخستان، حيث ينتقل الرعاة مع حيواناتهم من الربيع إلى الخريف، ويعيشون في خيام. تتبع الهجرة ذوبان الثلوج ونمو العشب: تتحرك العائلات في أواخر الربيع وتعود قبل الشتاء، أحيانًا على عدة مراحل.","تشمل حياة الجيلو الحلب وتصنيع منتجات الألبان والجز والاختلاط بالمخيمات المجاورة؛ كما تُقام فيها العديد من الأعراس وألعاب الفروسية. وتختلف هذه الممارسات حسب المنطقة والأجيال، فبعض العائلات تبقى قرب القرى بينما يصعد آخرون إلى المراعي العالية."]},{"heading":"السياحة والتحديات: مستقبل الجيلو","paragraphs":["جلب السياحة المجتمعية زوارًا إلى بعض المراعي، مما يوفر دخلًا للرعاة لكنه يغير الروتين اليومي. كما أن التغير المناخي وتدهور المراعي وهجرة الشباب إلى المدن تضغط على هذا النظام، وبعض العائلات الآن تحتفظ بالحيوانات دون التنقل."]}],"de":[{"heading":"Leben auf der Jailoo: Weide und Fest","paragraphs":["Jailoo sind die Sommerweiden in Kirgisistan und Kasachstan, wohin Hirten von Frühling bis Herbst mit ihren Tieren ziehen und in Jurten leben. Die Migration folgt der Schneeschmelze und dem Gras: Familien ziehen im späten Frühling hinauf und kehren vor dem Winter zurück, manchmal in mehreren Etappen.","Das Jailoo-Leben umfasst Melken, Verarbeitung von Milchprodukten, Schafschur und Geselligkeit mit benachbarten Lagern; auch viele Hochzeiten und Pferdespiele finden dann statt. Je nach Region und Generation variiert die Praxis: Manche Familien bleiben nahe den Dörfern, andere ziehen auf die Hochweiden."]},{"heading":"Tourismus und Herausforderungen: die Zukunft der Jailoo","paragraphs":["Gemeindebasierter Tourismus bringt Besucher auf einige Weiden, was den Hirten Einkommen sichert, aber auch den Alltag verändert. Klimawandel, Weidedegradation und die Abwanderung junger Menschen in die Städte setzen dem System zu, und manche Familien halten Tiere ohne Umzug."]}],"en":[{"heading":"Jailoo life: herding and celebration","paragraphs":["Jailoo are the summer pastures of Kyrgyzstan and Kazakhstan where herders move with their animals from spring to autumn, living in yurts. The migration follows snowmelt and grass: families move up in late spring and return before winter, sometimes over several stages.","Jailoo life involves milking, processing dairy products, shearing and socialising with neighbouring camps; it is also when many weddings and horse games are held. The practice varies by region and generation: some families stay near villages while others head for high pastures."]},{"heading":"Tourism and pressures: the future of jailoo","paragraphs":["Community-based tourism has brought visitors to some pastures, giving herders income but also changing routines. Climate change, pasture degradation and young people leaving for cities are pressuring the system, and some families now keep animals without moving."]}]},"context":{"countries":["KG","KZ"],"region":"Tian Shan and steppe pastures","continent":"asia","languages":["ky","kk"],"period":"contemporary"},"tags":["nature-and-seasons","Tian Shan and steppe pastures"],"sources":[{"organization":"Wikipedia","title":{"ar":"Yaylak","de":"Yaylak","en":"Yaylak"},"url":"https://en.wikipedia.org/wiki/Yaylak","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kyrgyzstan","de":"Kyrgyzstan","en":"Kyrgyzstan"},"url":"https://en.wikipedia.org/wiki/Kyrgyzstan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في يونيو، تُحمّل عائلة خيمة ومطبخًا على الخيول وشاحنة، وتنتقل إلى مرعى على ارتفاع 2500 متر، وتقضي الصيف في حلب الأفراس وصنع الكوميس بجانب مخيمات أخرى.","de":"Im Juni lädt eine Familie eine Jurte und eine Küche auf Pferde und einen Lastwagen, zieht auf eine Weide auf 2.500 Metern und verbringt den Sommer damit, Stuten zu melken und Kumys neben anderen Lagern herzustellen.","en":"In June a family loads a yurt and kitchen onto horses and a truck, moves to a pasture at 2,500 metres, and spends the summer milking mares and making kumis beside other camps."},"misunderstanding":{"ar":"هذه الممارسة ليست شاملة في قيرغيزستان: كثير من الرعاة يربون الحيوانات قرب القرى، والصورة الرومانسية للحياة البدوية تُستخدم غالبًا في التسويق السياحي.","de":"Die Praxis ist in Kirgisistan nicht universell: Viele Hirten halten Tiere in Dorfnähe, und das romantische Bild des Nomadenlebens wird oft im Tourismusmarketing verwendet.","en":"The practice is not universal in Kyrgyzstan: many herders keep animals near villages, and the romantic image of nomadic life is often used in tourism marketing."},"comparison":{"ar":"بينما يرتبط الجيلو بالهجرة الموسمية، فإن بعض العائلات في كازاخستان تبقى في السهوب على مدار السنة، مما يعكس تنوع طرق العيش في المنطقة.","de":"Während Jailoo mit saisonaler Migration verbunden ist, bleiben manche Familien in Kasachstan das ganze Jahr über in der Steppe, was die Vielfalt der Lebensweisen in der Region zeigt.","en":"While jailoo is tied to seasonal migration, some families in Kazakhstan stay on the steppe year-round, reflecting the diversity of ways of life in the region."}},{"id":"asa-078","version":2,"slug":"kumis-the-fermented-mare-s-milk-that-turns-a-pasture-into-a-table","contentType":"note","category":"food-and-hospitality","title":{"ar":"كوميس: لبن الفرس المخمر الذي يحول المرعى إلى مائدة","de":"Kumys: fermentierte Stutenmilch, die die Weide zum Tisch macht","en":"Kumis: fermented mare's milk that turns a pasture into a table"},"deck":{"ar":"في سهول آسيا الوسطى ومنغوليا، يُصنع الكوميس من لبن الفرس المخمر موسمياً، ويُقدَّم للضيوف رمزاً للكرم، ويتفاوت مذاقه وقوته حسب المنتج والموسم.","de":"In den Steppen Zentralasiens und der Mongolei wird Kumys saisonal aus fermentierter Stutenmilch hergestellt, als Gastgeschenk gereicht und schmeckt je nach Produzent und Jahreszeit unterschiedlich.","en":"In the steppes of Central Asia and Mongolia, kumis is made seasonally from fermented mare's milk, offered to guests as a sign of hospitality, and tastes different with each producer and season."},"teaser":{"ar":"مشروب خفيف الكحول من لبن الفرس، يظهر مع موسم الرضاعة ويختفي مع عودة الحيوانات إلى مراعي الشتاء، ويُقدَّم في الجبال كعلامة ضيافة.","de":"Ein leicht alkoholisches Getränk aus Stutenmilch, das mit der Fohlenzeit erscheint und mit der Rückkehr ins Winterlager verschwindet, in den Bergen als Gastgeschenk serviert.","en":"A mildly alcoholic drink from mare's milk, appearing with foaling season and vanishing as animals return to winter quarters, served at the yurt door as a welcome."},"readingMinutes":1,"sections":{"ar":[{"heading":"موسم الرضاعة والضيافة","paragraphs":["الكوميس مشروب خفيف الكحول يُصنع من لبن الفرس المخمر، ويُنتج تقليدياً في آسيا الوسطى ومنغوليا خلال موسم المراعي الصيفية. يُحلب الفرس عدة مرات يومياً، ثم يُخض اللبن في وعاء جلدي أو خشبي ويُترك ليتخمر مع خميرة بداية.","يُقدَّم المشروب للضيوف كعلامة على الضيافة، ويتفاوت مذاقه وقوته حسب الموسم والمنتج. ويرتبط المشروب بتقويم الرعي: يظهر عندما تلد الأفراس في الربيع ويختفي عندما تعود الحيوانات إلى مراعي الشتاء. وتختلف عادات التحضير والتقديم بين المناطق والأجيال، فبعض العائلات تحتفظ بخميرتها الخاصة وتنقلها عبر الأجيال."]},{"heading":"قيمة صحية وتقاليد متجددة","paragraphs":["طالما قُدِّر الكوميس لفوائده الصحية المتوقعة، وقد وصفته المصحات في كازاخستان وقيرغيزستان سابقاً لعلاج السل والهضم. الإنتاج صغير النطاق وموسمي، والمذاق يتفاوت بشكل واسع؛ الكوميس التجاري متوفر، لكن الكوميس الخام التقليدي ليس لكل الأذواق وقد يحمل مخاطر صحية."]}],"de":[{"heading":"Fohlenzeit und Gastfreundschaft","paragraphs":["Kumys ist ein leicht alkoholisches Getränk aus fermentierter Stutenmilch, das traditionell in Zentralasien und der Mongolei während der Sommerweidezeit hergestellt wird. Stuten werden mehrmals täglich gemolken, die Milch in einem Leder- oder Holzgefäß gestoßen und mit einer Starterkultur fermentiert.","Das Getränk wird Gästen als Zeichen der Gastfreundschaft angeboten, Geschmack und Stärke variieren je nach Saison und Produzent. Es ist an den Weidekalender gebunden: Es erscheint, wenn die Stuten im Frühling fohlen, und verschwindet, wenn die Tiere ins Winterlager zurückkehren. Die Zubereitung unterscheidet sich regional und Generationen, manche Familien bewahren ihren eigenen Starter über Jahre."]},{"heading":"Gesundheitswert und lebendige Tradition","paragraphs":["Kumys wurde lange für seine vermuteten gesundheitlichen Vorteile geschätzt, und Sanatorien in Kasachstan und Kirgisistan verschrieben es einst bei Tuberkulose und Verdauungsproblemen. Die Produktion ist klein und saisonal, der Geschmack schwankt stark; kommerzieller Kumys ist erhältlich, aber traditioneller roher Kumys ist nicht jedermanns Sache und kann Hygieneprobleme bergen."]}],"en":[{"heading":"Foaling season and hospitality","paragraphs":["Kumis is a mildly alcoholic drink made from fermented mare's milk, traditionally produced in Central Asia and Mongolia during the summer pasture season. Mares are milked several times a day, and the milk is churned in a leather or wooden vessel and left to ferment with a starter culture.","The drink is offered to guests as a sign of hospitality, and its taste and strength vary by season and producer. It is tied to the herding calendar: it appears when mares foal in spring and disappears when the animals return to winter quarters. Preparation varies by region and generation, with some families keeping their own starter culture for years."]},{"heading":"Health value and living tradition","paragraphs":["Kumis has long been valued for perceived health benefits, and sanatoria in Kazakhstan and Kyrgyzstan once prescribed it for tuberculosis and digestion. Production is small-scale and seasonal, and the taste varies widely; commercial kumis is available, but traditional raw kumis is not to everyone's taste and can carry hygiene risks."]}]},"context":{"countries":["KG","KZ","MN"],"region":"Central Asia and Mongolia","continent":"asia","languages":["ky","kk","mn"],"period":"contemporary"},"tags":["food-and-hospitality","Central Asia and Mongolia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kumis","de":"Kumis","en":"Kumis"},"url":"https://en.wikipedia.org/wiki/Kumis","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kazakhstan","de":"Kazakhstan","en":"Kazakhstan"},"url":"https://en.wikipedia.org/wiki/Kazakhstan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يُقدَّم لزائر الجايلو وعاء من الكوميس عند باب الخيمة، وبعد الوعاء الثالث يبدأ المضيف الحديث عن خيول العائلة.","de":"Ein Besucher im Jailoo bekommt an der Jurten Tür eine Schale Kumys gereicht, und nach der dritten Schale beginnt der Gastgeber von den Pferden der Familie zu erzählen.","en":"A visitor to a jailoo is handed a bowl of kumis at the yurt door, and after the third bowl the host begins to speak about the family's horses."},"misunderstanding":{"ar":"يعتقد البعض أن الكوميس مجرد حليب مخمر عادي، لكنه في الواقع مشروب خفيف الكحول ويُنتج فقط في موسم الرضاعة، وليس متاحاً على مدار السنة.","de":"Manche halten Kumys für gewöhnliche Sauermilch, doch er ist leicht alkoholisch und nur während der Fohlenzeit verfügbar, nicht das ganze Jahr.","en":"Some think kumis is just ordinary fermented milk, but it is mildly alcoholic and only available during foaling season, not year-round."},"comparison":{"ar":"يشبه الكوميس في دوره الاجتماعي الشاي في بعض الثقافات، لكنه موسمي ومرتبط بدورة حياة الحيوان، بينما الشاي متاح دائماً.","de":"In seiner sozialen Rolle ähnelt Kumys dem Tee in anderen Kulturen, ist aber saisonal und an den Lebenszyklus der Tiere gebunden, während Tee immer verfügbar ist.","en":"In its social role kumis resembles tea in other cultures, but it is seasonal and tied to the animal's life cycle, while tea is always available."}},{"id":"asa-079","version":2,"slug":"mahalla-the-neighbourhood-that-governs-itself","contentType":"note","category":"cities-and-community","title":{"ar":"المحلة: الحي الذي يحكم نفسه","de":"Mahalla: das Viertel, das sich selbst regiert","en":"Mahalla: the neighbourhood that governs itself"},"deck":{"ar":"في أوزبكستان وآسيا الوسطى، المحلة ليست مجرد حي سكني، بل مجتمع محلي ينظم نفسه ويشارك في الحياة اليومية.","de":"In Usbekistan und anderen Teilen Zentralasiens ist die Mahalla mehr als eine Nachbarschaft – sie ist eine Gemeinschaft mit sozialer und politischer Funktion.","en":"In Uzbekistan and Central Asia, the mahalla is more than a residential area—it is a community institution with social and political roles."},"teaser":{"ar":"المحلة في آسيا الوسطى تجمع بين التقاليد والوظائف الإدارية، وتلعب دورًا حيويًا في حياة السكان.","de":"Die Mahalla in Zentralasien verbindet Tradition und Verwaltung und spielt eine zentrale Rolle im Alltag der Menschen.","en":"The mahalla in Central Asia blends tradition with administration, playing a vital role in daily life and local governance."},"readingMinutes":1,"sections":{"ar":[{"heading":"المحلة كمجتمع محلي","paragraphs":["المحلة هي مجتمع حي تقليدي في أوزبكستان وأجزاء أخرى من آسيا الوسطى، يتمحور حول مسجد وبيت شاي ومساحات مشتركة. يتعاون السكان في الأعراس والجنازات وأعمال التنظيف والأعمال الخيرية، ويقوم مجلس من الشيوخ بالوساطة في النزاعات. هذا التعاون يعزز الروابط الاجتماعية ويخلق شبكة دعم محلية.","تختلف تنظيمات المحلة ومشاركة الدولة باختلاف البلد والمدينة، كما تختلف وظائف المحلات الريفية عن الحضرية؛ فالمؤسسة ليست موحدة في جميع أنحاء آسيا الوسطى. وتلعب المحلة دورًا مهمًا لعائلات المهاجرين الذين يعتمدون على الجيران أثناء عمل أفرادهم في الخارج."]},{"heading":"المحلة بين السلطة الاجتماعية والوظيفة السياسية","paragraphs":["في أوزبكستان، المحلة هي أيضًا وحدة إدارية رسمية، لها رئيس وميثاق، وتتولى مهام الدعم الاجتماعي والتسجيل. وتستخدم الدولة المحلة لتقديم الرعاية الاجتماعية ومراقبة الأسر، مما يمنحها سلطة اجتماعية ووظيفة سياسية في آن واحد. هذا المزيج يجعلها مؤسسة فريدة تجمع بين المجتمع والدولة."]}],"de":[{"heading":"Die Mahalla als Gemeinschaft","paragraphs":["Eine Mahalla ist eine traditionelle Nachbarschaftsgemeinschaft in Usbekistan und anderen Teilen Zentralasiens, die sich um eine Moschee, ein Teehaus und gemeinschaftliche Räume zentriert. Die Bewohner kooperieren bei Hochzeiten, Beerdigungen, Reinigungsaktionen und Wohltätigkeit, und ein Ältestenrat vermittelt bei Streitigkeiten. Diese Zusammenarbeit stärkt den sozialen Zusammenhalt und schafft ein lokales Unterstützungsnetzwerk.","Die Organisation der Mahalla und die staatliche Beteiligung unterscheiden sich je nach Land und Stadt, und ländliche und städtische Mahallas haben unterschiedliche Funktionen; die Institution ist in Zentralasien nicht einheitlich. Mahalla-Netzwerke sind wichtig für die Familien von Migranten, die sich während der Arbeit im Ausland auf ihre Nachbarn verlassen."]},{"heading":"Zwischen sozialer Autorität und politischer Funktion","paragraphs":["In Usbekistan ist die Mahalla auch eine offizielle Verwaltungseinheit mit einem Vorsitzenden und einer Satzung, die soziale Unterstützung und Registrierungsaufgaben übernimmt. Der Staat nutzt die Mahalla, um Wohlfahrt zu leisten und Familien zu überwachen, was ihr sowohl soziale Autorität als auch politische Funktion verleiht. Diese Doppelrolle macht sie zu einer einzigartigen Institution zwischen Gesellschaft und Staat."]}],"en":[{"heading":"The mahalla as a community","paragraphs":["A mahalla is a traditional neighbourhood community in Uzbekistan and other parts of Central Asia, centred on a mosque, tea house and communal spaces. Residents cooperate on weddings, funerals, clean-ups and charity, and a council of elders mediates disputes. This cooperation strengthens social ties and creates a local support network.","Mahalla organisation and state involvement differ by country and city, and rural and urban mahallas have different functions; the institution is not uniform across Central Asia. Mahalla networks are important for migrants' families, who rely on neighbours while members work abroad."]},{"heading":"Between social authority and political function","paragraphs":["In Uzbekistan the mahalla is also an official administrative unit, with a chairperson and a charter, and it handles social support and registration tasks. The state uses the mahalla to deliver welfare and to monitor families, which gives it both social authority and political function. This dual role makes it a unique institution bridging society and state."]}]},"context":{"countries":["UZ","TJ","KG"],"region":"Uzbekistan and Central Asia","continent":"asia","languages":["uz","tg"],"period":"contemporary"},"tags":["cities-and-community","Uzbekistan and Central Asia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mahalla","de":"Mahalla","en":"Mahalla"},"url":"https://en.wikipedia.org/wiki/Mahalla","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Uzbekistan","de":"Uzbekistan","en":"Uzbekistan"},"url":"https://en.wikipedia.org/wiki/Uzbekistan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عندما ترتب أسرة في طشقند حفل زفاف، يقوم متطوعو المحلة بترتيب الطاولات في الفناء وتنسيق الطبخ وجمع المساهمات من الجيران.","de":"Wenn eine Familie in Taschkent eine Hochzeit ausrichtet, stellen Mahalla-Freiwillige Tische im Hof auf, koordinieren das Kochen und sammeln Beiträge von den Nachbarn.","en":"When a family in Tashkent arranges a wedding, mahalla volunteers set up tables in the courtyard, coordinate cooking and collect contributions from neighbours."},"misunderstanding":{"ar":"قد يُفهم أن المحلة مجرد حي سكني تقليدي، لكنها في أوزبكستان وحدة إدارية رسمية لها صلاحيات اجتماعية وسياسية.","de":"Man könnte annehmen, die Mahalla sei nur ein traditionelles Wohnviertel, doch in Usbekistan ist sie eine offizielle Verwaltungseinheit mit sozialen und politischen Befugnissen.","en":"One might assume the mahalla is just a traditional residential neighbourhood, but in Uzbekistan it is an official administrative unit with social and political powers."},"comparison":{"ar":"على عكس الأحياء في المدن الغربية التي تقتصر على الجيرة، تجمع المحلة بين التعاون الاجتماعي والوظائف الإدارية، مما يعكس تكامل المجتمع والدولة.","de":"Anders als in westlichen Städten, wo Nachbarschaft oft nur räumliche Nähe bedeutet, verbindet die Mahalla soziale Kooperation mit Verwaltungsaufgaben und spiegelt die Verflechtung von Gesellschaft und Staat wider.","en":"Unlike in Western cities where neighbourhood often means mere proximity, the mahalla combines social cooperation with administrative tasks, reflecting the intertwining of society and state."}},{"id":"asa-080","version":2,"slug":"osh-the-plov-that-men-cook-for-a-crowd","contentType":"note","category":"food-and-hospitality","title":{"ar":"أوش: الطبق الذي يطبخه الرجال للجميع","de":"Osch: das Plov, das Männer für viele kochen","en":"Osh: the plov that men cook for a crowd"},"deck":{"ar":"في أوزبكستان وطاجيكستان، يُعد الأوش (أو البلو) طبق الأرز مع لحم الضأن والجزر والبصل والتوابل في قدر كبير، وهو محور الضيافة.","de":"In Usbekistan und Tadschikistan ist Osch, auch Plov genannt, ein Reisgericht mit Hammel, Karotten, Zwiebeln und Gewürzen aus dem großen Kasan – das Herzstück der Gastfreundschaft.","en":"In Uzbekistan and Tajikistan, osh, or plov, is a rice dish of mutton, carrots, onions and spices cooked in a large kazan – the centrepiece of hospitality."},"teaser":{"ar":"طبق الأرز الذي يجمع الناس، يطبخه الرجال في الساحات، وكل منطقة تفاخر بطريقتها الخاصة.","de":"Das Reisgericht, das Menschen zusammenbringt: Männer kochen es im Hof, und jede Region ist stolz auf ihre eigene Art.","en":"The rice dish that brings people together, cooked by men in courtyards, with every region proud of its own style."},"readingMinutes":1,"sections":{"ar":[{"heading":"طبق الضيافة والمناسبات","paragraphs":["الأوش، أو البلو، هو طبق الأرز مع لحم الضأن والجزر والبصل والتوابل، يُطبخ في قدر كبير يُسمى قازان، ويُعد محور الضيافة الأوزبكية.","غالبًا ما يطبخه الرجال في الساحات لحفلات الزفاف والجنازات وفعاليات الحي، والوصفة مصدر فخر إقليمي. يختلف الطهي حسب المنطقة والجيل، لكن روح الضيافة تبقى."]},{"heading":"فن الطهي والتنوع الإقليمي","paragraphs":["لكل منطقة أسلوبها: بلو سمرقند يرتب المكونات بشكل مختلف عن طشقند، وبخارى تستخدم خلطة توابلها الخاصة. يستطيع الطاهي الماهر (أوشباز) إطعام المئات من نار واحدة، وترتيب إضافة الأرز والماء يخضع لسيطرة صارمة.","كما يُباع الأوش كطعام شارع في أيام الأسبوع من قدور تفور، وفي كازاخستان يُسمى بالاو. تختلف الوصفات والطقوس حسب المنطقة والعائلة، وصورة طبخ الرجال مثالية اجتماعية وليست قاعدة مطلقة؛ فالنسخ اليومية أبسط وأرخص."]}],"de":[{"heading":"Ein Gericht der Gastfreundschaft","paragraphs":["Osch, oder Plov, ist ein Reisgericht mit Hammelfleisch, Karotten, Zwiebeln und Gewürzen, das in einem großen Kasan zubereitet wird und im Mittelpunkt usbekischer Gastfreundschaft steht.","Oft kochen Männer es im Hof für Hochzeiten, Beerdigungen und Nachbarschaftsfeste, und das Rezept ist eine Quelle regionalen Stolzes. Die Zubereitung variiert je nach Region und Generation, doch der Geist der Gastfreundschaft bleibt."]},{"heading":"Kochkunst und regionale Vielfalt","paragraphs":["Jede Region hat ihren Stil: Samarkand-Plov schichtet die Zutaten anders als Taschkent, und Buchara verwendet eine eigene Gewürzmischung. Ein Meisterkoch (Oschpaz) kann Hunderte von einem einzigen Feuer sättigen, und die Reihenfolge beim Hinzufügen von Reis und Wasser ist streng geregelt.","Plov wird auch als Straßenessen unter der Woche aus dampfenden Kesseln verkauft, und in Kasachstan heißt es Palau. Rezepte und Rituale unterscheiden sich je nach Region und Familie, und das Bild der kochenden Männer ist ein gesellschaftliches Ideal, keine absolute Regel; Alltagsversionen sind einfacher und günstiger."]}],"en":[{"heading":"A dish of hospitality and events","paragraphs":["Osh, or plov, is a rice dish of mutton, carrots, onions and spices cooked in a large kazan (cauldron); it is the centrepiece of Uzbek hospitality.","Cooking is often done by men in the courtyard for weddings, funerals and neighbourhood events, and the recipe is a source of regional pride. Preparation varies by region and generation, but the spirit of hospitality remains."]},{"heading":"Craft and regional variety","paragraphs":["Each region has a style: Samarkand plov layers ingredients differently from Tashkent, and Bukhara uses its own spice mix. A master cook (oshpaz) can feed hundreds from a single fire, and the order of adding rice and water is tightly controlled.","Plov is also a weekday street food sold from steaming cauldrons, and in Kazakhstan it is called palau. Recipes and rituals differ by region and family, and the men-cooking image is a social ideal rather than an absolute rule; everyday versions are simpler and cheaper."]}]},"context":{"countries":["UZ","TJ"],"region":"Uzbekistan","continent":"asia","languages":["uz","tg"],"period":"contemporary"},"tags":["food-and-hospitality","Uzbekistan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pilaf","de":"Pilaf","en":"Pilaf"},"url":"https://en.wikipedia.org/wiki/Pilaf","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Uzbek cuisine","de":"Uzbek cuisine","en":"Uzbek cuisine"},"url":"https://en.wikipedia.org/wiki/Uzbek_cuisine","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"قبل حفل زفاف عند الفجر، يضع ثلاثة رجال لحم الضأن في قدر ضخم، يضيفون الجزر الأصفر والأرز، وبحلول الظهر يخدمون مئات الضيوف من نفس القدر.","de":"Im Morgengrauen vor einer Hochzeit geben drei Männer Hammelfleisch in einen riesigen Kasan, fügen gelbe Karotten und Reis hinzu, und bis Mittag bedienen sie Hunderte von Gästen aus demselben Topf.","en":"At dawn before a wedding three men lower mutton into a huge kazan, add yellow carrots and rice, and by noon serve hundreds of guests from the same pot."},"misunderstanding":{"ar":"يُعتقد أحيانًا أن الأوش طبق احتفالي فقط، لكنه أيضًا طعام شارع يومي يُباع من قدور تفور.","de":"Manchmal wird angenommen, Plov sei nur ein Festgericht, doch es ist auch ein alltägliches Straßenessen aus dampfenden Kesseln.","en":"It is sometimes assumed that plov is only a festive dish, but it is also an everyday street food sold from steaming cauldrons."},"comparison":{"ar":"في كازاخستان يُعرف الطبق باسم بالاو، بينما في أوزبكستان وطاجيكستان يُسمى أوش أو بلو، مع اختلافات إقليمية في الترتيب والتوابل.","de":"In Kasachstan heißt das Gericht Palau, während es in Usbekistan und Tadschikistan Osch oder Plov genannt wird, mit regionalen Unterschieden in Schichtung und Gewürzen.","en":"In Kazakhstan the dish is called palau, while in Uzbekistan and Tajikistan it is known as osh or plov, with regional differences in layering and spices."}},{"id":"eur-001","version":2,"slug":"hygge-is-about-belonging-not-candles-and-blankets","contentType":"note","category":"everyday-life","title":{"ar":"هيغّه: الانتماء لا الشموع والبطانيات","de":"Hygge bedeutet Zugehörigkeit, nicht Kerzen und Decken","en":"Hygge is about belonging, not candles and blankets"},"deck":{"ar":"كلمة دنماركية تصف مزاجاً دافئاً وحميمياً، لا نمط ديكور.","de":"Ein dänisches Wort für eine warme, gesellige Stimmung – kein Einrichtungsstil.","en":"A Danish word for a warm, convivial mood, not an interior design style."},"teaser":{"ar":"هيغّه ليست وصفة سعادة تجارية، بل عادة اجتماعية يومية تجعل الضيوف مرتاحين وتخلق شعوراً بالانتماء.","de":"Hygge ist kein kommerzielles Glücksrezept, sondern eine alltägliche soziale Praxis, die Gäste entspannt und Gemeinschaft schafft.","en":"Hygge is not a commercial happiness recipe but an everyday social practice that puts guests at ease and builds a sense of belonging."},"readingMinutes":1,"sections":{"ar":[{"heading":"معنى هيغّه الحقيقي","paragraphs":["هيغّه كلمة دنماركية ونرويجية تعني مزاجاً مريحاً ومبهجاً، وليست أسلوباً في تزيين المنازل. الفكرة حديثة العهد كهوية دنماركية، رغم قِدَم الكلمة، إذ تعود إلى أواخر القرن العشرين.","في الحياة اليومية، تتشكل هيغّه من أشياء بسيطة: وجبات مشتركة، ضوء شموع، قهوة، ألعاب طاولة، ودون محاولة إبهار أحد. وهي التزام اجتماعي بقدر ما هي متعة؛ يُتوقع من المضيفين راحة الضيوف، ومن الضيوف الحفاظ على جو هادئ."]},{"heading":"هيغّه في المدارس والعمل","paragraphs":["تستخدم المدارس وأماكن العمل الدنماركية هيغّه عمداً لبناء تماسك المجموعة، عبر ساعات هيغّه الصفية وأمسيات الفريق. هذا يختلف بين الأجيال والمناطق، فالشباب قد يمارسونها بشكل أقل تقليدية."]}],"de":[{"heading":"Die wahre Bedeutung von Hygge","paragraphs":["Hygge ist ein dänisches und norwegisches Wort für eine gemütliche, gesellige Stimmung, kein Einrichtungsstil. Die moderne Idee von Hygge als Teil der dänischen Identität ist jung und stammt aus dem späten 20. Jahrhundert.","Im Alltag besteht Hygge aus einfachen Dingen: gemeinsame Mahlzeiten, Kerzenlicht, Kaffee, Brettspiele – ohne jemanden beeindrucken zu wollen. Es ist ebenso soziale Verpflichtung wie Vergnügen: Gastgeber sollen Gäste bequem machen, Gäste die entspannte Stimmung erhalten."]},{"heading":"Hygge in Schule und Beruf","paragraphs":["Dänische Schulen und Arbeitsplätze nutzen Hygge gezielt für den Gruppenzusammenhalt, etwa mit Klassen-Hygge-Stunden und Teamabenden. Je nach Region und Generation wird Hygge unterschiedlich gelebt; Jüngere praktizieren sie oft weniger traditionell."]}],"en":[{"heading":"The real meaning of hygge","paragraphs":["Hygge is a Danish and Norwegian word for a comfortable, convivial mood, not a style of interior decoration. The modern idea of hygge as a defining part of Danish identity is recent, dating from the late 20th century, even though the word itself is old.","In everyday life, hygge is made of low-key things: shared meals, candlelight, coffee, board games, and not trying to impress anyone. It works as a social obligation as much as a pleasure: hosts are expected to make guests comfortable, and guests to help keep the mood relaxed."]},{"heading":"Hygge at school and work","paragraphs":["Danish schools and workplaces use hygge deliberately to build group cohesion, for example with class 'hygge hours' and team evenings. It varies by region and generation; younger Danes often practise it less traditionally."]}]},"context":{"countries":["DK"],"region":"Scandinavia","continent":"europe","languages":["da"],"period":"contemporary"},"tags":["everyday-life","Scandinavia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hygge","de":"Hygge","en":"Hygge"},"url":"https://en.wikipedia.org/wiki/Hygge","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Denmark","de":"Culture of Denmark","en":"Culture of Denmark"},"url":"https://en.wikipedia.org/wiki/Culture_of_Denmark","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أمسية نوفمبر المظلمة، يبقى الزملاء بعد العمل لتناول القهوة والكعك في شقة أحدهم، هواتفهم مقلوبة، دون برنامج سوى الحديث.","de":"An einem dunklen Novemberabend bleiben Kollegen nach der Arbeit in der Wohnung eines Kollegen bei Kaffee und Kuchen, Handys mit dem Bildschirm nach unten, ohne Programm außer Gesprächen.","en":"On a dark November evening, colleagues stay after work for coffee and cake in a colleague's flat, phones face-down, with no programme beyond talking."},"misunderstanding":{"ar":"يُسوَّق لهيغّه في الخارج كوصفة دنماركية للسعادة، لكن الدنماركيين أنفسهم يختلفون حول ما إذا كانت سمة وطنية أو مثالاً برجوازياً أو علامة تجارية.","de":"Hygge wird im Ausland oft als dänisches Glücksrezept vermarktet; Dänen selbst streiten, ob es Nationalcharakter, bürgerliches Ideal oder Marke ist.","en":"Hygge is often marketed abroad as a Danish recipe for happiness; Danes themselves disagree about whether it is a national trait, a middle-class ideal or a commercial brand."},"comparison":{"ar":"بينما تُباع هيغّه كمنتج، تظل في الدنمارك عادة اجتماعية جماعية تُبنى على المشاركة والانتماء.","de":"Während Hygge als Produkt verkauft wird, bleibt sie in Dänemark eine gemeinschaftliche soziale Praxis, die auf Teilhabe und Zugehörigkeit beruht.","en":"While hygge is sold as a product, in Denmark it remains a collective social practice built on participation and belonging."}},{"id":"eur-002","version":2,"slug":"cohousing-the-danish-village-inside-the-city","contentType":"note","category":"cities-and-community","title":{"ar":"بيوتٌ حول مطبخٍ مشترك","de":"Ein Dorf mitten in der Stadt","en":"A village inside the city"},"deck":{"ar":"في الدنمارك، يختار بعض السكان حياةً جماعيةً صغيرة داخل المدينة: شققٌ خاصة حول بيتٍ مشترك، وقراراتٌ تُتَّخذ بالتوافق.","de":"In Dänemark leben manche Menschen in kleinen, selbstverwalteten Nachbarschaften: eigene Wohnungen um ein gemeinsames Haus, Entscheidungen im Konsens.","en":"In Denmark some people live in small, self-governing neighbourhoods: private homes around a shared house, decisions made by consensus."},"teaser":{"ar":"بدأت الفكرة في الدنمارك أواخر الستينيات، حين سئم الناس من العزلة العائلية ومن أبراجٍ سكنية باردة.","de":"Die Idee entstand Ende der 1960er in Dänemark, aus Unzufriedenheit mit isolierten Kleinfamilien und unpersönlichen Wohnblöcken.","en":"The idea began in Denmark in the late 1960s, out of frustration with isolated nuclear families and impersonal housing blocks."},"readingMinutes":1,"sections":{"ar":[{"heading":"بيتٌ واحد للجميع","paragraphs":["السكن الجماعي مجتمعٌ مقصود يحكم نفسه: بيوتٌ خاصة تتجمّع حول مساحةٍ مشتركة، وقد وُلد المصطلح في الدنمارك أواخر الستينيات.","لكلِّ أسرةٍ مطبخها، لكنّ الجيران يتقاسمون بيتًا فيه غرفة طعام ومغسلة وغرفٌ للضيوف، ويطبخون ويأكلون معًا بالتناوب.","بُني أول مجتمع حديث قرب كوبنهاغن عام 1972، تعبيرًا عن ضيقٍ بالعائلات المنعزلة وبالعمارات التي لا روح فيها."]},{"heading":"قراراتٌ بلا مالك","paragraphs":["تُتَّخذ القرارات في لقاءاتٍ دورية للسكان بالتوافق، لا بأمرٍ من مالكٍ أو شركة عقارية.","انتشر النموذج إلى هولندا والسويد والولايات المتحدة وبريطانيا، لكن الدنمارك تبقى أكثر بلدٍ يعرفه نسبةً إلى سكانه.","يختلف الأمر بين الأجيال والمناطق: شبانٌ في المدن الكبرى يقبلون عليه، وأسرٌ في البلدات الصغيرة تفضّل البيت التقليدي."]}],"de":[{"heading":"Ein Haus für alle","paragraphs":["Cohousing ist eine bewusste, selbstverwaltete Gemeinschaft privater Wohnungen um einen gemeinsamen Raum; der Begriff stammt aus Dänemark der späten 1960er.","Jede Familie hat ihre eigene Küche, teilt aber ein Gemeinschaftshaus mit Esszimmer, Waschküche und Gästezimmern; gekocht und gegessen wird meist reihum zusammen.","Die erste moderne Siedlung entstand 1972 bei Kopenhagen – als Antwort auf die Isolation der Kleinfamilie und die Anonymität großer Wohnblöcke."]},{"heading":"Entscheiden ohne Vermieter","paragraphs":["Entschieden wird bei regelmäßigen Treffen der Bewohner im Konsens, nicht durch einen Vermieter oder eine Immobiliengesellschaft.","Das Modell verbreitete sich in die Niederlande, nach Schweden, in die USA und nach Großbritannien; nirgends ist es gemessen an der Bevölkerung so verbreitet wie in Dänemark.","Je nach Region und Generation unterscheidet sich die Praxis: Jüngere in großen Städten zeigen Interesse, Familien auf dem Land bleiben oft beim klassischen Eigenheim."]}],"en":[{"heading":"One house for everyone","paragraphs":["Cohousing is an intentional, self-governing community of private homes clustered around shared space, and the term originated in Denmark in the late 1960s.","Residents keep their own kitchens but share a common house with a dining room, laundry and guest rooms, and they usually cook and eat together on a rota.","The first modern community was built near Copenhagen in 1972, born of dissatisfaction with both isolated nuclear families and impersonal housing blocks."]},{"heading":"Deciding without a landlord","paragraphs":["Decisions are taken at regular residents' meetings by consensus rather than by a landlord or property company.","The model has spread to the Netherlands, Sweden, the United States and Britain, but Denmark remains the country where it is most widespread relative to population.","Practice varies by region and generation: younger people in larger cities show interest, while families in smaller towns often stay with ordinary houses."]}]},"context":{"countries":["DK"],"region":"Scandinavia","continent":"europe","languages":["da"],"period":"contemporary"},"tags":["cities-and-community","Scandinavia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Cohousing","de":"Cohousing","en":"Cohousing"},"url":"https://en.wikipedia.org/wiki/Cohousing","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Intentional community","de":"Intentional community","en":"Intentional community"},"url":"https://en.wikipedia.org/wiki/Intentional_community","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يطبخ أحد السكان العشاء لخمسةٍ وعشرين جارًا مرةً في الشهر، بينما تسرد لوحةٌ إعلانية من عليه الدور لبقية الأسبوع.","de":"Ein Bewohner kocht einmal im Monat für 25 Nachbarn in der Gemeinschaftsküche, während eine Tafel zeigt, wer für den Rest der Woche dran ist.","en":"A resident cooks dinner for 25 neighbours once a month in the common kitchen, while a noticeboard lists whose turn it is for the rest of the week."},"misunderstanding":{"ar":"يُظنّ أحيانًا أنه سكنٌ مشترك في كل شيء، لكن لكلِّ أسرةٍ بابها ومطبخها وخصوصيتها.","de":"Man hält es oft für völlig gemeinsames Wohnen, doch jede Familie behält Tür, Küche und Privatsphäre.","en":"People sometimes assume everything is shared, but each household keeps its own door, kitchen and privacy."},"comparison":{"ar":"يشبه ذلك القرية الصغيرة داخل المدينة، لكنّه خيارُ أقليةٍ لا قاعدة، وقوائم الانتظار قد تطول.","de":"Es wirkt wie ein Dorf in der Stadt, bleibt aber eine Minderheitenwahl; die Wartelisten können lang sein.","en":"It resembles a small village inside the city, yet it is a minority choice with long waiting lists, not the Danish norm."}},{"id":"eur-003","version":2,"slug":"fika-the-swedish-coffee-break-that-structures-the-workday","contentType":"note","category":"food-and-hospitality","title":{"ar":"فيكا: استراحة القهوة السويدية","de":"Fika: Schwedens strukturierte Kaffeepause","en":"Fika: Sweden's scheduled coffee break"},"deck":{"ar":"كيف أصبحت استراحة قهوة مجدولة جزءاً من يوم العمل في السويد","de":"Wie eine feste Kaffeepause den schwedischen Arbeitstag gliedert","en":"How a fixed coffee pause shapes the Swedish workday"},"teaser":{"ar":"فيكا ليست مجرد قهوة، بل لحظة اجتماعية منظمة تجمع الزملاء مرتين يومياً، وتعكس إيقاع الحياة السويدية.","de":"Fika ist mehr als Kaffee: eine soziale Auszeit, die Kollegen zweimal täglich zusammenbringt und den Rhythmus des schwedischen Arbeitslebens prägt.","en":"Fika is more than coffee: a social pause that brings colleagues together twice a day and sets the rhythm of Swedish working life."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس يومي في العمل","paragraphs":["فيكا هي استراحة قهوة مجدولة، غالباً مع شيء حلو، تؤخذ عادة مرتين يومياً في أماكن العمل السويدية. الكلاسيكي هو كعكة القرفة، لكن الهدف هو التوقف والرفقة وليس المعجنات.","فيكا اجتماعية وليست فردية: يُتوقع من الزملاء ترك العمل معاً، ودعوة شخص ما لفيكا طريقة غير رسمية للتعرف عليه. تختلف العادات حسب مكان العمل: بعض المكاتب تحدد أوقاتاً صارمة، وأخرى تعتبرها ذريعة غير رسمية، ويُستخدم المصطلح أيضاً لقهوة مع الأصدقاء أو أي استراحة قصيرة."]},{"heading":"خلفية الكلمة والعادة","paragraphs":["الكلمة مقلوب لفظ «كافي»، وهو شكل لهجي قديم لكلمة «قهوة»، والعادة تعود إلى القرن التاسع عشر عندما أصبحت القهوة في متناول الجميع وتكاثرت المقاهي. تحتل السويد مرتبة متقدمة بين أكبر مستهلكي القهوة في العالم، وغالباً ما تكون فيكا المناسبة الرئيسية لشربها."]}],"de":[{"heading":"Ein tägliches Ritual am Arbeitsplatz","paragraphs":["Fika ist eine fest eingeplante Kaffeepause, meist mit etwas Süßem, die an schwedischen Arbeitsplätzen oft zweimal täglich stattfindet. Klassisch ist die Zimtschnecke, doch entscheidend sind die Pause und die Gesellschaft, nicht das Gebäck.","Fika ist sozial, nicht einsam: Kollegen legen gemeinsam die Arbeit nieder, und jemanden auf eine Fika einzuladen ist ein unkomplizierter Weg, ihn kennenzulernen. Die Bräuche unterscheiden sich je nach Arbeitsplatz: Manche Büros halten strenge Zeiten ein, andere sehen darin einen informellen Anlass, und das Wort steht auch für Kaffee mit Freunden oder jede kurze Pause."]},{"heading":"Wortgeschichte und Herkunft","paragraphs":["Das Wort ist eine Umkehrung von „kaffi“, einer alten Dialektform von „Kaffee“, und die Gewohnheit stammt aus dem 19. Jahrhundert, als Kaffee erschwinglich wurde und Kaffeehäuser zunahmen. Schweden zählt zu den größten Kaffeekonsumenten pro Kopf weltweit, und Fika ist oft der Hauptanlass, ihn zu trinken."]}],"en":[{"heading":"A daily ritual at work","paragraphs":["Fika is a scheduled coffee break, usually with something sweet, often taken twice a day at Swedish workplaces. The classic accompaniment is a cinnamon bun, but the point is the pause and the company rather than the pastry.","Fika is social rather than solitary: colleagues are expected to down tools together, and inviting someone to fika is a low-key way to get to know them. Customs differ by workplace: some offices keep strict times, others treat it as an informal excuse, and the word is also used for coffee with friends or any short break."]},{"heading":"Word history and origins","paragraphs":["The word is a reversal of kaffi, an old dialect form of 'coffee', and the habit dates from the 19th century, when coffee became affordable and coffee houses multiplied. Sweden ranks among the world's biggest coffee consumers per head, and fika is often the main occasion for drinking it."]}]},"context":{"countries":["SE"],"region":"Scandinavia","continent":"europe","languages":["sv"],"period":"contemporary"},"tags":["food-and-hospitality","Scandinavia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Coffee in Sweden","de":"Coffee in Sweden","en":"Coffee in Sweden"},"url":"https://en.wikipedia.org/wiki/Coffee_in_Sweden","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Sweden","de":"Culture of Sweden","en":"Culture of Sweden"},"url":"https://en.wikipedia.org/wiki/Culture_of_Sweden","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في التاسعة والنصف من صباح ثلاثاء، يفرغ مكتب سويدي إلى المطبخ لتناول القهوة وكعكة، وتُجدول الاجتماعات حول الاستراحة وليس خلالها.","de":"Dienstagmorgen um 9.30 Uhr leert sich ein schwedisches Büro in die Küche für Kaffee und ein Gebäck, und Besprechungen werden um die Pause herum geplant, nicht durch sie hindurch.","en":"At 9.30 on a Tuesday a Swedish office empties into the kitchen for coffee and a bun, and meetings are scheduled around the break rather than through it."},"misunderstanding":{"ar":"يُفهم أحياناً أن فيكا مجرد شرب قهوة سريع، لكنها في الواقع مناسبة اجتماعية منظمة.","de":"Manchmal wird Fika als schneller Kaffee missverstanden, doch tatsächlich ist es ein festes soziales Ereignis.","en":"Fika is sometimes mistaken for a quick coffee, but it is actually a fixed social occasion."},"comparison":{"ar":"بينما تُشرب القهوة في كثير من الثقافات على عجل أمام الشاشة، فإن فيكا تفرض توقفاً جماعياً.","de":"Während Kaffee in vielen Kulturen eilig vor dem Bildschirm getrunken wird, erzwingt Fika einen gemeinsamen Halt.","en":"While coffee is often rushed at a desk in many cultures, fika enforces a shared stop."}},{"id":"eur-004","version":2,"slug":"janteloven-the-ten-rules-that-tell-you-not-to-be-special","contentType":"note","category":"social-behaviour","title":{"ar":"قانون يانتي: عشر قواعد تطلب ألا تكون مميزاً","de":"Janteloven: zehn Regeln gegen das Besonderssein","en":"Janteloven: ten rules against standing out"},"deck":{"ar":"رواية ساخرة من 1933 صاغت عبارة يتداولها الاسكندنافيون حتى اليوم لوصف ضغط اجتماعي يرفض التفاخر.","de":"Ein satirischer Roman von 1933 prägte einen Begriff, der in Skandinavien bis heute einen sozialen Druck beschreibt, der sichtbaren Ehrgeiz ablehnt.","en":"A satirical 1933 novel coined a phrase Scandinavians still use for a social pressure that frowns on visible ambition and self-promotion."},"teaser":{"ar":"من بلدة خيالية في الدنمارك إلى نقاشات الرواتب في النرويج، كيف تحوّلت عشر قواعد إلى مقياس للتواضع؟","de":"Von einer erfundenen Kleinstadt in Dänemark bis zu Gehaltsdebatten in Norwegen: Wie wurden zehn Regeln zum Maßstab für Bescheidenheit?","en":"From a fictional Danish small town to salary talk in Norway, how did ten rules become a yardstick for modesty?"},"readingMinutes":1,"sections":{"ar":[{"heading":"من رواية إلى عُرف اجتماعي","paragraphs":["صاغ الكاتب الدنماركي النرويجي أكسل ساندموسه قانون يانتي في روايته «هارب يعبر آثاره» عام 1933، على شكل عشر قواعد تبدأ بعبارة «لا يحق لك أن تظن أنك شيء مميز». وتدور الأحداث في بلدة خيالية صغيرة تُدعى يانتي، مستوحاة من نيكوبينغ مورس في الدنمارك.","كانت الرواية سخرية من الانصياع في البلدات الصغيرة، لكن المصطلح صار يُستخدم في عموم اسكندنافيا لوصف موقف اجتماعي لا يرتاح للطموح الظاهر أو الترويج للذات.","وفي النرويج كثيراً ما يُستشهد بالقانون لتفسير أعراف المساواة، من التردد في الحديث عن الرواتب إلى توقع أن يبقى لاعبو كرة القدم متواضعين. والملاحظ أن المدن والأجيال الشابة تتحرر منه شيئاً فشيئاً."]},{"heading":"تواضع مطلوب وثمنه","paragraphs":["هذا النمط صورة نمطية لها آثار حقيقية: تشير أبحاث الإدارة في بلدان الشمال إلى أن القادة مطالبون بتخفيف مظاهر المكانة، وأن المنافسة العلنية قد تكون مكلفة اجتماعياً.","لكن قانون يانتي يصف موقفاً يشكو منه الناس بقدر ما يتبعونه؛ فمعظم النرويجيين لا يحبون أن يُقال إن ثقافتهم تميل إلى الانصياع.","وقد يبدو الفارق بسيطاً بين التواضع والإنكار، لكنه يظهر بوضوح في اللحظات التي يُفترض فيها الاحتفاء بالإنجاز الفردي."]}],"de":[{"heading":"Vom Roman zur sozialen Norm","paragraphs":["Der dänisch-norwegische Autor Aksel Sandemose erfand das Gesetz von Jante in seinem Roman „Ein Flüchtling kreuzt seine Spur“ von 1933, in Form von zehn Regeln, die mit „Du sollst nicht glauben, dass du etwas Besonderes bist“ beginnen. Der Schauplatz ist die erfundene Kleinstadt Jante, nach dem Vorbild von Nykøbing Mors in Dänemark.","Der Roman verspottete die Anpassung in Kleinstädten, doch heute dient der Begriff in ganz Skandinavien für eine Haltung, die sichtbaren Ehrgeiz oder Selbstvermarktung missbilligt.","In Norwegen wird das Gesetz oft zur Erklärung egalitärer Normen zitiert, vom Zögern, über Gehälter zu sprechen, bis zur Erwartung, dass Fußballer bescheiden bleiben. In Städten und bei Jüngeren verliert es merklich an Kraft."]},{"heading":"Erwartete Bescheidenheit und ihr Preis","paragraphs":["Das Klischee hat reale Wirkungen: Nordische Managementforschung zeigt, dass Führungskräfte ihren Status herunterspielen sollen und offener Wettbewerb sozial teuer werden kann.","Doch Janteloven beschreibt eine Haltung, über die Menschen ebenso oft klagen, wie sie ihr folgen; die meisten Norweger hören ungern, ihre Kultur sei angepasst.","Der Unterschied zwischen Bescheidenheit und Verleugnung wirkt klein, wird aber in Momenten sichtbar, in denen individueller Erfolg gefeiert werden soll."]}],"en":[{"heading":"From novel to social norm","paragraphs":["The Danish-Norwegian author Aksel Sandemose invented the Law of Jante in his 1933 novel A Fugitive Crosses His Tracks, as ten rules opening with “You shall not think you are something special.” It is set in the fictional small town of Jante, modelled on Nykøbing Mors in Denmark.","The novel satirised small-town conformity, but the term is now used across Scandinavia for an attitude that disapproves of visible ambition or self-promotion.","In Norway the law is often cited to explain egalitarian norms, from reluctance to discuss salaries to the expectation that footballers stay humble. Urban and younger circles are noticeably less bound by it."]},{"heading":"Expected modesty and its cost","paragraphs":["It is a stereotype with real effects: Nordic management research notes that leaders are expected to downplay status and that open competition can be socially costly.","Yet Janteloven describes an attitude people complain about as often as they follow; most Norwegians dislike being told their culture is conformist.","The line between modesty and denial looks thin, but it shows clearly in moments meant to celebrate individual achievement."]}]},"context":{"countries":["NO"],"region":"Scandinavia","continent":"europe","languages":["nb"],"period":"contemporary"},"tags":["social-behaviour","Scandinavia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Law of Jante","de":"Law of Jante","en":"Law of Jante"},"url":"https://en.wikipedia.org/wiki/Law_of_Jante","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Egalitarianism","de":"Egalitarianism","en":"Egalitarianism"},"url":"https://en.wikipedia.org/wiki/Egalitarianism","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"حين يفوز نرويجي بجائزة، تكون كلمة الشكر أقرب إلى شكر الفريق والجيران من التوقف عند الإنجاز الشخصي.","de":"Wenn ein Norweger einen Preis gewinnt, dankt die Rede eher dem Team und den Nachbarn, als die eigene Leistung zu betonen.","en":"When a Norwegian wins a prize, the acceptance speech is more likely to thank the team and the neighbours than to dwell on personal achievement."},"misunderstanding":{"ar":"يُفهم أحياناً كقانون مكتوب أو قاعدة رسمية تُفرض على الناس، بينما هو أداة ساخرة من رواية صارت تعبيراً شعبياً عن ضغط اجتماعي غير مكتوب.","de":"Manchmal wird es als geschriebenes Gesetz oder offizielle Regel verstanden, obwohl es eine satirische Erfindung aus einem Roman ist, die zum geflügelten Wort für unsichtbaren sozialen Druck wurde.","en":"It is sometimes taken as a written law or official rule, though it began as satire in a novel and became a shorthand for unwritten social pressure."},"comparison":{"ar":"يشبه في أثره ضغط «الخشبة العالية» في بعض الثقافات، حيث يُنتقد من يبرز فوق الآخرين، لكنه في اسكندنافيا مرتبط بخطاب المساواة لا بالحسد وحده.","de":"Es ähnelt dem Druck des „hohen Mohns“ in anderen Kulturen, wo auffällige Menschen kritisiert werden, ist in Skandinavien aber stärker an Gleichheitsdiskurse als an reinen Neid geknüpft.","en":"It echoes the “tall poppy” pressure found in other cultures, where visible people draw criticism, but in Scandinavia it is tied more to equality talk than to envy alone."}},{"id":"eur-005","version":2,"slug":"friluftsliv-and-the-right-to-walk-across-other-people-s-land","contentType":"note","category":"nature-and-seasons","title":{"ar":"حق المشي في أراضي الآخرين","de":"Das Recht, über fremdes Land zu gehen","en":"The right to walk across other people's land"},"deck":{"ar":"في الدول الاسكندنافية، الهواء الطلق أسلوب حياة، والقانون يسمح لك بالمرور عبر أرض الغير بشرط احترام البيوت والطبيعة.","de":"In Skandinavien ist Friluftsliv Alltag, und das Gesetz erlaubt den Durchgang über privates Land, solange Häuser und Natur respektiert werden.","en":"In Scandinavia, open-air life is everyday practice, and the law lets you cross private land as long as you respect houses and nature."},"teaser":{"ar":"فري لوفتسليف يعني الحياة في الهواء الطلق، وحق التجول يمنح الجميع حرية المشي والتخييم في الأراضي غير المزروعة.","de":"Friluftsliv heißt Leben im Freien, und das Jedermannsrecht erlaubt allen, unkultiviertes Land zu Fuß zu durchqueren und dort zu zelten.","en":"Friluftsliv means open-air life, and the right to roam lets everyone walk and camp on uncultivated land, with clear duties attached."},"readingMinutes":1,"sections":{"ar":[{"heading":"حياة في الهواء الطلق","paragraphs":["فري لوفتسليف، أي «الحياة في الهواء الطلق»، هو المثال الاسكندنافي لقضاء الوقت خارج البيت، من نزهة الأحد إلى قطف التوت والمبيت في العراء، دون بذل جهد كبير أو إنفاق كثير.","هذا المثال عادة اجتماعية ملزمة بقدر ما هو حق قانوني: الجبال مشتركة، وكذلك واجب إغلاق البوابات وتجنب المحاصيل وحمل النفايات إلى البيت."]},{"heading":"حق التجول وحدوده","paragraphs":["حق التجول، المسمى «أليمانسريتن» في النرويج، يتيح المشي والتزلج وركوب الدراجة والتخييم في الأراضي الخاصة غير المزروعة، بشرط الابتعاد عن المنازل وعدم ترك أي نفايات.","قنّن قانون الترفيه في الهواء الطلق النرويجي الصادر عام 1957 هذا العرف، وتوجد حقوق مماثلة في السويد وفنلندا وأيسلندا واسكتلندا.","القواعد دقيقة: في النرويج يمكن التخييم لليلتين على الأكثر في أرض غير مزروعة، على مسافة 150 متراً على الأقل من كوخ أو منزل، وإشعال النار ممنوع في مناطق كثيرة صيفاً.","تختلف التفاصيل بين النرويج والسويد وفنلندا، كما تتباين ممارسة هذه الحقوق بين الأجيال والمناطق، إذ يتمسك بها بعض الشباب في المدن أكثر من غيرهم."]}],"de":[{"heading":"Leben im Freien","paragraphs":["Friluftsliv, das „Leben im Freien“, ist das skandinavische Ideal, Zeit draußen zu verbringen, vom Sonntagsspaziergang über das Beerensammeln bis zum Übernachten im Zelt, ohne weit zu fahren oder viel auszugeben.","Dieses Ideal ist ebenso verbindliche soziale Norm wie gesetzliches Recht: Die Berge gehören allen, aber auch die Pflicht, Tore zu schließen, Felder zu meiden und Müll mit nach Hause zu nehmen."]},{"heading":"Jedermannsrecht und seine Grenzen","paragraphs":["Das Jedermannsrecht, in Norwegen Allemannsretten genannt, erlaubt Gehen, Skifahren, Radfahren und Zelten auf unkultiviertem Privatland, sofern man Abstand zu Häusern hält und keinen Abfall hinterlässt.","Norwegens Gesetz über die Erholung im Freien von 1957 kodifizierte diesen Brauch, ähnliche Rechte gibt es in Schweden, Finnland, Island und Schottland.","Die Regeln sind genau: In Norwegen darf man bis zu zwei Nächte auf unkultiviertem Land zelten, mindestens 150 Meter von einer Hütte oder einem Haus entfernt, und offene Feuer sind im Sommer in vielen Bezirken verboten.","Die Einzelheiten unterscheiden sich zwischen Norwegen, Schweden und Finnland, und auch die Nutzung variiert je nach Region und Generation, wobei manche Stadtjugendliche das Recht stärker verteidigen als andere."]}],"en":[{"heading":"A life lived outdoors","paragraphs":["Friluftsliv, or 'open-air life', is the Scandinavian ideal of spending time outdoors, from Sunday walks to berry picking and overnight camping, without going far or spending much.","The ideal is a binding social norm as well as a legal right: the mountains are shared, but so is the obligation to close gates, avoid crops and carry rubbish home."]},{"heading":"The right to roam and its limits","paragraphs":["The right to roam, called allemannsretten in Norway, lets people walk, ski, cycle and camp on uncultivated private land, provided they keep their distance from houses and leave no litter.","Norway's Outdoor Recreation Act of 1957 codified the custom, and similar everyman's rights exist in Sweden, Finland, Iceland and Scotland.","The rules are specific: in Norway one may camp for up to two nights on uncultivated land, at least 150 metres from a cabin or house, and open fires are banned in many districts in summer.","The details differ between Norway, Sweden and Finland, and how strongly the right is used varies by region and generation, with some young city dwellers defending it more firmly than others."]}]},"context":{"countries":["NO","SE","FI"],"region":"Northern Europe","continent":"europe","languages":["nb","sv","fi"],"period":"contemporary"},"tags":["nature-and-seasons","Northern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Freedom to roam","de":"Freedom to roam","en":"Freedom to roam"},"url":"https://en.wikipedia.org/wiki/Freedom_to_roam","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Norway","de":"Culture of Norway","en":"Culture of Norway"},"url":"https://en.wikipedia.org/wiki/Culture_of_Norway","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تقضي عائلة نرويجية أحد الأيام في التزلج على مسار غابي معلّم، وتتوقف لتناول البرتقال والشوكولاتة الساخنة من ترمس مع بقية المارّين.","de":"Eine norwegische Familie verbringt einen Sonntag auf einem markierten Waldweg mit Skifahren und hält wie alle anderen unterwegs für Orangen und heiße Schokolade aus der Thermoskanne.","en":"A Norwegian family spends a Sunday skiing a marked forest trail, stopping for oranges and hot chocolate from a thermos along with everyone else on the route."},"misunderstanding":{"ar":"يظن البعض أن حق التجول يعني حرية مطلقة في دخول أي مكان، لكنه لا يشمل الحدائق والحقول المزروعة في موسم النمو ولا التنقل بالمركبات.","de":"Manche glauben, das Jedermannsrecht erlaube den Zutritt überall, doch Gärten, bestellte Felder in der Wachstumszeit und motorisierte Fahrten sind ausgenommen.","en":"Some assume the right to roam means access everywhere, but it excludes gardens, cultivated fields in the growing season and motorised travel."},"comparison":{"ar":"في كثير من البلدان يقتصر المرور على مسارات محددة، أما هنا فالأرض المفتوحة مشتركة، مع واجبات واضحة تجاه الأرض وأصحابها.","de":"In vielen Ländern ist das Gehen auf bestimmte Wege beschränkt, hier gehört das offene Land allen, mit klaren Pflichten gegenüber Boden und Eigentümern.","en":"In many countries walking is confined to set paths, whereas here open land is shared, with clear duties towards the ground and its owners."}},{"id":"eur-006","version":2,"slug":"in-finland-the-sauna-is-a-room-for-politics-business-and-silence","contentType":"note","category":"everyday-life","title":{"ar":"الساونا في فنلندا: غرفة للسياسة والعمل والصمت","de":"Sauna in Finnland: Raum für Politik, Business und Stille","en":"In Finland the sauna is a room for politics, business and silence"},"deck":{"ar":"في فنلندا، الساونا ليست مجرد مكان للاسترخاء، بل مساحة اجتماعية ووسيلة للتواصل وحل الخلافات.","de":"In Finnland ist die Sauna mehr als ein Ort der Entspannung – sie ist ein sozialer Raum, ein Kommunikationsmittel und ein Ort der Konfliktlösung.","en":"In Finland, the sauna is more than a place to relax—it is a social space, a communication tool, and a way to resolve conflicts."},"teaser":{"ar":"مع نحو ثلاثة ملايين ساونا لسكان يبلغ عددهم 5.5 مليون نسمة، تعد الساونا واحدة من أكثر المباني شيوعًا في فنلندا، وتلعب دورًا محوريًا في الحياة اليومية.","de":"Mit rund drei Millionen Saunen für etwa 5,5 Millionen Einwohner ist die Sauna eines der häufigsten Gebäude Finnlands und spielt eine zentrale Rolle im Alltag.","en":"With roughly three million saunas for a population of about 5.5 million, the sauna is one of Finland's most ordinary buildings and plays a central role in everyday life."},"readingMinutes":1,"sections":{"ar":[{"heading":"أكثر من مجرد غرفة ساخنة","paragraphs":["في فنلندا، الساونا هي جزء لا يتجزأ من الحياة اليومية. يوجد حوالي ثلاثة ملايين ساونا لسكان يبلغ عددهم 5.5 مليون نسمة، مما يجعلها واحدة من أكثر المباني شيوعًا. إنها ليست رفاهية، بل عادة متجذرة في الثقافة الفنلندية.","الجلسة اجتماعية وغير مستعجلة: يجلس الناس معًا، ويرمون الماء على الحجارة الساخنة لإنتاج البخار (löyly)، ثم يبردون في الخارج أو في البحيرة أو في الثلج. هذه الممارسة تعزز الروابط الاجتماعية والتواصل."]},{"heading":"مساحة للحديث الصعب","paragraphs":["منذ فترة طويلة، كانت الساونا مساحة محايدة للمحادثات الصعبة. استخدمها المفاوضون والمديرون الفنلنديون لعقد الاجتماعات، حيث يساعد الجو الهادئ على فتح الحوار. في ديسمبر 2020، أُدرجت ثقافة الساونا الفنلندية في قائمة اليونسكو للتراث الثقافي غير المادي. كما أن الساونا ليست خاصة فقط: الساونا العامة وقاعات السباحة وساونا البيوت الصيفية كلها تغذي هذه العادة، مع فرش البتولا والغطس البارد كجزء من التجربة."]}],"de":[{"heading":"Mehr als nur ein heißer Raum","paragraphs":["In Finnland ist die Sauna ein fester Bestandteil des täglichen Lebens. Es gibt etwa drei Millionen Saunen für 5,5 Millionen Einwohner, was sie zu einem der häufigsten Gebäude macht. Sie ist kein Luxus, sondern eine tief verwurzelte kulturelle Gewohnheit.","Eine Sitzung ist gesellig und ungezwungen: Man sitzt zusammen, gießt Wasser auf die heißen Steine für den Löyly und kühlt sich draußen, im See oder im Schnee ab. Diese Praxis stärkt soziale Bindungen und Kommunikation."]},{"heading":"Raum für schwierige Gespräche","paragraphs":["Die Sauna dient seit langem als neutraler Raum für schwierige Gespräche. Finnische Unterhändler und Manager nutzen sie für Meetings, da die ruhige Atmosphäre den Dialog fördert. Im Dezember 2020 wurde die finnische Saunakultur in die UNESCO-Liste des immateriellen Kulturerbes aufgenommen. Saunen sind nicht nur privat: Öffentliche Saunen, Schwimmhallen und Sommerhaus-Saunen erhalten die Gewohnheit, mit Birkenwedel und kaltem Tauchbad als Teil des Erlebnisses."]}],"en":[{"heading":"More than just a hot room","paragraphs":["In Finland, the sauna is an integral part of daily life. There are about three million saunas for 5.5 million people, making it one of the country's most common buildings. It is not a luxury but a deeply rooted cultural habit.","A session is social and unhurried: people sit together, throw water on the hot stones for löyly, and cool off outside, in a lake or in the snow. This practice strengthens social bonds and communication."]},{"heading":"A space for difficult conversations","paragraphs":["The sauna has long served as a neutral space for difficult conversations. Finnish negotiators and managers have used it for meetings, as the calm atmosphere helps open dialogue. In December 2020, Finnish sauna culture was inscribed on UNESCO's Intangible Cultural Heritage list. Saunas are not only private: public saunas, swimming halls and summer-cottage saunas all sustain the habit, with the birch whisk and a cold plunge as part of the experience."]}]},"context":{"countries":["FI"],"region":"Northern Europe","continent":"europe","languages":["fi"],"period":"contemporary"},"tags":["everyday-life","Northern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Finnish sauna","de":"Finnish sauna","en":"Finnish sauna"},"url":"https://en.wikipedia.org/wiki/Finnish_sauna","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Sauna","de":"Sauna","en":"Sauna"},"url":"https://en.wikipedia.org/wiki/Sauna","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تتجادل عائلة فنلندية حول خطط الصيف، ثم تذهب إلى الساونا معًا؛ لا يُسمح لأحد بالبقاء غاضبًا في الحرارة.","de":"Eine finnische Familie streitet über die Sommerpläne und geht dann gemeinsam in die Sauna; niemand darf in der Hitze wütend bleiben.","en":"A Finnish family argues about plans for the summer, then goes to the sauna together; nobody is allowed to stay angry in the heat."},"misunderstanding":{"ar":"يعتقد البعض أن الساونا مجرد مكان للعرق والاسترخاء الجسدي، لكنها في فنلندا مساحة اجتماعية للتواصل وحل الخلافات.","de":"Manche halten die Sauna für einen reinen Ort des Schwitzens und der körperlichen Entspannung, doch in Finnland ist sie ein sozialer Raum für Gespräche und Konfliktlösung.","en":"Some think the sauna is just a place to sweat and relax physically, but in Finland it is a social space for conversation and conflict resolution."},"comparison":{"ar":"تختلف عادات الساونا من الهادئ والتأملي إلى الصاخب؛ قائمة اليونسكو تغطي الممارسة الفنلندية، بينما لدى إستونيا المجاورة تقليد مميز لساونا الدخان.","de":"Saunagewohnheiten reichen von ruhig und fast meditativ bis ausgelassen; die UNESCO-Listung umfasst die finnische Praxis, während das benachbarte Estland eine eigene Rauchsauna-Tradition hat.","en":"Sauna customs range from quiet and almost meditative to boisterous; the UNESCO listing covers Finnish practice, and neighbouring Estonia has a distinct smoke-sauna tradition."}},{"id":"eur-008","version":2,"slug":"why-icelanders-are-in-the-telephone-book-by-first-name","contentType":"note","category":"family-and-friendship","title":{"ar":"أسماء الآباء في آيسلندا","de":"Isländer im Telefonbuch nach Vornamen","en":"Icelanders in the Phone Book by First Name"},"deck":{"ar":"في آيسلندا، يُنادَى الناس بأسمائهم الأولى حتى في المواقف الرسمية، ودليل الهاتف مرتّب حسب الاسم الأول لا العائلة.","de":"In Island spricht man Menschen selbst in formellen Situationen mit dem Vornamen an, und das Telefonbuch ist nach Vornamen sortiert, nicht nach Nachnamen.","en":"In Iceland, people are addressed by first name even in formal situations, and the telephone book is sorted by given name rather than surname."},"teaser":{"ar":"نظام الأسماء الآيسلندي يعتمد على اسم الأب أو الأم، فيتغيّر اللقب كل جيل، ويُعرَف الناس بأسمائهم الأولى.","de":"Das isländische Namenssystem basiert auf dem Vater- oder Mutternamen, sodass sich der Nachname mit jeder Generation ändert und Menschen mit Vornamen bekannt sind.","en":"The Icelandic naming system relies on the father's or mother's name, so surnames change each generation and people are known by their first names."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف تُبنى الأسماء","paragraphs":["معظم الآيسلنديين لا يحملون لقب عائلة: يأخذ الطفل اسم الأب مضافًا إليه son أو dóttir، وأحيانًا اسم الأم، لذا يتغيّر الجزء الأخير من الاسم من جيل إلى جيل.","وهذا يعني أن أفراد الأسرة لا يتشاركون اللقب، مما قد يربك البنوك وضباط الحدود، ويسافر الآيسلنديون غالبًا بوثائق إضافية."]},{"heading":"الحياة اليومية والنداء","paragraphs":["يُنادَى الناس بأسمائهم الأولى حتى في المواقف الرسمية، ودليل الهاتف مرتّب حسب الاسم الأول وليس اللقب، فالأخوان يُدرجان تحت الحرف نفسه.","لجنة حكومية لتسمية الأسماء يجب أن توافق على الأسماء الجديدة، وقد اختار الآباء تاريخيًا أسماء تتوافق مع قواعد اللغة الآيسلندية والنوع الاجتماعي. ومنذ قانون 2019، يمكن تسجيل اسم محايد بين الجنسين دون إثبات هوية جندرية ثنائية، بعد سنوات من الحملات. ويختلف الالتزام بهذه القواعد حسب المنطقة والجيل، فبعض العائلات تحتفظ بألقاب موروثة نادرة."]}],"de":[{"heading":"Wie Namen gebildet werden","paragraphs":["Die meisten Isländer haben keinen Familiennamen: Ein Kind nimmt das Patronym (den Namen des Vaters plus son oder dóttir) und gelegentlich ein Matronym, sodass sich der letzte Namensteil von Generation zu Generation ändert.","Das bedeutet, dass Familienmitglieder keinen gemeinsamen Nachnamen haben, was Banken und Grenzbeamte verwirren kann, und Isländer reisen oft mit zusätzlichen Dokumenten."]},{"heading":"Alltag und Anrede","paragraphs":["Menschen werden selbst in formellen Situationen mit dem Vornamen angesprochen, und das Telefonbuch ist nach Vornamen sortiert, nicht nach Nachnamen, sodass zwei Brüder unter demselben Buchstaben stehen.","Ein staatliches Namenskomitee muss neue Vornamen genehmigen, und Eltern mussten historisch einen Namen wählen, der zur isländischen Grammatik und den Geschlechterregeln passt. Seit einem Gesetz von 2019 können Antragsteller einen geschlechtsneutralen Namen registrieren, ohne eine binäre Geschlechtsidentität nachweisen zu müssen, eine Änderung nach jahrelangen Kampagnen. Die Einhaltung dieser Regeln variiert je nach Region und Generation, und einige Familien tragen seltene ererbte Nachnamen."]}],"en":[{"heading":"How Names Are Built","paragraphs":["Most Icelanders have no family surname: a child takes a patronymic (father's name plus son or dóttir) and occasionally a matronymic, so the last part of a name changes from one generation to the next.","This means family members do not share a surname, which can confuse banks and border officers, and Icelanders often travel with extra documentation."]},{"heading":"Everyday Life and Address","paragraphs":["People are addressed by first name even in formal situations, and the telephone book is sorted by given name rather than surname, so two brothers are listed under the same letter.","A government naming committee must approve new given names, and parents have historically had to choose a name that fits Icelandic grammar and gender rules. Since a 2019 law, applicants can register a gender-neutral name without having to prove a binary gender identity, a change that followed years of campaigning. Adherence to these rules varies by region and generation, and some families hold rare inherited surnames."]}]},"context":{"countries":["IS"],"region":"North Atlantic","continent":"europe","languages":["is"],"period":"contemporary"},"tags":["family-and-friendship","North Atlantic"],"sources":[{"organization":"Wikipedia","title":{"ar":"Icelandic name","de":"Icelandic name","en":"Icelandic name"},"url":"https://en.wikipedia.org/wiki/Icelandic_name","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Patronymic","de":"Patronymic","en":"Patronymic"},"url":"https://en.wikipedia.org/wiki/Patronymic","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يظهر الشقيقان الآيسلنديان جون سيغورذسون وأولافور سيغورذسون في دليل الهاتف تحت حرف J، لأن الإدراج يتبع الأسماء الأولى.","de":"Die beiden isländischen Brüder Jón Sigurðsson und Ólafur Sigurðsson stehen im Telefonbuch beide unter J, weil die Einträge nach Vornamen erfolgen.","en":"Two Icelandic brothers are listed as Jón Sigurðsson and Ólafur Sigurðsson in the phone book, both under J, because the listings follow first names."},"misunderstanding":{"ar":"يعتقد البعض أن الآيسلنديين يفتقرون إلى ألقاب عائلية بسبب الفوضى، لكن النظام مقصود ويعكس روابط القرابة.","de":"Manche glauben, Isländer hätten keine Nachnamen aus Chaos, aber das System ist beabsichtigt und spiegelt Verwandtschaftsbeziehungen wider.","en":"Some think Icelanders lack surnames due to chaos, but the system is intentional and reflects kinship ties."},"comparison":{"ar":"على عكس العديد من المجتمعات حيث اللقب ثابت، في آيسلندا يتغيّر اللقب مع كل جيل، مما يعيد تشكيل الهوية العائلية.","de":"Anders als in vielen Gesellschaften, in denen der Nachname stabil ist, ändert sich in Island der Nachname mit jeder Generation, was die familiäre Identität neu gestaltet.","en":"Unlike many societies where the surname is stable, in Iceland the surname changes with each generation, reshaping family identity."}},{"id":"eur-009","version":2,"slug":"huldufolk-the-hidden-people-who-still-appear-in-planning-disputes","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"الهولدفولك: الجيران الخفيون في أيسلندا","de":"Huldufólk: die verborgenen Nachbarn Islands","en":"Huldufólk: Iceland's hidden neighbours"},"deck":{"ar":"كيف تتداخل حكايات الجان مع قرارات البناء والحياة اليومية في أيسلندا.","de":"Wie Elfen­geschichten Bauentscheidungen und den Alltag in Island bis heute prägen.","en":"How elf stories still shape building decisions and everyday life in Iceland."},"teaser":{"ar":"في أيسلندا، لا تزال حكايات 'الشعب المخفي' حاضرة في النقاشات حول الطرق والبناء، وفي جولات سياحية ترويها الأجيال.","de":"In Island sind die Erzählungen vom ‚verborgenen Volk‘ noch immer präsent – in Bauprojekten, in Führungen und in der Art, wie man über Landschaft spricht.","en":"In Iceland, tales of the 'hidden people' remain present in road and construction debates, in guided walks, and in how people talk about landscape."},"readingMinutes":1,"sections":{"ar":[{"heading":"من هم الشعب المخفي؟","paragraphs":["الهولدفولك، أو 'الشعب المخفي'، هم الجان وكائنات خارقة أخرى في الفولكلور الأيسلندي، يُقال إنهم يعيشون في الصخور والتلال وحقول الحمم. الاعتقاد بهم نادراً ما يكون عقيدة دينية، بل موقف ثقافي: وجدت استطلاعات أن أقلية كبيرة من الأيسلنديين تقول إن الجان قد يكونون موجودين، وكثيرون غير مستعدين لنفي وجودهم تماماً.","في القرن التاسع عشر، جُمعت قصصهم إلى جانب الحكايات الخرافية، واستُخدمت لتعليم الأطفال احترام المناظر الطبيعية الخطرة. هذا المزيج بين الحكاية والتحذير ما زال قائماً."]},{"heading":"عندما تلتقي الأسطورة بالجرافة","paragraphs":["للفولكلور عواقب عملية: أحياناً عُدّلت مشاريع الطرق والبناء بعد أن جادل نشطاء بأن صخرة ما هي مسكن جان. في إحدى الحالات، طلب سائق جرافة في حقل حمم ترك صخرة وشأنها لأنها تُنسب للشعب المخفي، فالتفّ المقاول حولها بهدوء.","تختلف درجة التمسك بهذه القصص بين المناطق والأجيال؛ ففي ريكيافيك الحضرية يُنظر إليها غالباً كتراث، بينما في الريف قد تحمل وزناً أكبر. مدرسة الجان في ريكيافيك وجولات 'المشي مع الجان' الموسمية تُظهر كيف أصبحت الحكايات تُؤدى للزوار كما تُروى في البيت."]}],"de":[{"heading":"Wer sind die Huldufólk?","paragraphs":["Huldufólk, das ‚verborgene Volk‘, sind Elfen und andere übernatürliche Wesen der isländischen Folklore, von denen es heißt, sie lebten in Felsen, Hügeln und Lavafeldern. Der Glaube ist selten kirchliche Lehre, sondern eine kulturelle Haltung: Umfragen zeigen, dass eine beträchtliche Minderheit der Isländer sagt, Elfen könnten existieren, und viele mehr zögern, sie ganz auszuschließen.","Im 19. Jahrhundert wurden diese Geschichten zusammen mit Märchen gesammelt und genutzt, um Kindern Respekt vor gefährlichen Landschaften beizubringen. Diese Verbindung von Erzählung und Warnung besteht fort."]},{"heading":"Wenn die Sage auf den Bagger trifft","paragraphs":["Die Folklore hat praktische Folgen: Manchmal wurden Straßen- und Bauprojekte geändert, nachdem Aktivisten argumentierten, ein Felsen sei eine Elfenwohnung. In einem Fall bittet ein Baggerfahrer in einem Lavafeld darum, einen Felsen unberührt zu lassen, weil er dem verborgenen Volk gehören soll – der Bauunternehmer umfährt ihn still.","Wie stark diese Geschichten getragen werden, variiert regional und generationell: Im urbanen Reykjavík gelten sie oft als Erbe, auf dem Land können sie mehr Gewicht haben. Die Elfenschule in Reykjavík und saisonale ‚Elfenwanderungen‘ zeigen, wie die Folklore heute für Besucher aufgeführt und zu Hause weitererzählt wird."]}],"en":[{"heading":"Who are the hidden people?","paragraphs":["Huldufólk ('hidden people') are the elves and other supernatural beings of Icelandic folklore, said to live in rocks, hills and lava fields. Belief is rarely literal church doctrine but a cultural attitude: surveys have found that a substantial minority of Icelanders say elves may exist, and many more are reluctant to rule them out.","In the 19th century, stories about hidden people were collected alongside fairy tales and were used to teach children respect for dangerous landscapes. That mix of storytelling and warning persists."]},{"heading":"When folklore meets the bulldozer","paragraphs":["The folklore has practical consequences: road and construction projects have sometimes been altered after campaigners argued that a rock was an elf dwelling. In one case, a bulldozer operator in a lava field asks for a rock to be left alone because it is said to belong to the hidden people, and the contractor quietly works around it.","Attachment to these stories varies by region and generation; in urban Reykjavík they are often treated as heritage, while in the countryside they may carry more weight. The elf school in Reykjavík and seasonal 'elf walks' show how the folklore is now performed for visitors as well as told at home."]}]},"context":{"countries":["IS"],"region":"North Atlantic","continent":"europe","languages":["is"],"period":"contemporary"},"tags":["beliefs-and-folklore","North Atlantic"],"sources":[{"organization":"Wikipedia","title":{"ar":"Huldufólk","de":"Huldufólk","en":"Huldufólk"},"url":"https://en.wikipedia.org/wiki/Hulduf%C3%B3lk","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Nordic folklore","de":"Nordic folklore","en":"Nordic folklore"},"url":"https://en.wikipedia.org/wiki/Nordic_folklore","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"سائق جرافة في حقل حمم يطلب ترك صخرة وشأنها لأنها تُقال إنها ملك للشعب المخفي، فيعمل المقاول حولها بهدوء.","de":"Ein Baggerfahrer in einem Lavafeld bittet darum, einen Felsen unberührt zu lassen, weil er dem verborgenen Volk gehören soll, und der Bauunternehmer arbeitet still um ihn herum.","en":"A bulldozer operator in a lava field asks for a rock to be left alone because it is said to belong to the hidden people, and the contractor quietly works around it."},"misunderstanding":{"ar":"الاعتقاد بالجان ليس بالضرورة إيماناً حرفياً؛ فأيسلندا بلد حديث وعلماني، ومعظم الناس لا يعتقدون حرفياً بوجود الجان، لكن القصص تهم كتراث وكحذر بيئي وكطريقة للحديث عن المناظر الطبيعية.","de":"Der Elfenglaube ist nicht unbedingt wörtlich; Island ist ein modernes, säkulares Land, und die meisten Menschen glauben nicht buchstäblich an Elfen. Die Geschichten zählen als Erbe, als ökologische Vorsicht und als Art, über Landschaft zu sprechen.","en":"Belief in elves is not necessarily literal; Iceland is a modern, secular country and most people do not believe in elves literally. The stories matter as heritage, as environmental caution and as a way of talking about landscape, and survey numbers vary widely."},"comparison":{"ar":"في كثير من الثقافات، تُروى حكايات مشابهة عن كائنات تسكن الطبيعة، لكن ما يميز الحالة الأيسلندية هو تحولها أحياناً إلى عامل في التخطيط العمراني والنقاش العام.","de":"In vielen Kulturen gibt es ähnliche Erzählungen über Wesen, die die Natur bewohnen, doch in Island können sie gelegentlich zu einem Faktor in Raumplanung und öffentlicher Debatte werden.","en":"Many cultures tell similar stories about beings inhabiting nature, but in Iceland such tales can occasionally become a factor in planning and public debate."}},{"id":"eur-010","version":2,"slug":"the-estonian-song-festival-where-30-000-people-sing-together","contentType":"note","category":"music-and-dance","title":{"ar":"مهرجان الأغنية الإستوني: 30 ألف صوت في آن واحد","de":"Estlands Sängerfest: 30.000 Stimmen vereint","en":"Estonia's Song Festival: 30,000 Voices as One"},"deck":{"ar":"منذ عام 1869، يجتمع الإستونيون كل خمس سنوات تقريبًا في تالين ليغنوا معًا، في تقليد عائلي تحول إلى رمز وطني.","de":"Seit 1869 kommen Esten etwa alle fünf Jahre in Tallinn zusammen, um gemeinsam zu singen – eine Familientradition, die zum nationalen Symbol wurde.","en":"Since 1869, Estonians have gathered roughly every five years in Tallinn to sing together—a family tradition that became a national symbol."},"teaser":{"ar":"في مهرجان الأغنية الإستوني، يلتقي أكثر من 30 ألف مغنٍّ على مسرح واحد، حاملين تراثًا عائليًا وذاكرة وطنية تتجاوز حدود الموسيقى.","de":"Beim estnischen Sängerfest singen über 30.000 Menschen auf einer Bühne. Es ist ein Familientradition und ein nationales Symbol, das über die Musik hinausgeht.","en":"At Estonia's Song Festival, more than 30,000 singers share one stage, carrying a family tradition and a national memory that goes beyond music."},"readingMinutes":1,"sections":{"ar":[{"heading":"تقليد عائلي يمتد عبر الأجيال","paragraphs":["انطلق مهرجان الأغنية الإستوني (لاولوبيدو) عام 1869، ويُقام كل خمس سنوات تقريبًا منذ عام 1923 في ساحة مهرجان الأغنية بتالين. يشارك في الجوقة المشتركة أكثر من 30 ألف مغنٍّ، ويتابعهم جمهور يصل إلى 80 ألفًا، مما يجعله أحد أكبر الأحداث الكورالية في العالم.","المشاركة فيه تقليد عائلي ينتقل عبر الأجيال؛ فالجدات والأمهات والبنات يتدربن لأشهر قبل الحفل الختامي. وتختلف حدة هذا التقليد بين المناطق والمدن، كما تتباين مشاركة الأجيال الشابة حسب الظروف المحلية."]},{"heading":"صوت الأمة تحت الحكم السوفيتي","paragraphs":["أصبح المهرجان رمزًا وطنيًا في ظل الحكم السوفيتي، حيث كان الغناء الجماعي بالأغاني الإستونية شكلًا مسموحًا به للتعبير الوطني. وفي عام 1988، غذّى هذا التقليد ما عُرف بالثورة الغنائية التي أدت إلى الاستقلال.","المهرجان مدرج لدى اليونسكو كتحفة من التراث الشفهي وغير المادي للبشرية، ويجمع بين الأغاني الشعبية والكلاسيكيات الكورالية وأعمال جديدة تُكلَّف خصيصًا للمهرجان."]}],"de":[{"heading":"Eine Familientradition über Generationen","paragraphs":["Das estnische Sängerfest (Laulupidu) wurde erstmals 1869 gefeiert und findet seit 1923 etwa alle fünf Jahre auf dem Sängerfestgelände in Tallinn statt. Der gemeinsame Chor umfasst mehr als 30.000 Sänger vor bis zu 80.000 Zuschauern – eines der größten Chorfeste der Welt.","Die Teilnahme ist eine Familientradition über Generationen: Großmütter, Mütter und Töchter proben monatelang vor dem Abschlusskonzert. Je nach Region und Generation variiert die Intensität dieses Brauchs, und die Beteiligung junger Menschen ist lokal unterschiedlich."]},{"heading":"Die Stimme der Nation unter sowjetischer Herrschaft","paragraphs":["Unter sowjetischer Herrschaft wurde das Fest zum nationalen Symbol: Das gemeinsame Singen estnischer Lieder war eine erlaubte Form des nationalen Ausdrucks. 1988 nährte es die Singende Revolution, die zur Unabhängigkeit führte.","Die UNESCO listet das Fest als Meisterwerk des mündlichen und immateriellen Erbes der Menschheit. Das Repertoire mischt Volkslieder, Chorklassiker und eigens in Auftrag gegebene neue Werke."]}],"en":[{"heading":"A Family Tradition Across Generations","paragraphs":["The Estonian Song Festival (Laulupidu) was first held in 1869 and has taken place roughly every five years since 1923 at the Song Festival Grounds in Tallinn. The joint choir has numbered more than 30,000 singers performing to an audience of up to 80,000—one of the largest choral events in the world.","Participation is a family tradition across generations: grandmothers, mothers, and daughters rehearse for months before the final concert. The intensity of this custom varies by region and generation, and younger people's involvement differs from place to place."]},{"heading":"The Nation's Voice Under Soviet Rule","paragraphs":["The festival became a national symbol under Soviet rule: singing Estonian songs together was a permitted form of national expression. In 1988 it fed the Singing Revolution that led to independence.","UNESCO lists it as a Masterpiece of the Oral and Intangible Heritage of Humanity, and the repertoire mixes folk songs, choral classics, and new commissions."]}]},"context":{"countries":["EE"],"region":"Baltic states","continent":"europe","languages":["et"],"period":"contemporary"},"tags":["music-and-dance","Baltic states"],"sources":[{"organization":"Wikipedia","title":{"ar":"Estonian Song Festival","de":"Estonian Song Festival","en":"Estonian Song Festival"},"url":"https://en.wikipedia.org/wiki/Estonian_Song_Festival","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Singing Revolution","de":"Singing Revolution","en":"Singing Revolution"},"url":"https://en.wikipedia.org/wiki/Singing_Revolution","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"جدة وابنتها وحفيدتها يسافرن إلى تالين بالأزياء الشعبية ليغرّدن في جوقات مختلفة على المسرح نفسه.","de":"Eine Großmutter, ihre Tochter und ihre Enkelin reisen in Trachten nach Tallinn, um in verschiedenen Chören auf derselben Bühne zu singen.","en":"A grandmother, her daughter, and her granddaughter travel to Tallinn in folk costumes to sing in different choirs on the same stage."},"misunderstanding":{"ar":"يُفهم المهرجان أحيانًا كحدث فلكلوري فقط، لكنه في الواقع مناسبة وطنية عاطفية ذات أبعاد سياسية واجتماعية عميقة.","de":"Das Fest wird manchmal nur als folkloristisches Ereignis gesehen, ist aber eine emotional aufgeladene nationale Veranstaltung mit politischer und sozialer Tiefe.","en":"The festival is sometimes seen as merely a folkloric event, but it is an emotionally charged national occasion with deep political and social dimensions."},"comparison":{"ar":"يشبه المهرجان في وظيفته الاجتماعية الكرنفالات الجماعية في أوروبا، لكنه يتميز بتركيزه على الغناء الكورالي كشكل من أشكال الهوية الوطنية.","de":"In seiner sozialen Funktion ähnelt es europäischen Karnevalsfesten, doch sein Fokus auf Chorgesang als Ausdruck nationaler Identität ist einzigartig.","en":"In its social function it resembles European carnival gatherings, yet its focus on choral singing as an expression of national identity is unique."}},{"id":"eur-011","version":2,"slug":"jani-midsummer-as-latvia-s-family-holiday","contentType":"note","category":"traditions","title":{"ar":"يانّي: عيد منتصف الصيف العائلي في لاتفيا","de":"Jāņi: Mittsommer als Lettlands Familienfest","en":"Jāņi: Midsummer as Latvia's Family Holiday"},"deck":{"ar":"في لاتفيا، يُحتفل بعيد يانّي كعيد عائلي وقومي، حيث تلتقي الأجيال حول نار المخيم والأغاني التقليدية.","de":"In Lettland wird Jāņi als Familien- und Nationalfest gefeiert, bei dem Generationen am Lagerfeuer zusammenkommen und traditionelle Lieder singen.","en":"In Latvia, Jāņi is celebrated as a family and national holiday, where generations gather around bonfires and sing traditional songs."},"teaser":{"ar":"يانّي هو عيد الانقلاب الصيفي في لاتفيا، حيث تتحول المدن إلى countryside، وتضاء النيران، وتُغنى أغاني ليغو، ويُؤكل جبن الكراوية مع البيرة.","de":"Jāņi ist Lettlands Mittsommerfest: Städter ziehen aufs Land, entzünden Feuer, singen Līgo-Lieder und essen Kümmelkäse mit Bier.","en":"Jāņi is Latvia's summer-solstice festival: city dwellers head to the countryside, light bonfires, sing Līgo songs, and eat caraway cheese with beer."},"readingMinutes":1,"sections":{"ar":[{"heading":"ليلة ليغو: عندما تترك المدينة خلفك","paragraphs":["في الثالث والعشرين من يونيو، مساء ليغو، يغادر الكثيرون المدن إلى الريف. تُشعل النيران وتبقى مشتعلة طوال الليل القصير، بينما تُغنى أغاني ليغو التقليدية. الرجال يضعون أكاليل من أوراق البلوط والنساء أكاليل من الزهور، ثم تُرمى الأكاليل لاحقًا على الأسطح أو في الماء في ألعاب حظ. العائلات تجتمع حول النار، تأكل جبن الكراوية وتشرب البيرة، في جو من المرح والتقاليد. تختلف العادات حسب المنطقة والعائلة، فبعض الشباب يحتفلون في حدائق المدن أو في مهرجانات موسيقية."]},{"heading":"من الانقلاب الصيفي إلى الهوية اللاتفية","paragraphs":["يعود عيد يانّي إلى ما قبل المسيحية، وقد نجا جزئيًا بدمجه في عيد القديس يوحنا. حاولت السلطات السوفيتية السيطرة عليه، لكنه أصبح تأكيدًا هادئًا للهوية اللاتفية. يُحتفل به أيضًا بين الشتات اللاتفي في الولايات المتحدة وكندا والأرجنتين وأستراليا. في لاتفيا، يُعتبر يومي 23 و24 يونيو عطلتين رسميتين، مما يمنح العائلات وقتًا للالتقاء والاحتفال. تختلف الممارسات بين الأجيال، فبينما يتمسك الكبار بالتقاليد الريفية، يبتكر الشباب طرقًا جديدة للاحتفال."]}],"de":[{"heading":"Līgo-Abend: Wenn die Stadt hinter sich gelassen wird","paragraphs":["Am 23. Juni, dem Līgo-Abend, verlassen viele die Städte und fahren aufs Land. Lagerfeuer werden entzündet und brennen durch die kurze Nacht, während traditionelle Līgo-Lieder gesungen werden. Männer tragen Eichenlaubkränze, Frauen Blumenkränze, die später bei Glücksspielen auf Dächer oder ins Wasser geworfen werden. Familien versammeln sich am Feuer, essen Kümmelkäse und trinken Bier. Die Bräuche variieren je nach Region und Familie; viele jüngere Letten feiern in Stadtparks oder bei Musikfestivals."]},{"heading":"Vom Sonnwendfest zur lettischen Identität","paragraphs":["Jāņi reicht vor das Christentum zurück und überlebte teilweise durch die Eingliederung in das Johannisfest. Die sowjetischen Behörden versuchten, es zu kontrollieren, doch es wurde zu einer stillen Bekräftigung der lettischen Identität. Auch die lettische Diaspora in den USA, Kanada, Argentinien und Australien feiert es. In Lettland sind der 23. und 24. Juni gesetzliche Feiertage, was Familien Zeit zum Feiern gibt. Die Praktiken unterscheiden sich zwischen den Generationen: Ältere halten an ländlichen Traditionen fest, Jüngere entwickeln neue Formen."]}],"en":[{"heading":"Līgo Evening: Leaving the City Behind","paragraphs":["On 23 June, Līgo evening, many leave the cities for the countryside. Bonfires are lit and kept burning through the short night, while traditional Līgo songs are sung. Men wear oak-leaf wreaths and women flower wreaths, which are later thrown onto roofs or into water in fortune-telling games. Families gather around the fire, eat caraway cheese and drink beer. Customs vary by region and family; many younger Latvians celebrate in city parks or at music festivals."]},{"heading":"From Solstice to Latvian Identity","paragraphs":["Jāņi predates Christianity and survived partly by being folded into the feast of St John. The Soviet authorities tried to control it, but it became a quiet assertion of Latvian identity. The Latvian diaspora in the United States, Canada, Argentina and Australia also celebrates it. In Latvia, 23 and 24 June are both public holidays, giving families time to celebrate. Practices differ between generations: older people keep rural traditions, while younger ones invent new ways."]}]},"context":{"countries":["LV"],"region":"Baltic states","continent":"europe","languages":["lv"],"period":"contemporary"},"tags":["traditions","Baltic states"],"sources":[{"organization":"Wikipedia","title":{"ar":"Jāņi","de":"Jāņi","en":"Jāņi"},"url":"https://en.wikipedia.org/wiki/J%C4%81%C5%86i","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Latvia","de":"Culture of Latvia","en":"Culture of Latvia"},"url":"https://en.wikipedia.org/wiki/Culture_of_Latvia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة من ريغا تقود سيارتها إلى مزرعة في 23 يونيو، وتنضم إلى الجيران حول نار المخيم، وتغني 'ليغو!' وتبقى مستيقظة حتى يضيء السماء مرة أخرى.","de":"Eine Familie aus Riga fährt am 23. Juni zu einem Bauernhof, gesellt sich zu den Nachbarn am Lagerfeuer, singt 'Līgo!' und bleibt auf, bis der Himmel wieder hell wird.","en":"A Riga family drives to a farm on 23 June, joins the neighbours around a bonfire, sings 'Līgo!' and stays up until the sky is light again."},"misunderstanding":{"ar":"يعتقد البعض أن يانّي عيد ديني بحت، لكنه في الواقع festival وثني قديم اندمج مع المسيحية، والكثير من اللاتفيين اليوم يحتفلون به كعيد قومي وثقافي أكثر منه ديني.","de":"Manche halten Jāņi für ein rein religiöses Fest, doch es ist ein altes heidnisches Sonnwendfest, das mit dem Christentum verschmolz; viele Letten feiern es heute eher national und kulturell.","en":"Some think Jāņi is purely religious, but it is an ancient pagan solstice festival that merged with Christianity; many Latvians today celebrate it more as a national and cultural holiday."},"comparison":{"ar":"يشبه يانّي احتفالات الانقلاب الصيفي في دول البلطيق الأخرى، لكنه يتميز بأغاني ليغو وجبن الكراوية وأكاليل البلوط والزهور، مما يجعله فريدًا في لاتفيا.","de":"Jāņi ähnelt den Mittsommerfesten der anderen baltischen Staaten, zeichnet sich aber durch Līgo-Lieder, Kümmelkäse und Eichenlaub- sowie Blumenkränze aus.","en":"Jāņi resembles midsummer festivals in the other Baltic states, but stands out with its Līgo songs, caraway cheese, and oak-leaf and flower wreaths."}},{"id":"eur-012","version":2,"slug":"the-lithuanian-book-smugglers-who-defied-the-tsar","contentType":"note","category":"cultural-change","title":{"ar":"مهربو الكتب الليتوانيون يتحدون القيصر","de":"Litauische Bücherschmuggler trotzen dem Zaren","en":"Lithuanian book smugglers who defied the Tsar"},"deck":{"ar":"بين عامي 1865 و1904، حظرت الإمبراطورية الروسية المنشورات الليتوانية بالأبجدية اللاتينية، فخاطر الفلاحون والقساوسة والمعلمون بتهريب الكتب إلى الداخل.","de":"Von 1865 bis 1904 verbot das Russische Reich litauische Publikationen in lateinischer Schrift. Bauern, Priester und Lehrer schmuggelten Bücher ins Land.","en":"From 1865 to 1904, the Russian Empire banned Lithuanian publications in the Latin alphabet. Peasants, priests and teachers smuggled books across the border."},"teaser":{"ar":"قصة الناس الذين خبأوا الكتب في العربات والصناديق المموهة لإنقاذ لغتهم وهويتهم من سياسة الترويس.","de":"Die Geschichte der Menschen, die Bücher in Wagen und doppelten Böden versteckten, um ihre Sprache und Identität vor der Russifizierung zu retten.","en":"The story of people who hid books in carts and false-bottomed boxes to save their language and identity from Russification."},"readingMinutes":1,"sections":{"ar":[{"heading":"الحظر والتهريب","paragraphs":["من 1865 إلى 1904، منعت الإمبراطورية الروسية المنشورات الليتوانية المطبوعة بالأبجدية اللاتينية، بينما شجعت تلك المطبوعة بالأبجدية السيريلية. جاء الحظر بعد فشل انتفاضة يناير 1863، وكان جزءًا من سياسة الترويس الأوسع.","طُبعت الكتب والصحف في الخارج، خاصة في بروسيا الشرقية، وهرّبها عبر الحدود 'حاملو الكتب' (knygnešiai)، وغالبًا ما كانوا من الفلاحين والقساوسة ومعلمي المدارس. كانت العقوبات قاسية، لكن التجارة تحولت إلى قضية وطنية: أخفيت كتب الصلاة والتقاويم في الحظائر وعربات القش والصناديق ذات القيعان المزيفة."]},{"heading":"الذاكرة والإرث","paragraphs":["رُفع الحظر في عام 1904 مع انشغال السياسة الإمبراطورية بالحرب الروسية اليابانية، وتُذكر شبكة التهريب كأساس للحركة الوطنية الليتوانية الحديثة. تختلف الروايات حسب المنطقة والجيل: فبعض العائلات تتذكر أسماء المهربين، بينما يعرف آخرون القصة من الكتب المدرسية فقط."]}],"de":[{"heading":"Verbot und Schmuggel","paragraphs":["Von 1865 bis 1904 verbot das Russische Reich litauische Publikationen in lateinischer Schrift, während kyrillische gefördert wurden. Das Verbot folgte dem gescheiterten Januaraufstand von 1863 und war Teil einer umfassenderen Russifizierungspolitik.","Bücher und Zeitungen wurden im Ausland gedruckt, vor allem in Ostpreußen, und von den knygnešiai (‚Bücherträgern‘) über die Grenze geschmuggelt – oft Bauern, Priester und Lehrer. Die Strafen waren hart, doch der Handel wurde zur nationalen Sache: Gebetsbücher und Kalender versteckten sich in Scheunen, Heuwagen und Kisten mit doppeltem Boden."]},{"heading":"Erinnerung und Vermächtnis","paragraphs":["1904 wurde das Verbot aufgehoben, als der Russisch-Japanische Krieg die imperiale Politik lockerte. Das Schmuggelnetzwerk gilt als Grundlage der modernen litauischen Nationalbewegung. Je nach Region und Generation wird die Geschichte anders erzählt: Manche Familien kennen die Namen der Schmuggler, andere kennen sie nur aus Schulbüchern."]}],"en":[{"heading":"The ban and the smuggling","paragraphs":["From 1865 to 1904 the Russian Empire banned Lithuanian-language publications printed in the Latin alphabet, while allowing and encouraging Cyrillic ones. The ban followed the failed 1863 January Uprising and was part of a wider Russification policy.","Books and newspapers were printed abroad, mainly in East Prussia, and smuggled across the border by knygnešiai ('book carriers'), often peasants, priests and schoolteachers. Penalties were severe and the trade became a national cause: prayer books and calendars were hidden in barns, hay carts and false-bottomed boxes."]},{"heading":"Memory and legacy","paragraphs":["The ban was lifted in 1904 as the Russo-Japanese War loosened imperial policy, and the smuggling network is remembered as a foundation of the modern Lithuanian national movement. The story varies by region and generation: some families recall the names of smugglers, while others know it only from schoolbooks."]}]},"context":{"countries":["LT"],"region":"Baltic states","continent":"europe","languages":["lt"],"period":"contemporary"},"tags":["cultural-change","Baltic states"],"sources":[{"organization":"Wikipedia","title":{"ar":"Lithuanian press ban","de":"Lithuanian press ban","en":"Lithuanian press ban"},"url":"https://en.wikipedia.org/wiki/Lithuanian_press_ban","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Lithuanian language","de":"Lithuanian language","en":"Lithuanian language"},"url":"https://en.wikipedia.org/wiki/Lithuanian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يخفي مزارع حزمة من كتب الصلاة الليتوانية تحت كومة من القش ويعبر حدود حقل ليلاً لتسليمها إلى قرية.","de":"Ein Bauer versteckt ein Bündel litauischer Gebetsbücher unter einer Ladung Heu und überquert nachts eine Feldgrenze, um sie in einem Dorf abzuliefern.","en":"A farmer hides a bundle of Lithuanian prayer books under a load of hay and crosses a field boundary at night to deliver them to a village."},"misunderstanding":{"ar":"القصة بطولية لكنها انتقائية: تفاوت تطبيق الحظر، وتعاون بعض الليتوانيين مع السلطات، وصُقلت أسطورة 'حامل الكتب' لاحقًا من قبل المؤرخين الوطنيين.","de":"Die Geschichte ist heldenhaft, aber selektiv: Die Durchsetzung war unterschiedlich, manche Litauer kooperierten mit den Behörden, und der Mythos des ‚Bücherträgers‘ wurde später von nationalen Historikern verfeinert.","en":"The story is heroic but selective: enforcement varied, some Lithuanians cooperated with the authorities, and the 'book carrier' myth was later polished by national historians."},"comparison":{"ar":"يشبه هذا التهريب أشكال مقاومة ثقافية أخرى في أوروبا الشرقية، حيث استُخدمت اللغة كأداة للهوية في مواجهة سياسات الإمبراطوريات.","de":"Ähnlich wie andere Formen kulturellen Widerstands in Osteuropa wurde die Sprache als Mittel der Identität gegen imperiale Politik eingesetzt.","en":"Similar to other forms of cultural resistance in Eastern Europe, language was used as a tool of identity against imperial policies."}},{"id":"eur-013","version":2,"slug":"in-britain-tea-is-an-offer-a-break-and-a-clock","contentType":"note","category":"food-and-hospitality","title":{"ar":"الشاي في بريطانيا: عرض واستراحة وساعة","de":"Tee in Großbritannien: Angebot, Pause und Uhr","en":"In Britain, tea is an offer, a break and a clock"},"deck":{"ar":"من رفاهية نادرة إلى عادة يومية: كيف أصبح الشاي جزءًا من نسيج الحياة البريطانية.","de":"Vom teuren Luxusgut zum Alltagsritual: Wie Tee das britische Leben prägt.","en":"From expensive luxury to everyday ritual: how tea became woven into British life."},"teaser":{"ar":"الشاي في بريطانيا ليس مجرد مشروب، بل عرض ضيافة واستراحة عمل ومقياس للوقت، مع تباين واضح بين الأجيال والمناطق.","de":"Tee ist in Großbritannien mehr als ein Getränk: ein Angebot, eine Arbeitspause und ein Taktgeber – mit deutlichen Unterschieden zwischen Generationen und Regionen.","en":"Tea in Britain is more than a drink: it's an offer of hospitality, a work break and a way to tell time, with sharp differences by region and generation."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الكماليات إلى الروتين","paragraphs":["وصل الشاي إلى بريطانيا في القرن السابع عشر كسلعة فاخرة باهظة الثمن، ثم انتشر تدريجيًا بين جميع الطبقات. ولا تزال المملكة المتحدة من أكبر مستهلكي الشاي في العالم للفرد، بنحو 1.9 كيلوغرام سنويًا.","يشرب البريطانيون في الغالب الشاي الأسود بالحليب، وقوة الشاي وتوقيت تحضيره مسألة رأي شخصي قوي. وفي القرن التاسع عشر شاع شاي بعد الظهر مع السندويتشات والكعك، لكن الطقس اليومي هو 'الكوبا': غلاية تُعرض على الزوار والزملاء والعمال."]},{"heading":"استراحة الشاي في العمل","paragraphs":["تتخلل استراحات الشاي يوم العمل في المكاتب ومواقع البناء، وعبارة 'ضع الغلاية' طريقة معيارية لتخفيف التوتر أو بدء محادثة. وظل الشاي أكثر شعبية من القهوة في بريطانيا حتى حوالي عام 2016، عندما غيّرت المقاهي وآلات المنزل Balance."]}],"de":[{"heading":"Vom Luxus zur Routine","paragraphs":["Tee kam im 17. Jahrhundert als teures Luxusgut nach Großbritannien und verbreitete sich allmählich über alle Klassen. Das Vereinigte Königreich zählt noch immer zu den größten Teekonsumenten pro Kopf, mit etwa 1,9 kg pro Jahr.","Briten trinken meist schwarzen Tee mit Milch, und Stärke sowie Ziehzeit sind starke persönliche Meinungen. Afternoon Tea mit Sandwiches, Scones und Kuchen wurde im 19. Jahrhundert populär, doch das Alltagsritual ist der 'cuppa': ein Wasserkocher, der Besuchern, Kollegen und Handwerkern angeboten wird."]},{"heading":"Die Teepause im Arbeitsalltag","paragraphs":["Teepausen gliedern den Arbeitstag in Büros und auf Baustellen, und 'put the kettle on' ist ein Standardweg, Spannungen zu lösen oder ein Gespräch zu beginnen. Tee blieb in Großbritannien bis etwa 2016 beliebter als Kaffee, als Cafés und Heimmaschinen die Balance veränderten."]}],"en":[{"heading":"From luxury to routine","paragraphs":["Tea arrived in Britain in the 17th century as an expensive luxury and gradually spread through all classes; the UK remains one of the world's largest consumers per head, at about 1.9 kg a year.","Britons mostly drink black tea with milk, and the strength and timing of the brew are matters of strong personal opinion. Afternoon tea, with sandwiches, scones and cake, was popularised in the 19th century, but the everyday ritual is the 'cuppa': a kettle offered to visitors, colleagues and tradespeople."]},{"heading":"The tea break at work","paragraphs":["Tea breaks punctuate the working day in offices and on building sites, and 'put the kettle on' is a standard way to defuse tension or begin a conversation. Tea remained more popular than coffee in Britain until around 2016, when coffee shops and home machines changed the balance."]}]},"context":{"countries":["GB"],"region":"British Isles","continent":"europe","languages":["en"],"period":"contemporary"},"tags":["food-and-hospitality","British Isles"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tea in the United Kingdom","de":"Tea in the United Kingdom","en":"Tea in the United Kingdom"},"url":"https://en.wikipedia.org/wiki/Tea_in_the_United_Kingdom","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of the United Kingdom","de":"Culture of the United Kingdom","en":"Culture of the United Kingdom"},"url":"https://en.wikipedia.org/wiki/Culture_of_the_United_Kingdom","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يصل السباك إلى منزل بريطاني فيُعرض عليه الشاي قبل أي نقاش حول المرجل؛ الرفض ممكن، لكنه يتطلب تفسيرًا صغيرًا.","de":"Ein Klempner kommt in ein britisches Haus und bekommt Tee angeboten, bevor über die Heizung gesprochen wird; ablehnen ist möglich, erfordert aber eine kleine Erklärung.","en":"A plumber arrives at a British house and is offered tea before any discussion of the boiler; refusing is possible, but it takes a small explanation."},"misunderstanding":{"ar":"يعتقد البعض أن شاي بعد الظهر هو الطقس اليومي، لكن العادة اليومية هي الكوبا البسيط، بينما شاي بعد الظهر مناسبة خاصة.","de":"Manche halten Afternoon Tea für das tägliche Ritual, doch der Alltag ist der einfache cuppa; Afternoon Tea ist ein besonderer Anlass.","en":"Some assume afternoon tea is the daily ritual, but the everyday habit is the simple cuppa; afternoon tea is a special occasion."},"comparison":{"ar":"بينما يُقدَّم الشاي في بريطانيا كعرض ضيافة، تختلف عادات الشرب بشكل حاد حسب الطبقة والمنطقة والجيل، وتخفي صورة 'المشروب الوطني' تراجعًا حديثًا في مبيعات الشاي وازدهارًا للقهوة؛ ولاسكتلندا وويلز وأيرلندا الشمالية علاماتها وتفضيلاتها الخاصة.","de":"Während Tee in Großbritannien als Gastfreundschaftsangebot gilt, unterscheiden sich die Trinkgewohnheiten stark nach Klasse, Region und Generation; das Bild vom 'Nationalgetränk' verdeckt einen recenten Rückgang der Teeverkäufe und einen Kaffeeboom; Schottland, Wales und Nordirland haben eigene Marken und Vorlieben.","en":"While tea in Britain is offered as hospitality, drinking habits differ sharply by class, region and generation, and the 'national drink' image hides a recent decline in tea sales and a boom in coffee; Scotland, Wales and Northern Ireland have their own brands and preferences."}},{"id":"eur-015","version":2,"slug":"the-pub-as-britain-s-third-place-and-why-so-many-are-closing","contentType":"note","category":"cities-and-community","title":{"ar":"الحانة: الغرفة الثالثة في بريطانيا","de":"Der Pub als dritter Ort","en":"The pub as Britain's third place"},"deck":{"ar":"لماذا تختفي الحانات بينما كانت يوماً قلب المجتمع المحلي؟","de":"Warum schließen so viele Pubs, obwohl sie Gemeinschaftsräume sind?","en":"Why pubs close even as community rooms disappear"},"teaser":{"ar":"الحانة ليست مجرد مكان للشرب، بل غرفة مجتمعية للفرق والمسابقات والتجمعات. فلماذا تغلق أبوابها؟","de":"Der Pub ist mehr als eine Kneipe: Quizabend, Dartteam, Trauerfeier. Doch seit den 2000er Jahren schließen viele – besonders auf dem Land.","en":"The pub is more than a bar: quiz night, darts team, wake. Yet since the 2000s many have closed, with rural pubs especially vulnerable."},"readingMinutes":1,"sections":{"ar":[{"heading":"أكثر من مجرد مشروب","paragraphs":["الحانة، أو «البيت العام» كما عُرفت في أواخر القرن السابع عشر، هي مكان مرخّص للشرب. لكنها كانت دائماً أكثر من ذلك: غرفة مجتمعية لليالي المسابقات، وفرق السهام والبلياردو، والتجمعات، واجتماعات النقابات، ومشجعي كرة القدم.","تعرّف حملة البيرة الحقيقية الحانة بأربع سمات: مفتوحة للجمهور دون عضوية، تقدم البيرة أو عصير التفاح دون طعام إلزامي، ولها مساحة داخلية غير مخصصة للوجبات، وتسمح بشراء المشروبات من البار."]},{"heading":"لماذا تُغلق الأبواب؟","paragraphs":["انخفض عدد الحانات بشدة منذ العقد الأول من القرن الحادي والعشرين، مع تغيّر عادات الشرب والأسعار وانتشار الكحول في المتاجر الكبرى. الحانات الريفية هي الأكثر عرضة للخطر.","تختلف الصورة بين المناطق والأجيال: فبعض الحانات تعتمد الآن على الطعام والسياحة، وبعضها يديرها المجتمع المحلي، وتغيّرت أنماط الشرب كثيراً منذ حظر التدخين عام 2007. ولا تزال فكرة «الحانة المحلية» حنيناً بقدر ما هي وصف."]}],"de":[{"heading":"Mehr als ein Getränk","paragraphs":["Der Pub, kurz für „public house“, ist ein lizenziertes Lokal, das seinen modernen Namen im späten 17. Jahrhundert in England erhielt. Doch er war immer mehr: ein Gemeinschaftsraum für Quizabende, Dart- und Poolteams, Trauerfeiern, Gewerkschaftstreffen und Fußballfanclubs.","Die Campaign for Real Ale definiert den Pub anhand von vier Merkmalen: öffentlich zugänglich ohne Mitgliedschaft, Ausschank von Bier oder Cider ohne Essenszwang, ein Innenbereich, der nicht für Mahlzeiten eingerichtet ist, und Getränkekauf an der Bar."]},{"heading":"Warum schließen die Türen?","paragraphs":["Seit den 2000er Jahren ist die Zahl der Pubs stark gesunken, weil sich Trinkgewohnheiten, Preise und Supermarkt-Alkohol verändert haben. Besonders ländliche Pubs sind gefährdet.","Das Bild variiert regional und generationell: Viele Pubs hängen heute von Essen und Tourismus ab, einige werden von der Gemeinde betrieben, und die britischen Trinkmuster haben sich seit dem Rauchverbot 2007 stark verändert. Der „Local“ ist ebenso Nostalgie wie Beschreibung."]}],"en":[{"heading":"More than a drink","paragraphs":["The pub, short for public house, is a licensed drinking establishment that took its modern name in late 17th-century England. But it has long been more: a community room for quiz nights, darts and pool teams, wakes, union meetings and football supporters' clubs.","The Campaign for Real Ale defines a pub by four features: open to the public without membership, serves draught beer or cider without requiring food, has an indoor area not laid out for meals, and allows drinks to be bought at the bar."]},{"heading":"Why the doors close","paragraphs":["The number of pubs has fallen sharply since the 2000s as drinking habits, prices and supermarket alcohol changed, with rural pubs especially vulnerable.","The picture varies by region and generation: many pubs now depend on food and tourism, some are run by their communities, and British drinking patterns have changed a lot since the smoking ban of 2007. The 'local' is a nostalgic idea as much as a description."]}]},"context":{"countries":["GB"],"region":"British Isles","continent":"europe","languages":["en"],"period":"contemporary"},"tags":["cities-and-community","British Isles"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pub","de":"Pub","en":"Pub"},"url":"https://en.wikipedia.org/wiki/Pub","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Working men's club","de":"Working men's club","en":"Working men's club"},"url":"https://en.wikipedia.org/wiki/Working_men's_club","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"حانة قرية تستضيف فريق السهام الثلاثاء، والمسابقة الخميس، وتأبيناً السبت، وصاحب الحانة يعرف أي الزبائن يأخذون الحليب.","de":"Ein Dorfpub beherbergt dienstags das Dartteam, donnerstags das Quiz und samstags eine Trauerfeier – und der Wirt weiß, welche Stammgäste Milch nehmen.","en":"A village pub hosts the darts team on Tuesdays, the quiz on Thursdays and a wake on Saturday, and the landlord knows which regulars take milk."},"misunderstanding":{"ar":"يظن البعض أن الحانة مجرد حانة، لكنها مؤسسة اجتماعية أساسية، خاصة في القرى.","de":"Manche halten den Pub für eine reine Kneipe, doch er ist eine soziale Institution, besonders in Dörfern.","en":"Some think a pub is just a bar, but it is a social institution, especially in villages."},"comparison":{"ar":"تشبه الحانة النادي الاجتماعي أو المقهى الشعبي في مجتمعات أخرى، لكنها مرتبطة ارتباطاً وثيقاً بالهوية البريطانية.","de":"Der Pub ähnelt dem Verein oder dem Dorfcafé anderswo, ist aber eng mit britischer Identität verbunden.","en":"The pub resembles a social club or village café elsewhere, but is closely tied to British identity."}},{"id":"eur-016","version":2,"slug":"bonfire-night-fireworks-effigies-and-an-old-plot","contentType":"note","category":"traditions","title":{"ar":"ليلة النار: احتفال بريطاني بالنجاة","de":"Feuernacht: Erinnern und Zusammensein","en":"Bonfire Night: Fire, Effigies and Memory"},"deck":{"ar":"في الخامس من نوفمبر تشتعل النيران في بريطانيا إحياءً لذكرى مؤامرة قديمة، لكنها صارت مناسبة للعائلة والجيران.","de":"Am 5. November brennen in Großbritannien Feuer zum Gedenken an eine alte Verschwörung – heute oft ein Fest für Familie und Nachbarschaft.","en":"On 5 November Britain lights fires to mark an old plot, but for most people the night is now about family and neighbours."},"teaser":{"ar":"من مؤامرة البارود عام 1605 إلى ألعاب نارية في الحدائق الخلفية: كيف تحوّلت ذكرى سياسية قديمة إلى ليلة دافئة يجتمع فيها الجيران.","de":"Von der Pulververschwörung 1605 zu Funken und Suppe im Hinterhof: Wie aus einem politischen Gedenktag ein warmherziger Nachbarschaftsabend wurde.","en":"From the 1605 Gunpowder Plot to sparklers in a back garden: how a political thanksgiving turned into a warm neighbourhood evening."},"readingMinutes":1,"sections":{"ar":[{"heading":"من مؤامرة إلى عادة سنوية","paragraphs":["يحيي البريطانيون في الخامس من نوفمبر ذكرى فشل مؤامرة البارود عام 1605، حين خطط متآمرون كاثوليك لتفجير مبنى البرلمان وقتل الملك جيمس الأول.","وبعد نجاته صدر قانون برلماني عام 1605 جعل التاريخ يوم شكر سنوي، فأُوقدت النيران احتفالاً بسلامة الملك.","ولا تزال النيران تُشعل في هذا التاريخ مع الألعاب النارية، وفي أماكن كثيرة يُحرق دمية تُسمى «غاي»، وقد كان الأطفال يجمعون «بنساً من أجل الغاي»."]},{"heading":"بين اللهو المحلي والذكرى الهادئة","paragraphs":["بعض البلدات تحتفظ بتقاليد أكثر صخباً، مثل نيران لويس بأزيائها وألعابها النارية، أو دحرجة براميل القطران في أوتري سانت ماري.","ومع الوقت خفتت النزعة الطائفية عند معظم المشاركين، وصارت الليلة مناسبة عائلية وجوارية، رغم بقاء توترات في أماكن قليلة.","وتختلف الأجواء من منطقة إلى أخرى ومن جيل إلى جيل، إذ صارت قواعد السلامة تجعل الألعاب النارية الخاصة أقل شيوعاً."]}],"de":[{"heading":"Von der Verschwörung zum Jahresbrauch","paragraphs":["Am 5. November erinnern Britinnen und Briten an das Scheitern der Pulververschwörung von 1605, als katholische Verschwörer das Parlamentsgebäude sprengen und König James I. töten wollten.","Nach seiner Rettung machte ein Parlamentsgesetz von 1605 den Tag zu einem jährlichen Dankfest, und man entzündete Feuer zur Feier des überlebenden Königs.","Noch heute brennen an diesem Datum Feuer mit Feuerwerk, vielerorts wird eine Strohpuppe namens „guy“ verbrannt; Kinder sammelten früher „a penny for the guy“."]},{"heading":"Lokaler Lärm und stille Erinnerung","paragraphs":["Manche Städte pflegen wildere Bräuche, etwa die Feuer von Lewes mit Kostümen und Feuerwerk oder das Teerfassrollen in Ottery St Mary.","Mit der Zeit verblasste für die meisten Beteiligten die konfessionelle Schärfe, und der Abend wurde ein Familien- und Nachbarschaftsfest, auch wenn an wenigen Orten Spannungen fortbestehen.","Je nach Region und Generation unterscheidet sich die Stimmung, denn Sicherheitsregeln machen privates Feuerwerk seltener."]}],"en":[{"heading":"From a Plot to a Yearly Habit","paragraphs":["On 5 November people in Britain mark the failure of the 1605 Gunpowder Plot, when Catholic conspirators planned to blow up the Houses of Parliament and kill King James I.","After his survival, an Act of Parliament in 1605 made the date an annual thanksgiving, and bonfires were lit to celebrate the king's safety.","Bonfires are still lit on 5 November with fireworks and, in many places, an effigy called a 'guy'; children once collected 'a penny for the guy'."]},{"heading":"Local Noise and Quiet Memory","paragraphs":["Some towns keep rowdier local traditions, such as the Lewes bonfires with their costumes and fireworks, or the tar-barrel rolling at Ottery St Mary.","Over time the anti-Catholic edge has faded for most participants, and the night is now a family and neighbourhood event, though sectarian tensions survive in a few places.","The mood shifts by region and generation, and safety rules have made private fireworks less common."]}]},"context":{"countries":["GB"],"region":"British Isles","continent":"europe","languages":["en"],"period":"contemporary"},"tags":["traditions","British Isles"],"sources":[{"organization":"Wikipedia","title":{"ar":"Guy Fawkes Night","de":"Guy Fawkes Night","en":"Guy Fawkes Night"},"url":"https://en.wikipedia.org/wiki/Guy_Fawkes_Night","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Bonfire","de":"Bonfire","en":"Bonfire"},"url":"https://en.wikipedia.org/wiki/Bonfire","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تتجمع أسرة في حديقة خلفية مساء الخامس من نوفمبر حول المشاعل والحساء وعرض ألعاب نارية صغير، بينما يقارن الأطفال دماهم المصنوعة من القش.","de":"In einem Hinterhof versammelt sich am 5. November eine Nachbarschaft zu Wunderkerzen, Suppe und einem kleinen Feuerwerk, während die Kinder ihre Strohpuppen vergleichen.","en":"A suburban street gathers in a back garden on 5 November for sparklers, soup and a small fireworks display while the children compare their guys."},"misunderstanding":{"ar":"يعتقد بعض الزوار أن الليلة موجهة ضد الكاثوليك، لكن معظم المشاركين يرونها مناسبة للجيران والأطفال أكثر من كونها احتجاجاً دينياً.","de":"Manche Besucher halten den Abend für eine katholikenfeindliche Veranstaltung, doch die meisten Beteiligten sehen darin eher ein Fest für Kinder und Nachbarn als einen religiösen Protest.","en":"Some visitors assume the night is aimed at Catholics, but most participants treat it as an evening for children and neighbours rather than a religious protest."},"comparison":{"ar":"تشبه الليلة احتفالات الشتاء الأخرى التي تجمع الجيران حول النار، لكنها تختلف بجذورها السياسية القديمة وارتباطها بتاريخ البرلمان.","de":"Der Abend ähnelt anderen winterlichen Festen, bei denen Nachbarn am Feuer zusammenkommen, unterscheidet sich aber durch seine alte politische Wurzel und den Bezug zur Parlamentsgeschichte.","en":"It resembles other winter gatherings around a fire, yet stands apart through its old political root and its link to parliamentary history."}},{"id":"eur-017","version":2,"slug":"welsh-is-back-in-the-classroom-on-the-signs-and-in-the-census","contentType":"note","category":"languages","title":{"ar":"الويلزية تعود إلى الفصول واللافتات","de":"Walisisch kehrt in Klassenzimmer und Schilder zurück","en":"Welsh returns to classrooms, signs and census"},"deck":{"ar":"لغة سلتيكية يتحدثها أكثر من نصف مليون شخص، وتستمدّ قوّتها من المدارس واللافتات والبثّ، لا من الذكريات وحدها.","de":"Eine keltische Sprache mit über einer halben Million Sprecherinnen und Sprechern, die ihre Kraft aus Schulen, Schildern und Sendungen zieht.","en":"A Celtic language spoken by more than half a million people, drawing its strength from schools, road signs and broadcasting rather than memory alone."},"teaser":{"ar":"من ردّ التحية في الصف إلى لافتة الطريق، تعود الويلزية إلى الحياة اليومية عبر التعليم والخدمات العامة.","de":"Vom Register im Klassenzimmer bis zum Straßenschild: Walisisch kehrt durch Bildung und öffentliche Dienste in den Alltag zurück.","en":"From answering the register to reading a road sign, Welsh is returning to everyday life through education and public services."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة تُسمَع في الشارع","paragraphs":["الويلزية لغة سلتيكية، وقد أظهر تعداد عام 2021 أن 538,300 شخص في ويلز من سنّ الثالث فأكثر، أي 17.8 في المئة، يستطيعون التحدث بها.","منح قانون اللغة الويلزية لعام 2011 اللغة وضعًا رسميًا في ويلز، والويلزية والإنجليزية لغتان رسميتان في البرلمان الويلزي.","اللافتات الطرقية الثنائية والوثائق وقناة S4C تجعل اللغة مرئية ومسموعة في الحياة اليومية، لا في الصفوف فقط."]},{"heading":"المدارس تصنع المتحدثين","paragraphs":["التعليم بالويلزية هو المحرّك الأساسي للنهضة: كثير من الأطفال من أسر تتحدث الإنجليزية يلتحقون بمدارس ويلزية ويصبحون طلقاء فيها.","تستهدف الحكومة الويلزية الوصول إلى مليون متحدث بحلول عام 2050، ويشمل التخطيط اللغوي أماكن العمل والخدمات الصحية والقادمين الجدد.","يختلف الوضع كثيرًا بين المقاطعات والأجيال، فبعض المناطق القلبية أكثر تماسكًا لغويًا من غيرها."]}],"de":[{"heading":"Eine Sprache, die man auf der Straße hört","paragraphs":["Walisisch ist eine keltische Sprache; laut Volkszählung von 2021 konnten 538.300 Menschen in Wales ab drei Jahren (17,8 Prozent) Walisisch sprechen.","Der Welsh Language (Wales) Measure 2011 verlieh dem Walisischen offiziellen Status, und im Senedd sind Walisisch und Englisch beide Amtssprachen.","Zweisprachige Straßenschilder, Dokumente und der Sender S4C machen die Sprache im Alltag sichtbar und hörbar, nicht nur im Unterricht."]},{"heading":"Schulen schaffen Sprecher","paragraphs":["Walisischsprachige Bildung ist der Hauptmotor der Wiederbelebung: Viele Kinder aus englischsprachigen Haushalten besuchen walisischsprachige Schulen und werden dort fließend.","Die walisische Regierung will bis 2050 eine Million Sprecherinnen und Sprecher erreichen; Sprachplanung umfasst Arbeitsplätze, Gesundheitsdienste und Neuankömmlinge.","Die Lage unterscheidet sich stark nach Region und Generation, denn manche Kerngebiete sind sprachlich gefestigter als andere."]}],"en":[{"heading":"A language heard on the street","paragraphs":["Welsh is a Celtic language, and according to the 2021 census, 538,300 people in Wales aged three and over, or 17.8 per cent, could speak it.","The Welsh Language (Wales) Measure 2011 gave Welsh official status in Wales, and Welsh and English are both official languages of the Senedd.","Bilingual road signs, documents and the broadcaster S4C make the language visible and audible in daily life, not only in classrooms."]},{"heading":"Schools create the speakers","paragraphs":["Welsh-medium education is the main engine of revival: many children from English-speaking homes now attend Welsh-medium schools and become fluent there.","The Welsh Government has a target of one million Welsh speakers by 2050, and language planning now covers workplaces, health services and newcomers.","The picture varies enormously by county and generation, since some heartland areas are linguistically stronger than others."]}]},"context":{"countries":["GB"],"region":"Wales","continent":"europe","languages":["cy","en"],"period":"contemporary"},"tags":["languages","Wales"],"sources":[{"organization":"Wikipedia","title":{"ar":"Welsh language","de":"Welsh language","en":"Welsh language"},"url":"https://en.wikipedia.org/wiki/Welsh_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Welsh-medium education","de":"Welsh-medium education","en":"Welsh-medium education"},"url":"https://en.wikipedia.org/wiki/Welsh-medium_education","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طفل في كارديف يجيب على النداء بالويلزية في الصف، ويشاهد رسوم S4C في البيت، ويرى كلمة «Araf» مرسومة على الطريق أمام المدرسة.","de":"Ein Kind in Cardiff antwortet im Unterricht auf Walisisch, sieht zu Hause S4C-Zeichentrickfilme und liest „Araf“ auf der Straße vor der Schule.","en":"A child in Cardiff answers the register in Welsh, watches S4C cartoons at home and sees 'Araf' painted on the road outside school."},"misunderstanding":{"ar":"يُظنّ أحيانًا أن كثرة المدارس الويلزية تعني تلقائيًا بالغين واثقين باللغة، لكن التوسّع في التعليم لم يُنتج دائمًا هذه الثقة.","de":"Manchmal wird angenommen, viele walisischsprachige Schulen brächten automatisch selbstsichere Erwachsene hervor, doch die Ausweitung des Unterrichts hat diese Sicherheit nicht immer erzeugt.","en":"It is sometimes assumed that many Welsh-medium schools automatically produce confident adult speakers, but growth in Welsh-medium education has not always produced that confidence."},"comparison":{"ar":"الويلزية ليست لغة محفوظة في المتاحف، بل لغة تُستخدم في الصفوف واللافتات والبثّ، ومع ذلك تبقى أقلية في بعض مناطق قلبها التقليدي.","de":"Walisisch ist keine im Museum verwahrte Sprache, sondern wird in Schulen, auf Schildern und im Rundfunk genutzt, bleibt aber in Teilen seines Kerngebiets eine Minderheitensprache.","en":"Welsh is not a language kept in museums but one used in classrooms, on signs and in broadcasting, yet it remains a minority language in parts of its own heartland."},"expression":{"original":"Bore da","language":"Cymraeg","gloss":{"ar":"صباح الخير","de":"Guten Morgen","en":"Good morning"},"usage":{"ar":"تحية صباحية شائعة في المدارس والمكاتب والمحلات.","de":"Geläufiger Morgengruß in Schulen, Büros und Geschäften.","en":"A common morning greeting in schools, offices and shops."},"transliteration":"bore da"}},{"id":"eur-018","version":2,"slug":"the-twelfth-parades-bonfires-and-memory-in-northern-ireland","contentType":"note","category":"traditions","title":{"ar":"الثاني عشر: مسيرات ونيران وذاكرة","de":"Der Zwölfte: Paraden, Feuer und Gedächtnis","en":"The Twelfth: parades, bonfires and memory"},"deck":{"ar":"في الثاني عشر من تموز/يوليو تمتلئ شوارع أيرلندا الشمالية بالرايات والفرق الموسيقية، في يوم يحمل معنى مختلفًا لكل من يعيشه.","de":"Am 12. Juli füllen Fahnen und Musikkapellen die Straßen Nordirlands – ein Tag, der für alle, die ihn erleben, etwas anderes bedeutet.","en":"On 12 July, flags and marching bands fill Northern Irish streets for a day that means something different to everyone who lives it."},"teaser":{"ar":"احتفال بروتستانتي بمعركة وقعت قبل ثلاثة قرون، تتجاور فيه الأعلام والنيران والمسيرات مع جدل لا يهدأ حول الطرق التي تمر بها.","de":"Ein protestantisches Gedenken an eine Schlacht vor drei Jahrhunderten, bei dem Fahnen, Feuer und Umzüge neben einer nie ganz verstummenden Debatte über die Routen stehen.","en":"A Protestant commemoration of a battle three centuries old, where flags, bonfires and parades sit beside a debate over routes that never quite fades."},"readingMinutes":1,"sections":{"ar":[{"heading":"مسيرات ونيران في ليلة سابقة","paragraphs":["في الثاني عشر من تموز/يوليو تحيي أوساط بروتستانتية في أيرلندا الشمالية ذكرى معركة البويْن عام 1690، حين انتصر وليام الثالث ملك أورانج على الملك الكاثوليكي جيمس الثاني. وتنظّم جماعة الأورانج، التي تأسست عام 1795، مسيرات للجماعات التابعة لها يصاحبها عدد من الفرق الموسيقية، وتزيّن الشوارع بأعلام الاتحاد وأشرطة الزينة.","في ليلة الحادي عشر تُشعل نيران كبيرة في أحياء الاتحاديين، بعضها يبلغ ارتفاعه عدة طوابق، فيجتمع الناس حولها. ويُعدّ اليوم عطلة رسمية في أيرلندا الشمالية وتعبيرًا بارزًا عن الهوية الاتحادية. وتختلف مظاهر الاحتفال بين المدن والبلدات، كما تتباين بين الأجيال في طريقة إحيائها للذكرى."]},{"heading":"الطريق نفسه موضع خلاف","paragraphs":["تمرّ مسيرات كثيرة عبر أحياء كاثوليكية أو قريبة منها، وقد ظلت موضع نزاع طويل. وتنظّم لجنة المسيرات هذه الفعاليات، غير أن الخلاف حول المسارات قد يهيمن على السياسة المحلية لأشهر.","يحمل اليوم معاني متباعدة: كثير من البروتستانت يرونه تراثًا وتقليدًا عائليًا لا موقفًا طائفيًا، بينما يعيشه كثير من الكاثوليك كتهديد، ولا يصفه بدقة إلا من يدرك المعنيين معًا."]}],"de":[{"heading":"Umzüge und Feuer in der Nacht davor","paragraphs":["Am 12. Juli begehen protestantische Kreise in Nordirland das Gedenken an die Schlacht am Boyne 1690, als Wilhelm von Oranien den katholischen Jakob II. besiegte. Der Oranierorden, 1795 gegründet, organisiert Umzüge seiner Logen mit Begleitkapellen, und die Straßen werden mit Unionsflaggen und Girlanden geschmückt.","In der Nacht zum Zwölften werden in loyalistischen Vierteln große Feuer entzündet, manche mehrere Stockwerke hoch, und die Menschen versammeln sich darum. Der Tag ist in Nordirland gesetzlicher Feiertag und ein wichtiger Ausdruck unionistischer Identität. Je nach Stadt und Landgemeinde sieht das Gedenken anders aus, und auch zwischen den Generationen unterscheidet sich die Art, es zu begehen."]},{"heading":"Die Route selbst ist der Streitpunkt","paragraphs":["Viele Umzüge führen durch oder nahe an katholischen Vierteln und waren lange umstritten. Die Parades Commission regelt die Veranstaltungen, doch Streit über Routen kann die lokale Politik monatelang bestimmen.","Der Tag trägt weit auseinanderliegende Bedeutungen: Viele Protestanten sehen ihn als Erbe und Familientradition, nicht als konfessionelle Aussage, während viele Katholiken ihn als Einschüchterung erleben – wer ihn genau beschreiben will, muss beides zugleich aushalten."]}],"en":[{"heading":"Marches and fires the night before","paragraphs":["On 12 July, Ulster Protestants mark the Battle of the Boyne in 1690, when William of Orange defeated the Catholic James II. The Orange Order, founded in 1795, organises parades of lodges with accompanying marching bands, and streets are decorated with Union flags and bunting.","On the Eleventh Night, large bonfires are lit in loyalist areas, some several storeys high, and people gather around them. The day is a public holiday in Northern Ireland and a major expression of unionist identity. Celebrations vary between cities and small towns, and generations differ in how they keep the date."]},{"heading":"The route itself is the argument","paragraphs":["Many parade routes pass through or near Catholic neighbourhoods and have long been contested. The Parades Commission regulates the events, yet disputes over routes can dominate local politics for months.","The day carries far-apart meanings: many Protestants see it as heritage and family tradition rather than a sectarian statement, while many Catholics experience it as intimidation, and describing it accurately means holding both."]}]},"context":{"countries":["GB"],"region":"Northern Ireland","continent":"europe","languages":["en"],"period":"contemporary"},"tags":["traditions","Northern Ireland"],"sources":[{"organization":"Wikipedia","title":{"ar":"The Twelfth","de":"The Twelfth","en":"The Twelfth"},"url":"https://en.wikipedia.org/wiki/The_Twelfth","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Orange Order","de":"Orange Order","en":"Orange Order"},"url":"https://en.wikipedia.org/wiki/Orange_Order","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تتدرب فرقة من بلدة صغيرة أشهرًا، ثم تسير في الثاني عشر خلف لافتة جماعة، ويصطف المتفرجون على طول الشارع الرئيسي.","de":"Eine Kapelle aus einer Kleinstadt übt monatelang, marschiert am Zwölften hinter dem Banner einer Loge, und Zuschauer säumen die Hauptstraße.","en":"A band from a small town practises for months, then marches on the Twelfth behind a lodge banner while spectators line the main street."},"misunderstanding":{"ar":"من السهل اختزاله في استعراض سياسي واحد، لكنه في الواقع مناسبة عائلية واجتماعية بقدر ما هي رمزية.","de":"Leicht wird er auf eine einzige politische Demonstration verkürzt, doch er ist ebenso ein familiares und gemeinschaftliches Ereignis.","en":"It is easily reduced to a single political display, but it is just as much a family and community occasion."},"comparison":{"ar":"يشبه في بعض وجوهه احتفالات محلية بأعياد وطنية في أوروبا، حيث تختلط الذاكرة الجماعية بالاحتفال الشعبي.","de":"In manchen Zügen ähnelt er lokalen Feiern nationaler Gedenktage in Europa, wo kollektive Erinnerung und Volksfest ineinander übergehen.","en":"In some ways it resembles local observances of national days across Europe, where collective memory and public festivity blend."}},{"id":"eur-019","version":2,"slug":"craic-is-not-an-old-irish-word-and-that-is-the-point","contentType":"language","category":"communication","title":{"ar":"كلمة craic ليست إرثاً غالياً قديماً","de":"„Craic“ ist kein alter irischer Begriff","en":"'Craic' is not an old Irish word"},"deck":{"ar":"كيف صار مصطلح حديث على ألسنة الأيرلنديين رمزاً لهويتهم الاجتماعية، وكيف يتغيّر استخدامه بين الأجيال والمناطق.","de":"Wie ein modernes Lehnwort zum Sinnbild irischer Geselligkeit wurde und warum sein Gebrauch je nach Region und Generation variiert.","en":"How a mid-century borrowing became a byword for Irish sociability, and why its use shifts across regions and generations."},"teaser":{"ar":"كلمة شائعة في الحانات الأيرلندية تبدو قديمة جداً، لكنها في الحقيقة حديثة العهد، وقصتها تكشف الكثير عن الحياة الاجتماعية.","de":"Ein Wort aus irischen Pubs klingt uralt, ist aber jung – und erzählt viel darüber, wie Menschen dort Gespräch und Gesellschaft schätzen.","en":"A word heard in every Irish pub sounds ancient, but it is surprisingly modern, and its story says a lot about how people value company."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما تعنيه الكلمة فعلاً","paragraphs":["تشير كلمة craic في أيرلندا إلى الأخبار والقيل والقال والمرح والترفيه والمحادثة الممتعة. والسؤال «What's the craic?» يعني «كيف حالك؟» أو «ما الجديد؟»، وعبارة «the craic was ninety» تعني أن الأمسية كانت ممتازة.","لكن الكلمة ليست إرثاً غالياً قديماً، بل اقترضتها الأيرلندية من كلمة crack الاسكتلندية والإنجليزية في منتصف القرن العشرين، ثم عادت التهجئة الأيرلندية إلى الإنجليزية."]},{"heading":"مثالية اجتماعية وتنوّع محلي","paragraphs":["تعكس الكلمة مثالاً اجتماعياً تُقدَّم فيه المحادثة والفكاهة والرفقة على التخطيط والإنفاق. وفي التسعينيات صارت شعاراً تسويقياً للحانات والسياحة، وعبارة «ceol agus craic» أي الموسيقى والمرح عبارة قياسية في الحانات.","يختلف الاستخدام بين المناطق والأجيال: فالشباب في المدن يستخدمونها أحياناً على سبيل الدعابة، بينما تبقى في القرى جزءاً من الحديث اليومي."]}],"de":[{"heading":"Was das Wort wirklich bedeutet","paragraphs":["„Craic“ bedeutet in Irland Neuigkeiten, Klatsch, Spaß, Unterhaltung und anregende Gespräche. „What's the craic?“ heißt „Wie geht's?“ oder „Was gibt's Neues?“, und „the craic was ninety“ meint, der Abend war hervorragend.","Doch das Wort ist kein altes gälisches Erbe: Das schottische und englische „crack“ wurde Mitte des 20. Jahrhunderts ins Irische entlehnt, die irische Schreibweise danach ins Englische zurück."]},{"heading":"Ein soziales Ideal im Wandel","paragraphs":["Das Wort verweist auf ein Ideal, in dem Gespräch, Humor und Gesellschaft mehr zählen als Planung und Ausgaben. In den 1990er-Jahren wurde es zum Werbeslogan für Pubs und Tourismus, und „ceol agus craic“ (Musik und Spaß) ist eine feste Pub-Wendung.","Der Gebrauch unterscheidet sich regional und zwischen Generationen: Jüngere in Städten sagen es oft ironisch, in Dörfern bleibt es Teil des Alltagsgesprächs."]}],"en":[{"heading":"What the word actually means","paragraphs":["In Ireland, 'craic' means news, gossip, fun, entertainment and enjoyable conversation. 'What's the craic?' means 'How are you?' or 'What's happening?', and 'the craic was ninety' means the evening was excellent.","But the word is not an ancient Gaelic inheritance: the Scots and English 'crack' was borrowed into Irish in the mid-20th century, and the Irish spelling was then reborrowed into English."]},{"heading":"A social ideal, unevenly shared","paragraphs":["It suggests a social ideal in which conversation, humour and company matter more than planning or spending. In the 1990s it became a marketing slogan for Irish pubs and tourism, and 'ceol agus craic' (music and fun) is a standard pub phrase.","Usage varies by region and generation: younger city dwellers sometimes say it playfully, while in rural areas it stays part of everyday talk."]}]},"context":{"countries":["IE"],"region":"Ireland","continent":"europe","languages":["en","ga"],"period":"contemporary"},"tags":["communication","Ireland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Craic","de":"Craic","en":"Craic"},"url":"https://en.wikipedia.org/wiki/Craic","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Ireland","de":"Culture of Ireland","en":"Culture of Ireland"},"url":"https://en.wikipedia.org/wiki/Culture_of_Ireland","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يدخل زائر حانة ويسأل «What's the craic?»، فيأتيه جواب يمتد عشر دقائق عن حفل زفاف ابن عم بدل كلمة «بخير» البسيطة.","de":"Ein Gast betritt einen Pub und fragt „What's the craic?“, worauf er zehn Minuten über die Hochzeit eines Cousins hört statt eines knappen „gut“.","en":"A visitor asks 'What's the craic?' on entering a pub, and the answer is a ten-minute account of a cousin's wedding rather than a simple 'fine'."},"misunderstanding":{"ar":"يظن كثيرون أن الكلمة إرث غالٍ أصيل، لكن تهجئتها الأيرلندية حديثة، وقد لا يستخدمها متحدثو الأيرلندية بالضرورة.","de":"Viele halten das Wort für altes gälisches Erbe, doch die irische Schreibweise ist modern, und Irischsprecher verwenden es nicht zwangsläufig.","en":"Many assume the word is ancient Gaelic, but the Irish spelling is modern; Irish speakers do not necessarily use it, and its uniqueness is partly a marketing construction."},"comparison":{"ar":"في ألمانيا يُسأل عن الحال بجملة قصيرة متوقعة، أما هنا فيُفتح السؤال باباً لحكاية كاملة.","de":"In Deutschland erwartet man auf die Frage nach dem Befinden eine kurze Antwort, hier öffnet sie die Tür zu einer ganzen Geschichte.","en":"In Germany the question about how you are invites a short answer; here it opens the door to a whole story."},"expression":{"original":"craic","language":"Béarla (Irish English)","gloss":{"ar":"مرح وأخبار ومحادثة ممتعة","de":"Spaß, Neuigkeiten und gute Gespräche","en":"fun, news and good conversation"},"usage":{"ar":"تُستخدم للسؤال عن الحال أو لوصف أمسية ممتعة","de":"dient als Grußformel oder als Lob für einen gelungenen Abend","en":"used to greet someone or to praise a great evening"},"transliteration":"craic"}},{"id":"eur-020","version":2,"slug":"the-irish-session-tunes-in-the-corner-no-stage","contentType":"scene","category":"music-and-dance","title":{"ar":"الجلسة الإيرلندية: ألحان في الزاوية","de":"Die irische Session: Melodien in der Ecke","en":"The Irish session: tunes in the corner"},"deck":{"ar":"موسيقيون يجتمعون في ركن حانة دون مسرح، يتبادلون الألحان ويواصلون العزف حين يعرفون اللحن.","de":"Musiker treffen sich in einer Pub-Ecke ohne Bühne, wechseln Tunes und spielen mit, sobald sie die Melodie kennen.","en":"Musicians gather in a pub corner without a stage, swapping tunes and joining in whenever they know the melody."},"teaser":{"ar":"في حانة غرب كلير يجلس ستة عازفين حول طاولة، يبدأ عازف الكمان ريلاً فيلتحق به الآخرون دون عدّ.","de":"An einem Dienstagabend sitzen sechs Musiker um einen Tisch in einem Pub in West Clare; ein Geiger beginnt eine Reel, die anderen fallen ohne Zählen ein.","en":"On a Tuesday night six musicians sit around a table in a West Clare pub; a fiddler starts a reel and the others join at the second phrase."},"readingMinutes":1,"sections":{"ar":[{"heading":"ركن الحانة بدل المسرح","paragraphs":["الجلسة لقاء غير رسمي لعازفي الموسيقى الإيرلندية التقليدية، يُقام عادة في ركن حانة لا على مسرح. الذخيرة الأساسية ألحان رقص: ريلز وجيغز وهورنبايبز وبولكاس، تُعزف في مجموعات بلا ترتيب ثابت.","الآلات المعتادة الكمان والفلوت وصفارة القصدير وأنابيب الأليان والأكورديون والكونسيرتينا والبانجو والبدران؛ ينضم العازف حين يعرف اللحن.","للجلسة آداب: يبدأ أحدهم المجموعة ويتبعه الآخرون، والموافقة غالباً إيماءة هادئة لا تصفيق. أسّست كومهالتاس كيولتوري إيرين عام 1951 صفوفاً ومسابقات فليده تشيول تغذّي هذا التقليد."]},{"heading":"تعلّم واختلاف بين الأجيال","paragraphs":["تتفاوت الجلسات بين ليالٍ سياحية وأخرى للعازفين الجدّيين، والجلسة «الأصيلة» بناء إحيائي جزئي؛ كثير من الشبان يتعلمون من التسجيلات ومن كبار العازفين معاً.","يختلف الإيقاع والحضور أيضاً بين المدن والأرياف وبين جيل وآخر، فبعض الجلسات هادئة وبعضها صاخب."]}],"de":[{"heading":"Die Pub-Ecke statt der Bühne","paragraphs":["Eine Session ist ein informelles Treffen von Musikerinnen und Musikern der irischen Tradition, meist in einer Pub-Ecke statt auf einer Bühne. Das Kernrepertoire sind Tanzmelodien – Reels, Jigs, Hornpipes und Polkas –, gespielt in Sets ohne feste Anordnung.","Typische Instrumente sind Fiddle, Flöte, Tin Whistle, Uilleann Pipes, Akkordeon, Concertina, Banjo und Bodhrán; man steigt ein, wenn man den Tune kennt.","Es gibt Etikette: Eine Person beginnt ein Set, andere folgen, und Zustimmung ist oft ein stilles Nicken statt Applaus. Comhaltas Ceoltóirí Éireann, 1951 gegründet, organisiert Kurse und die Fleadh-Cheoil-Wettbewerbe, die diese Tradition speisen."]},{"heading":"Lernen und Unterschiede zwischen Generationen","paragraphs":["Sessions reichen von touristenfreundlichen Pub-Abenden bis zu ernsten Runden nur für Spieler; die „authentische“ Session ist teils eine Wiederbelebungskonstruktion, und viele junge Musiker lernen sowohl von Aufnahmen als auch von Älteren.","Auch zwischen Stadt und Land sowie zwischen Generationen unterscheiden sich Tempo und Stimmung – manche Runden sind ruhig, andere laut."]}],"en":[{"heading":"The pub corner instead of a stage","paragraphs":["A session is an informal gathering of musicians playing Irish traditional music, usually in a pub corner rather than on a stage. The core repertoire is dance tunes – reels, jigs, hornpipes and polkas – played in sets of several tunes without a fixed arrangement.","Typical instruments are fiddle, flute, tin whistle, uilleann pipes, accordion, concertina, banjo and bodhrán; players join in when they know the tune.","Sessions have etiquette: a player starts a set, others follow, and approval is often a quiet nod rather than applause. Comhaltas Ceoltóirí Éireann, founded in 1951, runs classes and the Fleadh Cheoil competitions that feed the tradition."]},{"heading":"Learning and differences across generations","paragraphs":["Sessions range from tourist-friendly pub nights to serious players-only gatherings, and the 'authentic' session is partly a revival construction; many young musicians learn from recordings as well as from older players.","Pace and mood also vary between town and countryside and from one generation to the next, so some gatherings are quiet and others loud."]}]},"context":{"countries":["IE"],"region":"Ireland","continent":"europe","languages":["ga","en"],"period":"contemporary"},"tags":["music-and-dance","Ireland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Irish traditional music","de":"Irish traditional music","en":"Irish traditional music"},"url":"https://en.wikipedia.org/wiki/Irish_traditional_music","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Irish pub","de":"Irish pub","en":"Irish pub"},"url":"https://en.wikipedia.org/wiki/Irish_pub","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في ليلة ثلاثاء يجلس ستة موسيقيين حول طاولة في حانة بغرب كلير؛ يبدأ عازف كمان ريلاً فيلتحق الآخرون بالعبارة الثانية دون أن يعدّ أحد.","de":"An einem Dienstagabend sitzen sechs Musiker um einen Tisch in einem Pub in West Clare; ein Geiger beginnt eine Reel, und die anderen fallen beim zweiten Satz ein, ohne dass jemand zählt.","en":"On a Tuesday night six musicians sit around a table in a West Clare pub; a fiddler starts a reel and the others join at the second phrase without anyone counting in."},"misunderstanding":{"ar":"يظن بعض الزوار أن الجلسة عرض مسرحي يُصفَّق عليه، لكنها لقاء مشترك حيث يُنظر إلى الموافقة بإيماءة لا بتصفيق.","de":"Manche Besucher halten die Session für eine Aufführung mit Applaus, doch sie ist ein gemeinsames Treffen, bei dem Zustimmung eher ein Nicken ist.","en":"Some visitors expect a staged performance with applause, but a session is a shared gathering where approval is more likely a nod than clapping."},"comparison":{"ar":"تشبه الجلسة جلسات الطرب الجماعي في ثقافات أخرى، لكنها تعتمد على حفظ الألحان والانضمام التلقائي بدل قائمة برنامج.","de":"Ähnlich wie gemeinsames Musizieren in anderen Kulturen, beruht die Session doch auf auswendig gelernten Melodien und spontanem Einsteigen statt auf einem Programm.","en":"Like communal playing in other cultures, the session relies on memorised tunes and spontaneous joining rather than a printed programme."}},{"id":"eur-021","version":2,"slug":"the-gaeltacht-paying-people-to-keep-irish-alive","contentType":"note","category":"languages","title":{"ar":"الغايلتاخت: أجر مقابل إبقاء الأيرلندية حيّة","de":"Gaeltacht: Geld dafür, dass Irisch weiterlebt","en":"The Gaeltacht: paying people to keep Irish alive"},"deck":{"ar":"مناطق تعترف فيها الدولة بالأيرلندية لغةً أساسية في البيوت، لكن الأعداد تتقلّص والوظائف قليلة.","de":"In einigen Distrikten ist Irisch noch die Sprache zu Hause, doch junge Familien finden kaum Arbeit oder Wohnung.","en":"In some districts Irish is still the language of the kitchen table, but young families find little work and fewer homes."},"teaser":{"ar":"في بعض مناطق الغايلتاخت لا يزال الأيرلندي لغة البيت، لكنّ العائلات الشابة تواجه نقص العمل والسكن.","de":"Die Gaeltacht ist kein einheitlicher Ort: Manche Dörfer sprechen täglich Irisch, andere sind längst englischsprachig.","en":"The Gaeltacht is not one place: some villages speak daily Irish, others are effectively English-speaking, and the boundary is administrative."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة البيت لا لغة المدرسة","paragraphs":["الغايلتاخت هي مجموعة المناطق التي تعترف فيها الحكومة الأيرلندية بالأيرلندية لغةً أساسية في البيوت، وحُدِّدت رسمياً أول مرة في عشرينيات القرن الماضي. والأيرلندية هي اللغة الرسمية الأولى في البلاد، ويستطيع نحو 1.9 مليون شخص التحدّث بها، لكنّ أقلية صغيرة فقط تستخدمها يومياً خارج المدرسة.","أظهرت دراسة عام 2015 أنّ الأيرلندية تُتحدَّث يومياً بنسبة الثلثين على الأقل من السكان في عدد قليل من مناطق الغايلتاخت فقط، وأنّها تتراجع في كثير منها. ويختلف الوضع من منطقة إلى أخرى، كما تختلف عادات الأجيال الشابة عن عادات الأكبر سناً داخل المنطقة نفسها."]},{"heading":"دعم الدولة وضيق سوق العمل","paragraphs":["تدعم السياسة الرسمية الغايلتاخت بالمنح والمدارس الأيرلندية وهيئة أوداراس نا غايلتاختا وإذاعة مخصّصة، لكنّ الوظائف والسكن يظلّان شحيحين.","في الصيف تستقبل كليات الغايلتاخت آلاف المراهقين للإقامة مع أسر ناطقة بالأيرلندية، وهي تجربة تكوينية لكثير من البالغين الأيرلنديين."]}],"de":[{"heading":"Sprache des Hauses, nicht der Schule","paragraphs":["Die Gaeltacht umfasst jene Distrikte, in denen die irische Regierung Irisch als vorherrschende Haussprache anerkennt; offiziell definiert wurden sie erstmals in den 1920er-Jahren. Irisch ist die erste Amtssprache Irlands, rund 1,9 Millionen Menschen können es sprechen, doch nur eine kleine Minderheit nutzt es täglich außerhalb der Schule.","Eine Studie von 2015 ergab, dass in nur wenigen Gaeltacht-Distrikten mindestens zwei Drittel der Bevölkerung täglich Irisch sprechen, und in vielen geht die Sprache zurück. Das Bild unterscheidet sich regional, und jüngere Bewohner nutzen die Sprache oft anders als ältere im selben Ort."]},{"heading":"Staatliche Förderung, knapper Arbeitsmarkt","paragraphs":["Der Staat stützt die Gaeltacht mit Zuschüssen, irischsprachigen Schulen, Údarás na Gaeltachta und einem eigenen Radiosender, doch Jobs und Wohnraum bleiben knapp.","Im Sommer bringen Gaeltacht-Sprachcolleges Tausende Teenager bei irischsprachigen Familien unter – für viele Erwachsene in Irland eine prägende Erfahrung."]}],"en":[{"heading":"The language of home, not school","paragraphs":["The Gaeltacht is the set of districts where the Irish government recognises Irish as the predominant home language, first officially defined in the 1920s. Irish is Ireland's first official language, and about 1.9 million people can speak it, but only a small minority use it daily outside school.","A 2015 study found that Irish was spoken daily by at least two-thirds of the population in only a small number of Gaeltacht districts, and the language is declining in many of them. The picture varies region to region, and younger residents often use Irish differently from their grandparents in the same village."]},{"heading":"State support, scarce jobs","paragraphs":["State policy supports the Gaeltacht through grants, Irish-language schools, Údarás na Gaeltachta and a dedicated radio station, but jobs and housing remain scarce.","Every summer, Gaeltacht colleges bring thousands of teenagers to live with Irish-speaking families, a formative experience for many Irish adults."]}]},"context":{"countries":["IE"],"region":"Ireland","continent":"europe","languages":["ga","en"],"period":"contemporary"},"tags":["languages","Ireland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Irish language","de":"Irish language","en":"Irish language"},"url":"https://en.wikipedia.org/wiki/Irish_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Gaeltacht","de":"Gaeltacht","en":"Gaeltacht"},"url":"https://en.wikipedia.org/wiki/Gaeltacht","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يمضي مراهق من دبلن ثلاثة أسابيع في إقامة عائلية بمنطقة كونيمارا، ويُطلب منه التحدّث بالأيرلندية فقط على الفطور، فيعود إلى بيته ببضع كلمات جديدة ولكنة مختلفة.","de":"Ein Teenager aus Dublin verbringt drei Wochen bei einer Gastfamilie in Connemara, soll beim Frühstück nur Irisch sprechen und kommt mit ein paar Brocken und einem neuen Akzent nach Hause.","en":"A Dublin teenager spends three weeks in a Connemara homestay, is asked to speak only Irish at breakfast, and comes home with a cúpla focal and a new accent."},"misunderstanding":{"ar":"يُظنّ أنّ الغايلتاخت مكان واحد وتجربة واحدة، لكنّ بعض المناطق ما زالت قوية بالأيرلندية اليومية بينما صارت مناطق أخرى ناطقة بالإنجليزية فعلياً.","de":"Viele halten die Gaeltacht für einen einzigen Ort mit einer einzigen Erfahrung, doch einige Distrikte haben starkes tägliches Irisch, andere sind faktisch englischsprachig.","en":"People assume the Gaeltacht is one place and one experience, yet some districts have strong daily Irish while others are effectively English-speaking."},"comparison":{"ar":"يشبه الأمر أحياناً برامج الانغماس اللغوي في مناطق أخرى بأوروبا، لكنّ الفارق أنّ الدعم هنا مرتبط بحدود إدارية لا بجغرافيا اللغة وحدها.","de":"Ähnlich wie Sprachbad-Programme anderswo in Europa, nur dass hier Förderung an Verwaltungsgrenzen gebunden ist und nicht allein an die Sprachgeografie.","en":"It resembles language-immersion schemes elsewhere in Europe, except that support here follows administrative boundaries as much as the geography of speech."},"expression":{"original":"Conas atá tú?","language":"Gaeilge","gloss":{"ar":"كيف حالك؟","de":"Wie geht es dir?","en":"How are you?"},"usage":{"ar":"تحية يومية شائعة عند اللقاء، وتُستعمل في المدارس والكليات الصيفية وفي المحادثات العائلية.","de":"Geläufige Alltagsbegrüßung, oft in Schulen, Sommercolleges und in der Familie verwendet.","en":"A common everyday greeting, used in schools, summer colleges and family conversation."},"transliteration":"Conas atá tú?"}},{"id":"eur-022","version":2,"slug":"the-gaa-parish-teams-amateur-rules-and-a-national-code","contentType":"note","category":"games-and-leisure","title":{"ar":"الرابطة الغيلية: فرق الرعية والهواة","de":"Die GAA: Pfarreiteams und Amateurregeln","en":"The GAA: parish teams, amateur rules"},"deck":{"ar":"في أيرلندا، يلعب الرياضيون من أجل قريتهم لا من أجل عقد، وتُبنى الهوية المحلية في قلب المنافسة.","de":"In Irland spielen Sportler für ihr Dorf, nicht für einen Vertrag, und die lokale Identität steckt mitten im Wettbewerb.","en":"In Ireland, athletes play for where they come from, not for a contract, and local identity sits at the heart of the competition."},"teaser":{"ar":"تأسست الرابطة الغيلية عام 1884 لتعزيز الرياضات الأيرلندية، وأبرزها الهيرلينغ وكرة القدم الغيلية، وتضم اليوم أكثر من 500 ألف عضو.","de":"Die Gaelic Athletic Association wurde 1884 gegründet, um irische Sportarten zu fördern, vor allem Hurling und Gaelic Football, und hat heute über 500.000 Mitglieder.","en":"The Gaelic Athletic Association was founded in 1884 to promote Irish sports, above all hurling and Gaelic football, and now has over 500,000 members."},"readingMinutes":1,"sections":{"ar":[{"heading":"الفريق يمثل المكان الذي يأتي منه","paragraphs":["تُنظَّم الأندية حسب الرعية والمقاطعة، فيمثل اللاعبون المكان الذي أتوا منه لا سوقًا تجاريًا.","في قرية من 500 نسمة يشارك فريق هيرلينغ كامل، وتخرج الرعية كلها إلى نهائي المقاطعة؛ يتدرب اللاعبون بعد العمل ويعودون إلى العمل يوم الاثنين.","تختلف حدة هذا الانتماء بين الأجيال والمناطق، ففي دبلن والمناطق الحضرية الجديدة يكون الحضور أخف مما هو عليه في الريف."]},{"heading":"لعبة هواة وقواعد مثيرة للجدل","paragraphs":["اللعبة هواة: لا يتقاضى اللاعبون أجرًا، وقد أثارت قواعد المدفوعات والانتقالات نزاعات متكررة.","يُلعب الهيرلينغ بعصا من خشب الرماد وكرة صغيرة، بنقطة فوق العارضة وثلاث نقاط للهدف، ويوصف غالبًا بأنه من أسرع الألعاب الميدانية في العالم.","تعزز الرابطة أيضًا الموسيقى والرقص واللغة الأيرلندية، وملاعبها ولا سيما كروك بارك رموز وطنية."]}],"de":[{"heading":"Das Team vertritt den eigenen Ort","paragraphs":["Die Clubs sind nach Pfarrei und County organisiert, sodass die Spieler den Ort vertreten, aus dem sie kommen, nicht einen Markt.","Ein Dorf mit 500 Einwohnern stellt ein Hurling-Team, und die ganze Pfarrei erscheint zum County-Finale; die Spieler trainieren nach der Arbeit und sind am Montag wieder bei der Arbeit.","Wie stark diese Bindung lebt, unterscheidet sich nach Generation und Region: In Dublin und in neueren städtischen Vierteln ist sie schwächer als auf dem Land."]},{"heading":"Amateursport mit Streitfragen","paragraphs":["Die Spiele sind amateurhaft: Spieler werden nicht bezahlt, und Regeln zu Zahlungen und Transfers haben wiederholt Konflikte ausgelöst.","Hurling wird mit einem Eschenholz-Schläger und einem kleinen Ball gespielt, mit einem Punkt über die Latte und drei für ein Tor, und gilt oft als eines der schnellsten Feldspiele der Welt.","Die GAA fördert auch irische Musik, Tanz und die irische Sprache, und ihre Plätze, besonders Croke Park, sind nationale Symbole."]}],"en":[{"heading":"The team stands for the place","paragraphs":["Clubs are organised by parish and county, so players represent where they come from, not a market.","A village of 500 people fields a hurling team, and the whole parish turns out for the county final; the players train after work and are back at work on Monday.","How strongly that bond is felt varies by region and generation, running lighter in Dublin and newer urban communities than in the countryside."]},{"heading":"An amateur game with disputes","paragraphs":["The games are amateur: players are not paid, and rules on payments and transfers have caused repeated conflict.","Hurling is played with an ash stick and a small ball, with one point over the crossbar and three for a goal, and is often described as one of the fastest field games in the world.","The GAA also promotes Irish music, dance and the Irish language, and its grounds, especially Croke Park, are national symbols."]}]},"context":{"countries":["IE"],"region":"Ireland","continent":"europe","languages":["ga","en"],"period":"contemporary"},"tags":["games-and-leisure","Ireland"],"sources":[{"organization":"Wikipedia","title":{"ar":"Gaelic Athletic Association","de":"Gaelic Athletic Association","en":"Gaelic Athletic Association"},"url":"https://en.wikipedia.org/wiki/Gaelic_Athletic_Association","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Hurling","de":"Hurling","en":"Hurling"},"url":"https://en.wikipedia.org/wiki/Hurling","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"قرية من 500 نسمة تُشكّل فريق هيرلينغ، وتخرج الرعية كلها إلى نهائي المقاطعة؛ يتدرب اللاعبون بعد العمل ويعودون إلى العمل يوم الاثنين.","de":"Ein Dorf mit 500 Einwohnern stellt ein Hurling-Team, und die ganze Pfarrei erscheint zum County-Finale; die Spieler trainieren nach der Arbeit und sind am Montag wieder bei der Arbeit.","en":"A village of 500 people fields a hurling team, and the whole parish turns out for the county final; the players train after work and are back at work on Monday."},"misunderstanding":{"ar":"يظن البعض أن كون اللعبة هواة يعني أنها بسيطة أو غير منظمة، لكن المستوى الأعلى منظم تجاريًا، وتاريخ الرابطة يشمل سياسة وطنية واستبعادًا.","de":"Manche halten Amateursport für einfach oder unorganisiert, doch die Spitze ist hoch organisiert und kommerziell, und die Geschichte der GAA umfasst nationalistische Politik und Ausgrenzung.","en":"Some assume amateur means simple or disorganised, yet the top level is highly organised and commercial, and the GAA's history includes nationalist politics and exclusion."},"comparison":{"ar":"في كثير من البلدان يمثل اللاعب ناديًا يشتريه سوق، أما هنا فيمثل رعيته ومقاطعته.","de":"In vielen Ländern vertritt ein Spieler einen Club, den ein Markt kauft; hier vertritt er seine Pfarrei und sein County.","en":"In many countries a player represents a club a market buys; here a player represents a parish and a county."}},{"id":"eur-023","version":2,"slug":"la-bise-how-many-kisses-depends-on-where-you-are","contentType":"note","category":"social-behaviour","title":{"ar":"القبلة الفرنسية: عدد القبلات يعتمد على المكان","de":"La bise: Wie viele Küsse, hängt vom Ort ab","en":"La bise: how many kisses depends on where you are"},"deck":{"ar":"في فرنسا، التحية بالقبلة على الخدين ليست مجرد عادة، بل نظام اجتماعي دقيق يختلف باختلاف المنطقة والأجيال.","de":"In Frankreich ist die Begrüßung mit Wangenküssen keine bloße Gewohnheit, sondern ein fein abgestimmtes soziales System, das je nach Region und Generation variiert.","en":"In France, the cheek-kiss greeting is not just a habit but a finely tuned social system that varies by region and generation."},"teaser":{"ar":"هل تعرف كم قبلة يجب أن تقدم عند لقاء صديق فرنسي؟ الجواب يختلف بين الشمال والجنوب، وبين الأجيال أيضاً.","de":"Wissen Sie, wie viele Küsse man einem französischen Freund geben sollte? Die Antwort variiert zwischen Nord und Süd und auch zwischen den Generationen.","en":"Do you know how many kisses to give a French friend? The answer varies between north and south, and between generations too."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقوس التحية","paragraphs":["في فرنسا، تُعرف التحية بالقبلة على الخدين باسم 'لا بيز'. وهي عادة اجتماعية تتضمن لمس الخدين وإصدار صوت قبلة خفيف، عادة دون تلامس الشفاه. تختلف عدد القبلات حسب المنطقة: قبلتان شائعتان في معظم أنحاء الشمال، بينما ثلاث أو أربع قبلات معتادة في أجزاء من الجنوب والغرب. هذه العادة تحكمها قواعد غير مكتوبة: فهي شائعة بين الأصدقاء والعائلة والزملاء في المواقف غير الرسمية، بينما المصافحة أكثر أماناً في مجال الأعمال ومع الغرباء."]},{"heading":"التغير الاجتماعي والاختلاف","paragraphs":["قد تستغرق التحية وقتاً: في غرفة تضم عشرة معارف، قد يُتوقع من الجميع تحية بعضهم البعض فرداً فرداً. وقد أدت جائحة كوفيد-19 إلى انقطاع هذه العادة، حيث احتفظت بعض أماكن العمل والمدارس بالمصافحة أو التحية اللفظية منذ ذلك الحين. وتختلف العادات بشكل كبير حسب المنطقة والجيل: فالعادات في المناطق الريفية والجنوبية تختلف عن عادات باريس، والرجال أحياناً يصافحون بدلاً من القبلة، وكثيرون لا يحبون هذه العادة، لذا لا توجد قاعدة فرنسية واحدة."]}],"de":[{"heading":"Das Begrüßungsritual","paragraphs":["In Frankreich ist die Begrüßung mit Wangenküssen als 'la bise' bekannt. Es ist ein soziales Ritual, bei dem man die Wangen berührt und ein leichtes Kussgeräusch macht, normalerweise ohne Lippenkontakt. Die Anzahl der Küsse variiert je nach Region: Zwei sind in weiten Teilen des Nordens üblich, während drei oder vier in Teilen des Südens und Westens üblich sind. Diese Begrüßung unterliegt ungeschriebenen Regeln: Sie ist üblich unter Freunden, Familie und Kollegen in informellen Situationen, während ein Händedruck im Geschäftsleben und bei Fremden sicherer ist."]},{"heading":"Sozialer Wandel und Unterschiede","paragraphs":["Die Begrüßung kann Zeit in Anspruch nehmen: In einem Raum mit zehn Bekannten wird möglicherweise erwartet, dass jeder jeden einzeln begrüßt. Die COVID-19-Pandemie hat diese Gewohnheit unterbrochen, und einige Arbeitsplätze und Schulen haben seitdem einen Händedruck oder eine verbale Begrüßung beibehalten. Die Bräuche variieren stark je nach Region und Generation: Ältere, ländliche und südliche Gewohnheiten unterscheiden sich von denen in Paris, Männer schütteln manchmal stattdessen Hände, und viele Menschen mögen es nicht, daher gibt es keine einheitliche französische Regel."]}],"en":[{"heading":"The greeting ritual","paragraphs":["In France, the cheek-kiss greeting is known as 'la bise'. It is a social ritual involving touching cheeks and making a light kiss sound, usually without lip contact. The number of kisses varies by region: two are common in much of the north, while three or four are usual in parts of the south and west. This greeting is governed by unwritten rules: it is common between friends, family and colleagues in informal settings, while a handshake is safer in business and with strangers."]},{"heading":"Social change and variation","paragraphs":["The greeting can take time: in a room of ten acquaintances, everyone may be expected to greet everyone else individually. The COVID-19 pandemic interrupted the habit, and some workplaces and schools have kept a handshake or a verbal greeting since. Habits vary greatly by region and generation: older, rural and southern habits differ from Parisian ones, men sometimes shake hands instead, and many people dislike it, so there is no single French rule."]}]},"context":{"countries":["FR"],"region":"Western Europe","continent":"europe","languages":["fr"],"period":"contemporary"},"tags":["social-behaviour","Western Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Cheek kissing","de":"Cheek kissing","en":"Cheek kissing"},"url":"https://en.wikipedia.org/wiki/Cheek_kissing","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of France","de":"Culture of France","en":"Culture of France"},"url":"https://en.wikipedia.org/wiki/Culture_of_France","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"باريسي يلتقي بوالدي صديقه يقدم قبلتين؛ زائر من مرسيليا يقدم ثلاثاً، والوقفة الناتجة هي تفاوض اجتماعي صغير.","de":"Ein Pariser, der die Eltern eines Freundes trifft, bietet zwei Küsse an; ein Besucher aus Marseille bietet drei an, und die daraus resultierende Pause ist eine kleine soziale Verhandlung.","en":"A Parisian meeting a friend's parents offers two kisses; a visitor from Marseille offers three, and the resulting pause is a small social negotiation."},"misunderstanding":{"ar":"يعتقد البعض أن القبلة الفرنسية عالمية في فرنسا، لكنها في الواقع غير موحدة: ففي باريس قد تكون قبلتين، بينما في الجنوب ثلاث أو أربع، وقد يفضل البعض المصافحة.","de":"Manche glauben, die französische Begrüßung sei in ganz Frankreich gleich, aber sie ist tatsächlich nicht einheitlich: In Paris sind es oft zwei Küsse, im Süden drei oder vier, und manche ziehen einen Händedruck vor.","en":"Some believe the French kiss greeting is uniform across France, but it is not: in Paris it may be two kisses, in the south three or four, and some prefer a handshake."},"comparison":{"ar":"على عكس المصافحة التي تُستخدم في السياقات الرسمية، فإن 'لا بيز' تعبير عن العلاقة الحميمة والود، لكنها تخضع لقواعد اجتماعية دقيقة.","de":"Im Gegensatz zum Händedruck, der in formellen Kontexten verwendet wird, ist 'la bise' ein Ausdruck von Vertrautheit und Freundlichkeit, unterliegt aber strengen sozialen Regeln.","en":"Unlike the handshake, used in formal contexts, 'la bise' expresses familiarity and friendliness, but it is subject to strict social rules."}},{"id":"eur-024","version":2,"slug":"terroir-why-french-food-is-argued-by-place","contentType":"note","category":"food-and-hospitality","title":{"ar":"التروار: لماذا يُناقش الطعام الفرنسي بالمكان","de":"Terroir: Warum französisches Essen nach Herkunft streitet","en":"Terroir: why French food is argued by place"},"deck":{"ar":"فكرة تجمع بين التربة والمناخ والتقاليد والمهارة البشرية لتمنح المنتج طابعه، وتحولت إلى أداة تسويق عالمية.","de":"Eine Idee, die Boden, Klima, Tradition und menschliches Können vereint und einem Produkt seinen Charakter gibt – heute ein globales Marketinginstrument.","en":"An idea combining soil, climate, tradition and human skill to give a product its character, now a global marketing tool."},"teaser":{"ar":"في فرنسا، لا يُقاس الطعام بالطعم فقط، بل بالمكان الذي يأتي منه، وبالقواعد التي تحمي اسمه.","de":"In Frankreich wird Essen nicht nur nach Geschmack beurteilt, sondern nach dem Ort, aus dem es kommt, und nach den Regeln, die seinen Namen schützen.","en":"In France, food is judged not only by taste but by the place it comes from and the rules that protect its name."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما وراء الاسم","paragraphs":["التروار يعني اجتماع التربة والمناخ والتقاليد والمهارة البشرية لتمنح المنتج طابعه. هذه الفكرة الفرنسية أصبحت أداة تسويق عالمية.","نظام تسمية المنشأ المراقبة (AOC)، الذي تم تقنينه عام 1935، يشهد بأن إنتاج منتج ما وتحويله يتمان في منطقة محددة وبطرق معترف بها."]},{"heading":"قواعد صارمة وحماية اجتماعية","paragraphs":["يشمل نظام AOC النبيذ والجبن والزبدة واللحوم وغيرها، وقد تحدد القواعد أصناف العنب والمحصول والتعتيق وحتى حجم الحصاد. بدأ النظام رداً على الغش والإفراط في إنتاج النبيذ، فحوّل أسماء الأماكن إلى ضمانات قانونية.","التروار أيضاً فكرة اجتماعية تربط المنتجين بالمناظر الطبيعية والهويات المحلية، ويُستخدم للدفاع عن صغار المنتجين ضد الطعام الصناعي. ويختلف تطبيقه بين الأجيال والمناطق، إذ يتمسك بعض الشباب بالأسواق المحلية بينما يرى آخرون أنه قيد بيروقراطي."]}],"de":[{"heading":"Hinter dem Namen","paragraphs":["Terroir bedeutet das Zusammenspiel von Boden, Klima, Tradition und menschlichem Können, das einem Produkt seinen Charakter verleiht. Diese französische Idee ist zu einem globalen Marketinginstrument geworden.","Das 1935 formalisierte System der appellation d'origine contrôlée (AOC) bescheinigt, dass Herstellung und Verarbeitung eines Produkts in einem definierten Gebiet nach anerkannten Methoden erfolgen."]},{"heading":"Strenge Regeln und sozialer Schutz","paragraphs":["AOC umfasst Wein, Käse, Butter, Fleisch und andere Produkte; die Regeln können Rebsorten, Erträge, Reifung und sogar die Erntemenge vorschreiben. Das System entstand als Reaktion auf Betrug und Überproduktion im Weinhandel und machte Ortsnamen zu rechtlichen Garantien.","Terroir ist auch eine soziale Idee: Es verbindet Produzenten mit Landschaften und lokalen Identitäten und wird genutzt, um kleine Produzenten gegen industrielle Lebensmittel zu verteidigen. Die Anwendung variiert regional und generationell – manche Jüngere setzen auf lokale Märkte, andere sehen darin vor allem Bürokratie."]}],"en":[{"heading":"Behind the name","paragraphs":["Terroir means the combination of soil, climate, tradition and human skill that gives a product its character. This French idea has become a global marketing tool.","The appellation d'origine contrôlée (AOC) system, formalised in 1935, certifies that a product's production and processing take place in a defined area using recognised methods."]},{"heading":"Strict rules and social protection","paragraphs":["AOC covers wine, cheese, butter, meat and other products, and the rules can specify grape varieties, yields, ageing and even harvest size. The system began as a response to fraud and overproduction in the wine trade, turning place names into legal guarantees.","Terroir is also a social idea: it ties producers to landscapes and local identities and is used to defend small producers against industrial food. Its application varies by region and generation, with some younger producers embracing local markets while others see it as bureaucracy."]}]},"context":{"countries":["FR"],"region":"Western Europe","continent":"europe","languages":["fr"],"period":"contemporary"},"tags":["food-and-hospitality","Western Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Terroir","de":"Terroir","en":"Terroir"},"url":"https://en.wikipedia.org/wiki/Terroir","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Appellation d'origine contrôlée","de":"Appellation d'origine contrôlée","en":"Appellation d'origine contrôlée"},"url":"https://en.wikipedia.org/wiki/Appellation_d'origine_contr%C3%B4l%C3%A9e","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"منتِج جبن في منطقة كونتيه لا يستطيع ببساطة ادعاء الاسم: يجب أن يأتي الحليب من منطقة محددة، وأن تُغذى الأبقار بطرق معينة، ويفحص المفتشون الأقبية.","de":"Ein Käser in der Comté-Region kann den Namen nicht einfach beanspruchen: Die Milch muss aus einem definierten Gebiet stammen, die Kühe müssen auf bestimmte Weise gefüttert werden, und Inspektoren prüfen die Keller.","en":"A cheesemaker in the Comté region cannot simply claim the name: the milk must come from a defined area, the cows must be fed in specific ways, and inspectors check the cellars."},"misunderstanding":{"ar":"يُفهم التروار أحياناً كضمان للجودة أو الأصالة، لكنه في الواقع يحدد قواعد الإنتاج والمكان، وليس بالضرورة تفوق الطعم.","de":"Terroir wird manchmal als Garantie für Qualität oder Authentizität missverstanden, doch es legt Produktions- und Ortsregeln fest, nicht unbedingt einen überlegenen Geschmack.","en":"Terroir is sometimes mistaken for a guarantee of quality or authenticity, but it actually sets rules about production and place, not necessarily superior taste."},"comparison":{"ar":"في ألمانيا، تُحمى أسماء مثل 'شبانفيلدر' بموجب نظام تسمية المنشأ الأوروبي، لكن النقاش العام حول الطعام المحلي أقل ارتباطاً بفكرة التروار الفرنسية.","de":"In Deutschland werden Namen wie „Spannfelder“ durch das EU-Herkunftssystem geschützt, doch die öffentliche Debatte über lokales Essen ist weniger stark mit der französischen Terroir-Idee verbunden.","en":"In Germany, names like 'Spannfelder' are protected under the EU origin system, but public debate about local food is less tied to the French terroir idea."}},{"id":"eur-025","version":2,"slug":"the-french-cafe-is-a-room-for-watching-the-street","contentType":"scene","category":"cities-and-community","title":{"ar":"المقهى الفرنسي مسرح لمراقبة الشارع","de":"Das französische Café als Straßenbühne","en":"The French café is a room for watching the street"},"deck":{"ar":"كيف تحوّل المقهى إلى مؤسسة اجتماعية تحدد إيقاع الحياة اليومية في فرنسا.","de":"Wie das Café zu einer sozialen Institution wurde, die den Alltag in Frankreich prägt.","en":"How the café became a social institution that sets the rhythm of daily life in France."},"teaser":{"ar":"في فرنسا، المقهى ليس مجرد مكان للقهوة، بل غرفة زجاجية لمراقبة الشارع واختبار الانتماء.","de":"In Frankreich ist das Café kein bloßer Kaffeestand, sondern ein verglaster Raum zur Straßenbeobachtung und ein Test der Zugehörigkeit.","en":"In France, the café is not just a place for coffee but a glassed-in room for watching the street and testing belonging."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقوس الزبون بين الرصيف والطاولة","paragraphs":["في المقهى الفرنسي، القهوة تُشرب بسرعة على البار، بينما طاولة التراس تُستأجر بالساعة للحديث ومراقبة المارة. تختلف الأسعار بين البار والطاولة الداخلية والتراس، والفاتورة عقد يحدد مدة ترحيبك.","كانت المقاهي ملتقى للكتّاب والسياسيين والعمال، وجعل وجوديون سان جيرمان دي بري من مقهى الضفة اليسرى صورة عالمية. بعد حظر التدخين عام 2008 تغيّر جو التراس واقتصاده، وكثير من المقاهي صار يقدم طعامًا أكثر من القهوة."]},{"heading":"البيسرو والحياة الاجتماعية","paragraphs":["البيسرو، وهو مطعم صغير بقائمة قصيرة، تطور جنبًا إلى جنب مع المقهى ويتقاسم معه دوره الاجتماعي. يختلف هذا المشهد بين المدن والأرياف، وبين الأجيال: فالشباب قد يفضلون مساحات العمل المشترك، بينما يبقى كبار السن أوفياء للبار."]}],"de":[{"heading":"Rituale zwischen Theke und Terrasse","paragraphs":["Im französischen Café trinkt man den Kaffee schnell an der Theke, während ein Terrassentisch stundenweise für Gespräch und People-Watching gemietet wird. Die Preise unterscheiden sich oft zwischen Theke, Innentisch und Terrasse, und die Rechnung ist ein Vertrag darüber, wie lange man willkommen ist.","Cafés dienten Schriftstellern, Politikern und Arbeitern als Treffpunkt, und die Existenzialisten von Saint-Germain-des-Prés machten das Left-Bank-Café zu einem globalen Bild. Das Rauchverbot von 2008 veränderte Atmosphäre und Ökonomie der Terrasse, und viele Cafés servieren heute mehr Essen als Kaffee."]},{"heading":"Bistro und soziales Leben","paragraphs":["Das Bistro, ein kleineres Lokal mit kurzer Speisekarte, entwickelte sich parallel zum Café und teilt dessen soziale Rolle. Diese Szene variiert regional und generationell: Jüngere mögen Co-Working-Spaces bevorzugen, während Ältere der Theke treu bleiben."]}],"en":[{"heading":"Rituals between counter and terrace","paragraphs":["In a French café, coffee is drunk quickly at the counter, while a terrace table is rented by the hour for conversation and people-watching. Prices often differ between the counter, the inside table and the terrace, and the bill is a contract about how long you are welcome to stay.","Cafés served as meeting places for writers, politicians and workers, and the existentialists of Saint-Germain-des-Prés made the Left Bank café a global image. The smoking ban of 2008 changed the atmosphere and the economics of the terrace, and many cafés now serve more food than coffee."]},{"heading":"The bistro and social life","paragraphs":["The bistro, a smaller eating place with a short menu, developed alongside the café and shares its social role. This scene varies by region and generation: younger people may prefer co-working spaces, while older patrons remain loyal to the bar."]}]},"context":{"countries":["FR"],"region":"Western Europe","continent":"europe","languages":["fr"],"period":"contemporary"},"tags":["cities-and-community","Western Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Coffeehouse","de":"Coffeehouse","en":"Coffeehouse"},"url":"https://en.wikipedia.org/wiki/Coffeehouse","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Bistro","de":"Bistro","en":"Bistro"},"url":"https://en.wikipedia.org/wiki/Bistro","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"رجل متقاعد يطلب إسبريسو صغيرًا على البار، يقرأ الصحيفة، يحيي صاحب المقهى ويغادر في عشر دقائق، بينما تحتسي طالبة كريم كافيه على التراس ساعتين.","de":"Ein Rentner bestellt einen kleinen Espresso an der Bar, liest die Zeitung, grüßt den Besitzer und ist in zehn Minuten weg, während eine Studentin zwei Stunden lang einen Café crème auf der Terrasse genießt.","en":"A retired man orders a small espresso at the bar, reads the newspaper, greets the owner and is gone in ten minutes, while a student nurses a café crème on the terrace for two hours."},"misunderstanding":{"ar":"يُفهم أحيانًا أن الجلوس على التراس مجرد رفاهية، لكنه في الواقع عقد زمني: تدفع مقابل مدة بقائك وليس فقط مقابل المشروب.","de":"Manchmal wird das Sitzen auf der Terrasse als bloßer Luxus missverstanden, doch es ist ein Zeitvertrag: Man zahlt für die Dauer des Bleibens, nicht nur für das Getränk.","en":"Sitting on the terrace is sometimes misunderstood as mere luxury, but it is actually a time contract: you pay for the duration of your stay, not just for the drink."},"comparison":{"ar":"في مدن أخرى، قد يكون المقهى مكانًا عابرًا للقهوة السريعة، لكن في فرنسا هو مساحة للتفاعل الاجتماعي البطيء والمراقبة اللطيفة للشارع.","de":"In anderen Städten mag das Café ein flüchtiger Ort für schnellen Kaffee sein, in Frankreich ist es ein Raum für langsame soziale Interaktion und sanfte Straßenbeobachtung.","en":"In other cities, the café may be a fleeting spot for quick coffee, but in France it is a space for slow social interaction and gentle street-watching."}},{"id":"eur-026","version":2,"slug":"grandes-ecoles-and-the-making-of-french-elites","contentType":"note","category":"work-and-education","title":{"ar":"المدارس الكبرى وصناعة النخبة الفرنسية","de":"Grandes écoles und die französische Elite","en":"Grandes écoles and the making of French elites"},"deck":{"ar":"نظام تعليمي موازٍ للجامعات العامة يختار طلبته عبر مسابقات تنافسية بعد سنتين من الأقسام التحضيرية.","de":"Ein paralleles Hochschulsystem zur öffentlichen Universität, das seine Studierenden über Wettbewerbsprüfungen nach zwei Jahren Vorbereitungsklassen auswählt.","en":"A parallel higher-education system beside public universities, selecting students through competitive exams after two years of preparatory classes."},"teaser":{"ar":"كيف تصنع المدارس الكبرى النخبة في فرنسا؟ رحلة من الأقسام التحضيرية إلى المناصب العليا، ونقاش حول تكافؤ الفرص.","de":"Wie entsteht Frankreichs Elite? Von den Vorbereitungsklassen bis in Spitzenpositionen – und die Debatte um Chancengleichheit.","en":"How do grandes écoles shape France's elite? From prépa to top posts, and the debate over equal opportunity."},"readingMinutes":1,"sections":{"ar":[{"heading":"مسار الانتقاء","paragraphs":["المدارس الكبرى مؤسسات تعليم عالٍ نخبوية في فرنسا تعمل إلى جانب نظام الجامعات العامة. يتم الالتحاق بها عادةً عبر مسابقة تنافسية بعد سنتين من الأقسام التحضيرية، وليس عبر قبول مفتوح.","من أشهرها المدرسة المتعددة التقنيات (École Polytechnique) التي تأسست عام 1794، والمدرسة الوطنية للإدارة (ENA) التي أنشئت عام 1945 لتدريب كبار الموظفين المدنيين. ويُعرف خريجوها باسم إينارك وبوليتكنيسيان ونورماليان.","يختلف الوضع حسب المنطقة والجيل: ففي باريس والمدن الكبرى تكون الأقسام التحضيرية أكثر حضوراً، بينما قد لا يلتقي طلاب الأرياف بهذا المسار إلا عبر معلومات محدودة."]},{"heading":"نقد التكافؤ","paragraphs":["يقول النقاد إن النظام يعيد إنتاج عدم المساواة، إذ تستقطب الأقسام التحضيرية والمدارس الكبرى أبناء العائلات الميسورة بشكل غير متناسب. وقد استُبدلت ENA عام 2022 بمعهد جديد بعد انتقادات النخبوية."]}],"de":[{"heading":"Der Auswahlweg","paragraphs":["Die Grandes écoles sind elitäre französische Hochschulen, die neben dem öffentlichen Universitätssystem bestehen. Der Zugang erfolgt meist über eine Wettbewerbsprüfung nach zwei Jahren Vorbereitungsklassen, nicht durch offene Zulassung.","Zu den bekanntesten zählen die École Polytechnique, gegründet 1794, und die École nationale d'administration (ENA), 1945 zur Ausbildung hoher Beamter geschaffen. Ihre Absolventen heißen énarques, polytechniciens und normaliens.","Je nach Region und Generation unterscheidet sich der Zugang: In Paris und großen Städten sind Vorbereitungsklassen präsenter, während Jugendliche aus ländlichen Gebieten oft nur begrenzte Informationen über diesen Weg haben."]},{"heading":"Kritik an der Chancengleichheit","paragraphs":["Kritiker sagen, das System reproduziere Ungleichheit: Vorbereitungsklassen und Grandes écoles ziehen überproportional Kinder privilegierter Familien an. Die ENA wurde 2022 nach Elitismus-Kritik durch ein neues Institut ersetzt."]}],"en":[{"heading":"The selection path","paragraphs":["Grandes écoles are elite French higher-education institutions that run alongside the public university system. Entry is usually by competitive examination after two years of preparatory classes rather than by open admission.","The most famous include the École Polytechnique, founded in 1794, and the École nationale d'administration (ENA), created in 1945 to train senior civil servants. Their graduates dominate the senior civil service, business and politics and are known as énarques, polytechniciens and normaliens.","Access varies by region and generation: in Paris and large cities, preparatory classes are more visible, while students from rural areas may encounter the path only through limited information."]},{"heading":"Critique of fairness","paragraphs":["Critics say the system reproduces inequality: preparatory classes and the grandes écoles draw disproportionately from privileged families, and ENA was replaced in 2022 by a new institute after criticism of elitism."]}]},"context":{"countries":["FR"],"region":"Western Europe","continent":"europe","languages":["fr"],"period":"contemporary"},"tags":["work-and-education","Western Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Grande école","de":"Grande école","en":"Grande école"},"url":"https://en.wikipedia.org/wiki/Grande_%C3%A9cole","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Baccalauréat","de":"Baccalauréat","en":"Baccalauréat"},"url":"https://en.wikipedia.org/wiki/Baccalaur%C3%A9at","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب في الثانوية من مدينة إقليمية ينتقل إلى ثانوية في باريس لقضاء سنتين في الأقسام التحضيرية، ثم يجتاز أسبوعاً من الامتحانات الكتابية والشفوية أملاً في مقعد في مدرسة كبرى.","de":"Ein Lycée-Schüler aus einer Provinzstadt wechselt für zwei Jahre prépa an ein Pariser Lycée und legt dann eine Woche schriftlicher und mündlicher Prüfungen ab, in der Hoffnung auf einen Platz an einer grande école.","en":"A lycée student from a provincial town enters a Paris lycée for two years of prépa, then sits a week of written and oral exams hoping for a place at a grande école."},"misunderstanding":{"ar":"المدارس الكبرى ليست نظاماً واحداً: فمدارس الهندسة وإدارة الأعمال والعلوم الإنسانية تختلف كثيراً، بعضها عام وبعضها خاص، ومعظم الطلاب الفرنسيين لا يصادفونها أبداً.","de":"Die Grandes écoles sind kein einheitliches System: Ingenieur-, Wirtschafts- und Geisteswissenschaftsschulen unterscheiden sich stark, einige sind öffentlich, andere privat, und die meisten französischen Studierenden begegnen ihnen nie.","en":"The grandes écoles are not one system: engineering, business and humanities schools differ greatly, some are public and some private, and most French students never encounter them at all."},"comparison":{"ar":"على عكس الجامعات الفرنسية المفتوحة للجميع تقريباً، تعتمد المدارس الكبرى على انتقاء صارم عبر مسابقات، مما يجعلها أشبه بنظام نخبوي داخل التعليم العالي.","de":"Anders als die fast allen offenstehenden französischen Universitäten setzen die Grandes écoles auf strenge Auswahl durch Wettbewerbsprüfungen und wirken wie ein elitärer Pfad innerhalb der Hochschulbildung.","en":"Unlike French universities, which are open to nearly all baccalauréat holders, the grandes écoles rely on strict selection through competitive exams, making them a distinct elite track within higher education."}},{"id":"eur-027","version":2,"slug":"going-dutch-splitting-the-bill-as-a-social-philosophy","contentType":"note","category":"social-behaviour","title":{"ar":"الحساب المشترك في هولندا","de":"Geteilte Rechnung als Lebenshaltung","en":"Going Dutch: splitting the bill as a social philosophy"},"deck":{"ar":"دفع كل شخص نصيبه من الفاتورة ليس بخلًا، بل عادة اجتماعية تعكس ثقافة المساواة والصراحة في هولندا.","de":"In den Niederlanden zahlt jede Person ihren Anteil, und das gilt als praktisch, fair und keineswegs als unhöflich.","en":"In the Netherlands, paying your own share is not stinginess but a normal, unembarrassed habit rooted in equality and directness."},"teaser":{"ar":"في هولندا، تقسيم الفاتورة بدقة أمر طبيعي لا يحرج أحدًا، ويكشف عن نظرة عملية للعلاقات والمال والمساواة بين الناس.","de":"Wer in den Niederlanden die Rechnung teilt, zeigt keine Kälte, sondern eine alltägliche Vorstellung von Gleichheit, Direktheit und fairen Beziehungen.","en":"Splitting a restaurant bill to the cent looks cold to outsiders, yet in the Netherlands it expresses fairness, practicality and an easy kind of friendship."},"readingMinutes":1,"sections":{"ar":[{"heading":"دفع النصيب بدقة","paragraphs":["في هولندا يعني التعبير الإنجليزي «Going Dutch» أن يدفع كل شخص نصيبه من الفاتورة، وهذا جزء طبيعي من الحياة الاجتماعية لا يشعر فيه أحد بالحرج.","يستخدم الأصدقاء تطبيقات مثل «Tikkie» لطلب المبالغ الصغيرة بدقة، ويتابعون الديون الصغيرة دون أن يعتبروها إهانة أو اتهامًا بالبخل.","تختلف هذه العادة بحسب الجيل والمنطقة والسياق، فبعض الناس يتساهلون مع الأصدقاء المقربين بينما يلتزم آخرون بالتقسيم الحرفي."]},{"heading":"صراحة ومساواة","paragraphs":["تنسجم هذه العادة مع ثقافة أوسع من الصراحة والمساواة، فالسؤال عن من يدين لمن يُعدّ أمرًا عمليًا لا وقاحة.","تظهر أعياد الميلاد النمط نفسه، إذ يُتوقع من الضيوف غالبًا إحضار هدية صغيرة وتهنئة أفراد عائلة صاحب العيد بترتيب معيّن.","العبارة نفسها أقدم وأعقد من الممارسة، فقد كانت أصلًا وصفًا إنجليزيًا يحمل دلالة سلبية عن البخل، ودخلت الإنجليزية في القرن التاسع عشر."]}],"de":[{"heading":"Genaue Anteile, kleine Beträge","paragraphs":["„Going Dutch“ bedeutet, dass jede Person ihren eigenen Anteil zahlt, und in den Niederlanden gehört das selbstverständlich und ohne Peinlichkeit zum sozialen Leben.","Freunde teilen Restaurantrechnungen oft genau auf, nutzen Zahlungsanfragen wie Tikkie und verfolgen kleine Schulden, ohne sie als Beleidigung zu verstehen.","Je nach Generation, Region und Anlass wird die Regel lockerer gehandhabt, etwa im engeren Freundeskreis oder bei besonderen Einladungen."]},{"heading":"Direktheit und Gleichheit","paragraphs":["Die Gewohnheit passt zu einer Kultur der Direktheit und Gleichheit: Wer wem was schuldet, fragt man praktisch und nicht aus Misstrauen.","Bei Geburtstagen zeigt sich dasselbe Muster, denn Gäste bringen oft ein kleines Geschenk mit und gratulieren den Familienmitgliedern der Geburtstagsperson in einer festen Reihenfolge.","Der Ausdruck selbst ist älter und komplizierter als die Praxis, denn er war ursprünglich ein englisches Schimpfwort auf angebliche Knausrigkeit und kam im 19. Jahrhundert ins Englische."]}],"en":[{"heading":"Exact shares, small debts","paragraphs":["“Going Dutch” means each person pays their own share, and in the Netherlands this is a normal, unembarrassed part of social life.","Dutch friends commonly split restaurant bills precisely, use payment request apps such as Tikkie, and keep track of small debts without treating them as insults.","The habit varies by generation, region and setting, with some groups far more relaxed about treating close friends than others."]},{"heading":"Directness and equality","paragraphs":["The habit fits a wider culture of directness and equality: asking who owes what is considered practical rather than rude.","Birthdays show the same pattern, as guests are often expected to bring a small gift and to congratulate the birthday person’s family members in a set order.","The phrase itself is older and more complicated than the practice suggests: it was originally an English slur implying Dutch stinginess, and it entered English in the 19th century."]}]},"context":{"countries":["NL"],"region":"Western Europe","continent":"europe","languages":["nl"],"period":"contemporary"},"tags":["social-behaviour","Western Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Going Dutch","de":"Going Dutch","en":"Going Dutch"},"url":"https://en.wikipedia.org/wiki/Going_Dutch","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of the Netherlands","de":"Culture of the Netherlands","en":"Culture of the Netherlands"},"url":"https://en.wikipedia.org/wiki/Culture_of_the_Netherlands","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بعد العشاء مع الأصدقاء يدفع أحدهم الفاتورة كاملة ثم يرسل طلب «Tikkie» بنصيب كل واحد بدقة، ولا يقترح أحد أن يتحمّل الدافع المبلغ عن الجميع.","de":"Nach dem Essen mit Freunden zahlt eine Person die Rechnung und schickt per Tikkie eine Anfrage über den genauen Anteil aller; niemand erwartet, dass die zahlende Person die anderen einlädt.","en":"After dinner with friends, one person pays the bill and sends a Tikkie request for everyone’s exact share; nobody suggests that the payer should cover it."},"misunderstanding":{"ar":"الصورة النمطية عن الهولندي البخيل قديمة وغير منصفة، فكثير من الهولنديين يودّون تكريم أصدقائهم بسهولة، والعادة تتباين حسب الجيل والمنطقة والمناسبة.","de":"Der geizige Holländer ist ein unfaires, veraltetes Klischee; viele Niederländer geben Freunden gern etwas aus, und die Gewohnheit variiert nach Generation, Region und Situation.","en":"The stingy Dutchman is an unfair, outdated stereotype; many Dutch people happily treat friends, and the split-bill habit varies by generation, region and setting."},"comparison":{"ar":"في مجتمعات كثيرة يُتوقع من المضيف أو من يبادر بدفع الفاتورة أن يتحمّلها كاملة، وقد يُفسَّر تقسيمها الدقيق كفتور، بينما يُقرأ في هولندا كعدالة عملية.","de":"In vielen Gesellschaften erwartet man, dass die einladende Person die ganze Rechnung übernimmt, und eine genaue Teilung könnte distanziert wirken; in den Niederlanden gilt sie als praktische Fairness.","en":"In many societies the person who picks up the bill is expected to cover it all, and precise splitting can read as distance; in the Netherlands it reads as practical fairness."}},{"id":"eur-028","version":2,"slug":"gezelligheid-the-dutch-word-for-a-room-that-works","contentType":"note","category":"everyday-life","title":{"ar":"خيزيليخهايد: الكلمة الهولندية للجو الدافئ","de":"Gezelligheid: das niederländische Wort für eine Atmosphäre, die alle mitgestalten","en":"Gezelligheid: the Dutch word for a room that works"},"deck":{"ar":"مفهوم هولندي يجعل من الجو الاجتماعي واجباً جماعياً، حيث يتوقع من الجميع المساهمة فيه.","de":"Ein niederländisches Konzept, das aus einem Raum eine gemeinsame soziale Verpflichtung macht – Gastgeber und Gäste tragen gleichermaßen dazu bei.","en":"A Dutch concept that turns a shared atmosphere into a social obligation, where hosts set the scene and guests are expected to add to it."},"teaser":{"ar":"في هولندا، الكلمة ليست مجرد صفة للغرفة، بل التزام اجتماعي: المضيف يهيئ المكان والضيف يضيف إليه.","de":"In den Niederlanden ist das Wort keine bloße Beschreibung eines Raumes, sondern eine soziale Erwartung: Der Gastgeber bereitet vor, der Gast fügt hinzu.","en":"In the Netherlands, the word is not just a description of a room but a social expectation: the host arranges, the guest contributes."},"readingMinutes":1,"sections":{"ar":[{"heading":"معنى يتجاوز الترجمة","paragraphs":["خيزيليخهايد هو مفهوم هولندي لجو دافئ ومبهج يشاركه الناس. الصفة «خيزيليخ» تصف شخصاً أو غرفة أو أمسية تنتج هذا الجو. يصعب ترجمتها: كلمة «مريح» تغطي جزءاً فقط، بينما يستخدمها الهولنديون لكل شيء من المقهى إلى عشاء عائلي إلى مكتب منظم.","يرتبط المفهوم بتوقعات اجتماعية: المضيفون يعدون الإضاءة والجلوس والطعام لخلق المزاج، ويُتوقع من الضيوف المساهمة فيه بدلاً من الاكتفاء باستهلاكه. الكلمة تظهر باستمرار في الكلام اليومي: حفلة فاشلة هي «نيت خيزيليخ»، ودعوة كثيراً ما تنتهي بـ«خيزيليخ!»."]},{"heading":"بين الهوية والانتماء","paragraphs":["ترتبط خيزيليخهايد بالألمانية «غيموتليشكايت» لكنها أكثر اجتماعية وأقل تركيزاً على الراحة، وغالباً ما تُذكر كجزء أساسي من الهوية الهولندية. هذا المفهوم هو وصف ذاتي وطني بقدر ما هو حقيقة ملحوظة، والحياة الاجتماعية الهولندية يمكن أن تكون خيزيليخ ومنظمة للغاية أو حصرية في آن واحد؛ يجد القادمون الجدد أحياناً صعوبة في دخول هذا الدفء."]}],"de":[{"heading":"Mehr als nur gemütlich","paragraphs":["Gezelligheid ist ein niederländisches Konzept für eine warme, gesellige Atmosphäre, die mit anderen geteilt wird. Das Adjektiv „gezellig“ beschreibt eine Person, einen Raum oder einen Abend, der diese Stimmung erzeugt. Es ist notorisch schwer zu übersetzen: „gemütlich“ deckt nur einen Teil ab, und die Niederländer verwenden es für alles vom Café über ein Familienessen bis hin zu einem gut geplanten Büro.","Das Konzept prägt soziale Erwartungen: Gastgeber arrangieren Beleuchtung, Sitzgelegenheiten und Essen, um die Stimmung zu schaffen, und Gäste sollen dazu beitragen, statt nur zu konsumieren. Das Wort erscheint ständig in der Alltagssprache: Eine misslungene Party ist „niet gezellig“, und eine Einladung endet oft mit „gezellig!“."]},{"heading":"Zwischen Identität und Zugehörigkeit","paragraphs":["Gezelligheid ist mit dem deutschen Begriff Gemütlichkeit verwandt, aber sozialer und weniger auf Komfort bezogen, und gilt oft als Kern der niederländischen Identität. Das Konzept ist ebenso sehr nationale Selbstbeschreibung wie beobachtbare Tatsache, und das niederländische Sozialleben kann zugleich gezellig und hochorganisiert oder exklusiv sein; Neuankömmlinge finden den Zugang zu dieser Gemütlichkeit manchmal schwer."]}],"en":[{"heading":"More than just cosy","paragraphs":["Gezelligheid is a Dutch concept for a warm, convivial atmosphere shared with others; the adjective gezellig describes a person, room or evening that produces it. It is notoriously hard to translate: 'cosy' covers only part of it, and the Dutch use it for everything from a café to a family dinner to a well-planned office.","The concept shapes social expectations: hosts arrange lighting, seating and food to create the mood, and guests are expected to contribute to it rather than just consume it. The word appears constantly in everyday speech: a failed party is 'niet gezellig', and an invitation often ends with 'gezellig!'."]},{"heading":"Between identity and belonging","paragraphs":["Gezelligheid is related to German Gemütlichkeit but is more social and less about comfort, and it is often cited as a core part of Dutch identity. The concept is a national self-description as much as an observable fact, and Dutch social life can be both gezellig and highly organised or exclusive; newcomers sometimes find the cosiness hard to enter."]}]},"context":{"countries":["NL"],"region":"Western Europe","continent":"europe","languages":["nl"],"period":"contemporary"},"tags":["everyday-life","Western Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Gezelligheid","de":"Gezelligheid","en":"Gezelligheid"},"url":"https://en.wikipedia.org/wiki/Gezelligheid","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Gemütlichkeit","de":"Gemütlichkeit","en":"Gemütlichkeit"},"url":"https://en.wikipedia.org/wiki/Gem%C3%BCtlichkeit","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"صديق هولندي يدعوك للقهوة، يشعل شمعة، يضع نوعاً واحداً من البسكويت ويقول «خيزيليخ» عندما تجلس؛ الإطراء يتعلق بالجو، لا بالبسكويت.","de":"Ein niederländischer Freund lädt dich zum Kaffee ein, zündet eine Kerze an, stellt eine Sorte Kekse hin und sagt „gezellig“, als du dich setzt; das Kompliment gilt der Atmosphäre, nicht dem Keks.","en":"A Dutch friend invites you for coffee, lights a candle, puts out one kind of biscuit and says 'gezellig' as you sit down; the compliment is about the atmosphere, not the biscuit."},"misunderstanding":{"ar":"يظن البعض أن خيزيليخهايد مجرد ديكور أو رفاهية، لكنها في الواقع توقع اجتماعي يتطلب مشاركة فعلية من الجميع.","de":"Manche halten Gezelligheid für bloße Dekoration oder Luxus, doch tatsächlich ist es eine soziale Erwartung, die aktive Beteiligung von allen verlangt.","en":"Some think gezelligheid is just decoration or luxury, but it is actually a social expectation that requires active participation from everyone."},"comparison":{"ar":"تشبه «غيموتليشكايت» الألمانية لكنها أكثر اجتماعية وأقل تركيزاً على الراحة الفردية.","de":"Ähnlich der deutschen Gemütlichkeit, aber sozialer und weniger auf individuellen Komfort ausgerichtet.","en":"Similar to German Gemütlichkeit but more social and less focused on individual comfort."}},{"id":"eur-029","version":2,"slug":"how-the-netherlands-became-a-country-built-for-bicycles","contentType":"note","category":"cities-and-community","title":{"ar":"هولندا: بلد مبني للدراجات","de":"Niederlande: Land der Fahrräder","en":"How the Netherlands became a country built for bicycles"},"deck":{"ar":"كيف أصبحت الدراجة وسيلة النقل اليومية في هولندا، وكيف تشكّل حياة الناس اليومية؟","de":"Wie das Fahrrad in den Niederlanden zum Alltagsverkehrsmittel wurde und das Leben der Menschen prägt.","en":"How cycling became a daily mode of transport in the Netherlands and how it shapes people's everyday lives."},"teaser":{"ar":"في هولندا، الدراجات أكثر من الناس، ومسارات مخصصة تمتد لآلاف الكيلومترات، والأطفال يذهبون إلى المدرسة وحدهم على الدراجة.","de":"In den Niederlanden gibt es mehr Fahrräder als Menschen, Tausende Kilometer Radwege und Kinder, die allein zur Schule radeln.","en":"In the Netherlands, bicycles outnumber people, dedicated paths stretch for thousands of kilometres, and children cycle to school alone."},"readingMinutes":1,"sections":{"ar":[{"heading":"الدراجة كوسيلة نقل أساسية","paragraphs":["تمتلك هولندا حوالي 36,000 كيلومتر من مسارات الدراجات المخصصة، والدراجات تفوق عدد السكان. لكن الأمر لا يتعلق بالترفيه فقط: في المدن الهولندية، نسبة كبيرة من الرحلات، وأغلب الرحلات إلى العمل أو المدرسة في بعض المناطق، تتم بالدراجة.","هذا الواقع لم يأتِ من فراغ. في السبعينيات، أدى الاستخدام المكثف للسيارات وارتفاع الوفيات على الطرق إلى احتجاجات وتحول في السياسة نحو مسارات دراجات محمية وتهدئة حركة المرور. ومنذ ذلك الحين، أصبحت الدراجة جزءًا من البنية التحتية والحياة اليومية."]},{"heading":"قوانين تحمي راكبي الدراجات","paragraphs":["يمنح قانون المرور الهولندي الأولوية لراكبي الدراجات في العديد من المواقف، وعادة ما يُعتبر السائقون مسؤولين في حالات الاصطدام مع الأطفال وراكبي الدراجات. هذا التشريع يعكس ثقافة تعطي الأولوية للضعفاء في الطريق.","يتعلم الأطفال ركوب الدراجة في سن مبكرة، وكثيرًا ما يذهبون إلى المدرسة وحدهم على الدراجة، وهو من أبرز الفروق التي يلاحظها الزوار. لكن الصورة لا تخلو من تباين: الغرب المنبسط يختلف عن الجنوب التلالي، وبعض المدن أفضل بكثير من غيرها، وهناك أيضًا ازدحام مروري وخلافات حول الدراجات الكهربائية والدراجات البخارية."]}],"de":[{"heading":"Das Fahrrad als Hauptverkehrsmittel","paragraphs":["Die Niederlande verfügen über rund 36.000 Kilometer eigene Radwege, und es gibt mehr Fahrräder als Einwohner. Dabei geht es nicht nur um Freizeit: In niederländischen Städten wird ein großer Teil aller Wege und in manchen Gegenden die Mehrheit der Arbeits- und Schulwege mit dem Rad zurückgelegt.","Das war nicht immer so. In den 1970er-Jahren führten massiver Autoverkehr und hohe Verkehrstote zu Protesten und einem politischen Umschwung hin zu geschützten Radwegen und Verkehrsberuhigung. Seitdem ist das Rad fester Bestandteil der Infrastruktur und des Alltags."]},{"heading":"Gesetze schützen Radfahrende","paragraphs":["Das niederländische Verkehrsrecht räumt Radfahrenden in vielen Situationen Vorrang ein, und Autofahrende haften bei Kollisionen mit Kindern und Radfahrenden in der Regel. Diese Regelung spiegelt eine Kultur wider, die die Schwächeren im Verkehr schützt.","Kinder lernen früh das Radfahren und fahren oft allein zur Schule – für Besucher einer der auffälligsten Unterschiede. Doch das Bild täuscht: Der flache Westen unterscheidet sich vom hügeligen Süden, manche Städte sind viel besser als andere, und auch die Niederlande haben starken Autoverkehr und Konflikte um E-Bikes und Roller."]}],"en":[{"heading":"Cycling as a primary mode of transport","paragraphs":["The Netherlands has around 36,000 km of dedicated cycle paths, and bicycles outnumber people. But it's not just recreation: in Dutch cities a large share of all trips, and a majority of trips to work or school in some areas, are made by bike.","This didn't happen by accident. In the 1970s, mass car use and road deaths prompted protests and a policy shift towards protected cycle lanes and traffic calming. Since then, the bike has become part of the infrastructure and everyday life."]},{"heading":"Laws that protect cyclists","paragraphs":["Dutch traffic law gives cyclists priority in many situations, and drivers are usually held liable in collisions with children and cyclists. This legislation reflects a culture that prioritises the vulnerable on the road.","Children learn to cycle early and often cycle to school alone, which is one of the most striking differences for visitors. But the image hides variation: the flat west is not the hilly south, some cities are far better than others, and the Netherlands also has heavy car traffic and conflicts over e-bikes and scooters."]}]},"context":{"countries":["NL"],"region":"Western Europe","continent":"europe","languages":["nl"],"period":"contemporary"},"tags":["cities-and-community","Western Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Cycling in the Netherlands","de":"Cycling in the Netherlands","en":"Cycling in the Netherlands"},"url":"https://en.wikipedia.org/wiki/Cycling_in_the_Netherlands","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Bicycle-friendly","de":"Bicycle-friendly","en":"Bicycle-friendly"},"url":"https://en.wikipedia.org/wiki/Bicycle-friendly","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طفل في الرابعة يركب دراجته بجانب أحد والديه على مسار منفصل إلى المدرسة، يوقف الدراجة عند الحامل، ثم يواصل الوالد طريقه إلى العمل بالدراجة.","de":"Ein vierjähriges Kind radelt neben einem Elternteil auf einem separaten Weg zur Schule, schließt das Rad am Ständer ab, und der Elternteil fährt mit dem Rad weiter zur Arbeit.","en":"A four-year-old cycles beside a parent on a separated path to school, locks the bike at the rack, and the parent continues to work by bike."},"misunderstanding":{"ar":"يعتقد البعض أن هولندا بلد الدراجات فقط، لكنها تعاني أيضًا من ازدحام السيارات والنزاعات حول المركبات الكهربائية.","de":"Manche halten die Niederlande für ein reines Fahrradparadies, doch es gibt auch dichten Autoverkehr und Konflikte um Elektro-Fahrzeuge.","en":"Some think the Netherlands is a pure cycling paradise, but it also has heavy car traffic and conflicts over electric vehicles."},"comparison":{"ar":"بينما تعتمد دول أخرى على السيارات في التنقل اليومي، جعلت هولندا الدراجة خيارًا آمنًا وعمليًا للجميع.","de":"Während andere Länder im Alltag aufs Auto setzen, machte die Niederlande das Rad zu einer sicheren und praktischen Option für alle.","en":"While other countries rely on cars for daily transport, the Netherlands made cycling a safe and practical option for everyone."}},{"id":"eur-030","version":2,"slug":"belgium-s-language-border-runs-through-daily-life","contentType":"note","category":"languages","title":{"ar":"حدود اللغة في بلجيكا وحياتها اليومية","de":"Belgiens Sprachgrenze im Alltag","en":"Belgium's language border runs through daily life"},"deck":{"ar":"خط لغوي ثابت يقسم البلاد إلى مناطق، لكنه لا يمنع العائلات من عبوره يومياً في العمل والمدرسة والإعلام.","de":"Eine feste Sprachgrenze teilt das Land in Gebiete, doch Familien überqueren sie täglich bei Arbeit, Schule und Medien.","en":"A fixed language border divides the country into areas, yet families cross it daily for work, school and news."},"teaser":{"ar":"بلجيكا بثلاث لغات رسمية، لكن الحياة اليومية تُنظَّم حسب مناطق لغوية بحدود ثابتة، وهذا يظهر في الطرق والمدارس والأخبار.","de":"Belgien hat drei Amtssprachen, doch der Alltag ist nach Sprachgebieten mit fester Grenze organisiert – sichtbar an Straßen, Schulen und Nachrichten.","en":"Belgium has three official languages, but everyday life is organised by language areas with a fixed border – visible in roads, schools and news."},"readingMinutes":1,"sections":{"ar":[{"heading":"خط غير مرئي على الطريق","paragraphs":["في بلجيكا ثلاث لغات رسمية هي الهولندية والفرنسية والألمانية، لكن البلاد مقسّمة إلى مناطق لغوية ذات حدود ثابتة. ثُبِّتت هذه الحدود في 1962-1963، ثم حوّلت الإصلاحات الدستورية من 1970 فصاعداً بلجيكا إلى دولة فيدرالية بمجتمعات فلمنكية وفرنكوفونية وناطقة بالألمانية.","يصف المثال راكباً يعبر حدوداً بلدية غير مرئية نحو بروكسل فيلاحظ تغيّر لافتات الطريق ولغة الإدارة المحلية، مع أن الشوارع تبدو متطابقة. الحدود إدارية وسياسية لا فاصل ثقافي حاد، فكثير من العائلات ثنائية اللغة، وبروكسل أكثر اختلاطاً مما يوحي الخريطة.","يختلف هذا الواقع بين الأجيال والمناطق: شبان في المدن الكبرى يتنقلون بين اللغتين بسلاسة، بينما يبقى في البلديات الريفية تمسّك أكبر بلغة واحدة."]},{"heading":"مؤسسات منفصلة وأخبار مختلفة","paragraphs":["الأحزاب السياسية والجامعات والمدارس والإعلام منظّمة بشكل منفصل حسب اللغة، لذا كثيراً ما تستهلك المجموعتان الرئيسيتان أخباراً مختلفة وتناقشان قضايا مختلفة.","بروكسل رسمياً ثنائية اللغة، لكن الفرنسية تهيمن عملياً، والبلديات الفلمنكية المحيطة لديها «تسهيلات» للناطقين بالفرنسية تظل محل جدل سياسي.","بدأت الحركة الفلمنكية في القرن التاسع عشر وناضلت من أجل مساواة الهولندية بالفرنسية في التعليم والإدارة والحياة العامة، ولا تزال آثار ذلك النضال حاضرة في النقاش اليومي."]}],"de":[{"heading":"Eine unsichtbare Linie auf der Straße","paragraphs":["Belgien hat drei Amtssprachen – Niederländisch, Französisch und Deutsch –, ist aber in Sprachgebiete mit fester Grenze unterteilt. Diese wurde 1962–63 festgelegt; Verfassungsreformen ab 1970 machten Belgien zu einem föderalen Staat mit flämischer, französischsprachiger und deutschsprachiger Gemeinschaft.","Ein Pendler überquert auf dem Weg nach Brüssel eine unsichtbare Gemeindegrenze und bemerkt, dass sich Straßenschilder und die Sprache der Verwaltung ändern, obwohl die Straßen gleich aussehen. Die Grenze ist verwaltungstechnisch und politisch, keine scharfe kulturelle Trennlinie: Viele Familien sind zweisprachig, Brüssel ist gemischter als die Karte vermuten lässt.","Regional und generationell unterscheidet sich das: Jüngere in großen Städten wechseln fließend zwischen den Sprachen, während man in ländlichen Gemeinden stärker an einer Sprache festhält."]},{"heading":"Getrennte Institutionen, andere Nachrichten","paragraphs":["Parteien, Universitäten, Schulen und Medien sind sprachlich getrennt organisiert, sodass die beiden Hauptgemeinschaften oft unterschiedliche Nachrichten konsumieren und über andere Themen debattieren.","Brüssel ist offiziell zweisprachig, praktisch dominiert jedoch Französisch; die umliegenden flämischen Gemeinden haben „Erleichterungen“ für Französischsprachige, die politisch umstritten bleiben.","Die Flämische Bewegung des 19. Jahrhunderts kämpfte für die Gleichstellung des Niederländischen mit dem Französischen in Bildung, Verwaltung und öffentlichem Leben – ein Erbe, das die Debatten bis heute prägt."]}],"en":[{"heading":"An invisible line on the road","paragraphs":["Belgium has three official languages – Dutch, French and German – but the country is divided into language areas with a fixed border. The border was fixed in 1962–63, and constitutional reforms from 1970 turned Belgium into a federal state with separate Flemish, French-speaking and German-speaking communities.","A commuter crosses an invisible municipal boundary on the way to Brussels and notices that road signs and the language of local government change, even though the streets look identical. The border is administrative and political, not a sharp cultural divide: many families are bilingual, and Brussels is far more mixed than the map suggests.","This varies by region and generation: younger people in big cities move smoothly between languages, while rural municipalities tend to hold more firmly to one language."]},{"heading":"Separate institutions, different news","paragraphs":["Political parties, universities, schools and media are organised separately by language, so the two main communities often consume different news and debate different issues.","Brussels is officially bilingual, but in practice French dominates, and the surrounding Flemish municipalities have 'facilities' for French speakers that remain politically contested.","The Flemish Movement, which began in the 19th century, fought for Dutch to have equal status with French in education, administration and public life – a legacy still present in everyday debate."]}]},"context":{"countries":["BE"],"region":"Western Europe","continent":"europe","languages":["nl","fr","de"],"period":"contemporary"},"tags":["languages","Western Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Languages of Belgium","de":"Languages of Belgium","en":"Languages of Belgium"},"url":"https://en.wikipedia.org/wiki/Languages_of_Belgium","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Flemish Movement","de":"Flemish Movement","en":"Flemish Movement"},"url":"https://en.wikipedia.org/wiki/Flemish_Movement","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يعبر راكب حدوداً بلدية غير مرئية في طريقه إلى بروكسل، فيلاحظ تغيّر لافتات الطريق ولغة الإدارة المحلية رغم أن الشوارع تبدو متطابقة.","de":"Ein Pendler überquert auf dem Weg nach Brüssel eine unsichtbare Gemeindegrenze und bemerkt, dass Straßenschilder und Verwaltungssprache wechseln, obwohl die Straßen identisch aussehen.","en":"A commuter crosses an invisible municipal boundary on the way to Brussels and notices that the road signs and the language of the local government change, even though the streets look identical."},"misunderstanding":{"ar":"يظن كثيرون أن الحدود اللغوية فاصل ثقافي حاد بين مجموعتين متجانستين، مع أن الواقع أكثر اختلاطاً، وكثير من العائلات ثنائية اللغة.","de":"Viele halten die Sprachgrenze für eine scharfe kulturelle Trennlinie zwischen homogenen Gruppen, obwohl die Realität gemischter ist und viele Familien zweisprachig sind.","en":"Many assume the language border is a sharp cultural divide between homogeneous groups, when in reality it is more mixed and many families are bilingual."},"comparison":{"ar":"بينما تُنظَّم المؤسسات والإعلام حسب اللغة، تبقى الحياة اليومية في المدن مليئة بالتبادل والتعدد اللغوي.","de":"Während Institutionen und Medien nach Sprache getrennt sind, bleibt der Alltag in den Städten von Austausch und Mehrsprachigkeit geprägt.","en":"While institutions and media are organised by language, daily life in cities remains full of exchange and multilingualism."},"expression":{"original":"Goeiedag / Bonjour","language":"Nederlands / Français","gloss":{"ar":"تحية نهارية: صباح الخير أو مرحباً","de":"Guten Tag (Niederländisch) / Hallo (Französisch)","en":"Good day (Dutch) / hello (French)"},"usage":{"ar":"تُستخدم عند اللقاء نهاراً، واختيار إحداهما في بروكسل قد يعكس اللغة المفضّلة لدى المتحدث.","de":"Eine Tagesgrußformel; in Brüssel kann die Wahl verraten, welche Sprache der Sprecher bevorzugt.","en":"A daytime greeting; in Brussels the choice may signal which language the speaker prefers."},"transliteration":"goeiedag / bonjour"}},{"id":"eur-031","version":2,"slug":"the-stammtisch-a-table-reserved-for-belonging","contentType":"note","category":"social-behaviour","title":{"ar":"طاولة المعتادين: مكان للانتماء","de":"Der Stammtisch: ein Tisch für Zugehörigkeit","en":"The Stammtisch: a table for belonging"},"deck":{"ar":"في الحانات الألمانية تُحجز طاولة كل أسبوع لجماعة ثابتة، فتصير مجلساً غير رسمي للحديث واللعب والدعم.","de":"In deutschen Gaststuben ist ein Tisch jede Woche für dieselbe Gruppe reserviert – ein informelles Parlament und Netzwerk.","en":"In German pubs one table is reserved every week for the same group — an informal village parliament and support network."},"teaser":{"ar":"طاولة واحدة في زاوية الحانة تجمع الرجال أنفسهم كل خميس، فتصبح برلمان القرية الصغير وشبكة دعمها اليومي.","de":"Acht Männer, ein Ecktisch, jeden Donnerstag: Der Stammtisch macht aus einem Wirtshaus ein kleines Dorfparlament und ein Netzwerk.","en":"Eight men, one corner table, every Thursday: the Stammtisch turns a village pub into a small parliament and a quiet support network."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس أسبوعي ثابت","paragraphs":["في حانة قرية بجنوب ألمانيا يجلس الرجال الثمانية أنفسهم إلى الطاولة الركنية كل خميس، يلعبون الورق ويتجادلون في شؤون المجلس البلدي، ويحجزون الطاولة بلوحة خشبية صغيرة.","كلمة «شتامتيش» تعني «طاولة المعتادين»، وقد ازدهر هذا التقليد في القرن التاسع عشر مع الأندية والجوقات وجمعيات الرماية.","كانت الطاولة تقليدياً للرجال وحدهم، مكاناً للعب السكات والشافكوبف والشرب والنقاش السياسي والفلسفي الطويل."]},{"heading":"من البرلمان إلى السخرية","paragraphs":["ما زال الطقس شائعاً في البلدات الصغيرة والأندية، وقد يعمل برلماناً قروياً غير رسمي أو شبكة دعم.","أما تعبيرا «شتامتيشبوليتيك» و«شتامتيشنيفو» فيحملان سخرية خفيفة من الحديث السياسي المبسّط والجازم.","يتراجع التقليد في المدن الكبيرة وبين الشباب، والصورة النمطية للرجال والبيرة والسياسة مبالغة؛ فكثير من الجماعات اليوم تضم نساءً وتجتمع لأسباب أخرى، ويختلف الأمر بين الأجيال والمناطق."]}],"de":[{"heading":"Ein fester Wochentermin","paragraphs":["In einem schwäbischen Dorfgasthaus sitzen dieselben acht Männer jeden Donnerstag am Ecktisch, spielen Karten, streiten über den Gemeinderat und reservieren den Tisch mit einem kleinen Holzschild.","Das Wort bedeutet „Tisch der Stammgäste“, und die Einrichtung blühte im 19. Jahrhundert auf, zusammen mit Vereinen, Chören und Schützengesellschaften.","Traditionell war der Stammtisch eine reine Männerrunde, ein Ort für Skat oder Schafkopf, für Bier und lange politische oder philosophische Debatten."]},{"heading":"Vom Dorfparlament zur Redewendung","paragraphs":["Der Brauch ist in kleineren Städten und Vereinen noch verbreitet und kann als informelles Dorfparlament oder Unterstützungsnetz wirken.","Die Begriffe „Stammtischpolitik“ und „Stammtischniveau“ sind leicht abwertend und meinen vereinfachte, meinungsstarke Politik.","In Großstädten und bei Jüngeren geht der Stammtisch zurück, und das Bild von Männern, Bier und Politik ist eine Karikatur; viele Runden schließen heute Frauen ein und treffen sich aus anderen Gründen, regional und generationell verschieden."]}],"en":[{"heading":"A fixed weekly appointment","paragraphs":["In a Swabian village pub the same eight men occupy the corner table every Thursday, play cards, argue about the local council and reserve the table with a small wooden sign.","The word means 'regulars' table', and the institution flourished in the 19th century alongside clubs, choirs and shooting societies.","Traditionally all-male, the Stammtisch was a place for card games such as Skat or Schafkopf, drinking and long political or philosophical arguments."]},{"heading":"From village parliament to mild mockery","paragraphs":["The ritual is still common in smaller towns and clubs, and it can function as an informal village parliament or support network.","'Stammtischpolitik' and 'Stammtischniveau' are mildly derogatory terms for simplified, opinionated political talk of the kind heard at such tables.","The Stammtisch is declining in big cities and among younger people, and the all-male, beer-and-politics image is a caricature; many groups now include women and meet for other reasons, varying by region and generation."]}]},"context":{"countries":["DE"],"region":"Central Europe","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["social-behaviour","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Stammtisch","de":"Stammtisch","en":"Stammtisch"},"url":"https://en.wikipedia.org/wiki/Stammtisch","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Beer in Germany","de":"Beer in Germany","en":"Beer in Germany"},"url":"https://en.wikipedia.org/wiki/Beer_in_Germany","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حانة قرية بجنوب ألمانيا يحتل الرجال الثمانية أنفسهم الطاولة الركنية كل خميس، يلعبون الورق ويتجادلون في المجلس البلدي ويحجزون الطاولة بلوحة خشبية صغيرة.","de":"In einem schwäbischen Dorfgasthaus besetzen dieselben acht Männer jeden Donnerstag den Ecktisch, spielen Karten, streiten über den Gemeinderat und reservieren den Tisch mit einem kleinen Holzschild.","en":"In a Swabian village pub the same eight men occupy the corner table every Thursday, play cards, argue about the local council and reserve the table with a small wooden sign."},"misunderstanding":{"ar":"الصورة الشائعة عن طاولة رجال وبيرة وسياسة هي صورة نمطية مبالغ فيها؛ فكثير من هذه الجماعات يضم نساءً ويجتمع لأسباب اجتماعية أخرى.","de":"Das Klischee vom reinen Männer-, Bier- und Politikabend ist eine Karikatur; viele Stammtische sind heute gemischt und treffen sich aus ganz anderen Anlässen.","en":"The all-male, beer-and-politics image is a caricature; many Stammtische today are mixed and meet for entirely different reasons."},"comparison":{"ar":"يشبه هذا الطقس مجالس الحي الدورية في مدن عربية، حيث تتحول طاولة أو ديوان إلى مكان للنقاش وحل المشكلات الصغيرة.","de":"Ähnlich wie ein regelmäßiger Stammtisch im Vereinsheim funktionieren Nachbarschaftsrunden anderswo, die Woche für Woche dieselben Menschen zusammenbringen.","en":"It resembles regular neighbourhood gatherings elsewhere that bring the same people together week after week around one table."}}];

